'use server';

import { createClient } from '@/lib/supabase/server';
import { revalidatePath } from 'next/cache';
import { redirect } from 'next/navigation';
import { z } from 'zod';
import { checkServerActionRateLimit } from '@/lib/security';
import { verifyOrigin } from '@/lib/security/csrf';

const loginSchema = z.object({
    email: z.string().email(),
    password: z.string().min(6),
});

const signupSchema = z.object({
    email: z.string().email(),
    password: z.string().min(6),
    restaurantName: z
        .string()
        .trim()
        .min(2)
        .max(120)
        .optional()
        .or(z.literal(''))
        .transform(value => (value ? value : undefined)),
});

export async function login(prevState: unknown, formData: FormData) {
    // CSRF Protection - verify origin before processing
    await verifyOrigin();

    // Check rate limit for auth actions (login)
    const rateLimit = await checkServerActionRateLimit('auth');
    if (!rateLimit.allowed) {
        return { error: `Too many login attempts. Please wait ${rateLimit.retryAfter} seconds.` };
    }

    const email = formData.get('email') as string;
    const password = formData.get('password') as string;

    const validatedFields = loginSchema.safeParse({
        email,
        password,
    });

    if (!validatedFields.success) {
        return { error: 'Invalid fields' };
    }

    const supabase = await createClient();

    const { error } = await supabase.auth.signInWithPassword({
        email,
        password,
    });

    if (error) {
        return { error: error.message };
    }

    revalidatePath('/', 'layout');
    redirect('/auth/post-login');
}

export async function signup(prevState: unknown, formData: FormData) {
    // CSRF Protection - verify origin before processing
    await verifyOrigin();

    // Check rate limit for auth actions (signup)
    const rateLimit = await checkServerActionRateLimit('auth');
    if (!rateLimit.allowed) {
        return { error: `Too many signup attempts. Please wait ${rateLimit.retryAfter} seconds.` };
    }

    const email = formData.get('email') as string;
    const password = formData.get('password') as string;
    const restaurantName = (formData.get('restaurant_name') as string | null) ?? '';

    const validatedFields = signupSchema.safeParse({
        email,
        password,
        restaurantName,
    });

    if (!validatedFields.success) {
        return { error: 'Invalid fields' };
    }

    const supabase = await createClient();
    const { data, error } = await supabase.auth.signUp({
        email: validatedFields.data.email,
        password: validatedFields.data.password,
        options: {
            data: {
                restaurant_name: validatedFields.data.restaurantName || undefined,
            },
        },
    });

    if (error) {
        return { error: error.message };
    }

    revalidatePath('/', 'layout');

    if (data.session) {
        redirect('/auth/post-login');
    }

    return { error: null, message: 'Account created. Check your email to confirm sign-up.' };
}

export async function logout() {
    // CSRF Protection - verify origin before processing
    await verifyOrigin();

    const supabase = await createClient();
    await supabase.auth.signOut();
    revalidatePath('/', 'layout');
    redirect('/');
}

import { NextResponse } from 'next/server';
// The client you created from the Server-Side Auth instructions
import { createClient } from '@/lib/supabase/server';
import { validateForwardedHost } from '@/lib/security/host-validation';

/**
 * Validates redirect path to prevent open redirect attacks (CRIT-002)
 * Only allows relative paths starting with / and validates against allowlist
 */
function validateRedirectPath(path: string): string {
    if (path.startsWith('/') && !path.startsWith('//')) {
        const allowedPrefixes = ['/auth/', '/merchant/', '/kds/', '/app/'];
        if (allowedPrefixes.some(prefix => path.startsWith(prefix))) {
            return path;
        }
    }
    return '/auth/post-login';
}

export async function GET(request: Request) {
    const { searchParams, origin } = new URL(request.url);
    const code = searchParams.get('code');
    // if "next" is in param, use it as the redirect URL
    // Validate the redirect path to prevent open redirect attacks (CRIT-002)
    const rawNext = searchParams.get('next') ?? '/auth/post-login';
    const next = validateRedirectPath(rawNext);

    if (code) {
        const supabase = await createClient();
        const { error } = await supabase.auth.exchangeCodeForSession(code);
        if (!error) {
            // HIGH-008: Validate x-forwarded-host using centralized validation
            const forwardedHost = request.headers.get('x-forwarded-host');
            const validation = validateForwardedHost(forwardedHost, request);

            // Determine the safe host to use
            if (validation.valid && validation.host) {
                // Use validated forwarded host
                return NextResponse.redirect(`https://${validation.host}${next}`);
            } else {
                // Fall back to origin (uses request's validated host)
                return NextResponse.redirect(`${origin}${next}`);
            }
        }
    }

    // return the user to an error page with instructions
    return NextResponse.redirect(`${origin}/auth/auth-code-error`);
}

'use client';

import { useState } from 'react';
import { toast } from 'react-hot-toast';
import { useRouter } from 'next/navigation';
import { acceptInvite } from '@/app/(auth)/invite/actions';

export function InviteAcceptButton({ code }: { code: string }) {
    const [loading, setLoading] = useState(false);
    const router = useRouter();

    const handleAccept = async () => {
        try {
            setLoading(true);
            const result = await acceptInvite(code);

            if (result?.error) {
                toast.error(result.error);
            } else {
                toast.success('Invitation accepted! Setting up profile...');
                router.push('/merchant/onboarding/staff');
            }
        } catch (e) {
            toast.error('An unexpected error occurred. Please try again.');
            console.error(e);
        } finally {
            setLoading(false);
        }
    };

    return (
        <button
            onClick={handleAccept}
            disabled={loading}
            className="w-full rounded-xl bg-blue-600 py-3 text-sm font-semibold text-white shadow-lg shadow-blue-500/20 transition-all hover:bg-blue-700 hover:shadow-blue-500/40 active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-70"
        >
            {loading ? 'Accepting...' : 'Accept Invitation'}
        </button>
    );
}

'use server';

import { createClient } from '@/lib/supabase/server';
import { createAuditedServiceRoleClient } from '@/lib/supabase/service-role';
import { revalidatePath } from 'next/cache';
import { verifyOrigin } from '@/lib/security/csrf';
import { logger } from '@/lib/logger';

const log = logger.child('auth:invite');

export async function acceptInvite(code: string) {
    // CSRF Protection - verify origin before processing
    await verifyOrigin();

    const supabase = await createClient();
    const {
        data: { user },
        error: userError,
    } = await supabase.auth.getUser();

    if (userError || !user) {
        return { error: 'You must be logged in to accept an invite.' };
    }

    // 1. Fetch the invite
    // HIGH-013: Explicit column selection
    const { data: invite, error: inviteError } = await supabase
        .from('staff_invites')
        .select('id, restaurant_id, role, status, expires_at')
        .eq('code', code)
        .single();

    if (inviteError || !invite) {
        return { error: 'Invalid or expired invite code.' };
    }

    if (invite.status !== 'pending') {
        return { error: 'This invite has already been used.' };
    }

    if (new Date(invite.expires_at) < new Date()) {
        return { error: 'This invite has expired.' };
    }

    // 2. Add to restaurant_staff
    // Check if already a member?
    const { data: existingStaff } = await supabase
        .from('restaurant_staff')
        .select('id')
        .eq('restaurant_id', invite.restaurant_id)
        .eq('user_id', user.id)
        .single();

    if (existingStaff) {
        // Already a member? Maybe update role?
        // For now, let's just say "You are already a member".
        // Or update role if that was the intent.
        // Let's assume we update role if different?
        // But usually we just return success or error.
        return { error: 'You are already a staff member of this restaurant.' };
    }

    // HIGH-010: Use audited service role client for staff insertion
    const adminClient = createAuditedServiceRoleClient('invite-actions', {
        userId: user.id,
        restaurantId: invite.restaurant_id,
    });
    const { error: insertError } = await adminClient.from('restaurant_staff').insert({
        restaurant_id: invite.restaurant_id,
        user_id: user.id,
        role: invite.role,
        is_active: true,
        // invited_by: invite.created_by -- if we had this col
    });

    if (insertError) {
        log.error('Failed to add staff member', insertError);
        return { error: 'Failed to join restaurant. Please try again.' };
    }

    // 3. Update invite status
    await supabase
        .from('staff_invites')
        .update({ status: 'accepted' }) // or 'used'
        .eq('id', invite.id);

    // 4. Return success (client handles navigation)
    revalidatePath('/', 'layout');
    return { success: true };
}

import { redirect } from 'next/navigation';
import Link from 'next/link';
import { createClient } from '@/lib/supabase/server';
import { InviteAcceptButton } from './InviteAcceptButton';
import { verifyOrigin } from '@/lib/security/csrf';

export default async function InvitePage(props: { searchParams: Promise<{ code: string }> }) {
    const searchParams = await props.searchParams;
    const { code } = searchParams;

    if (!code) {
        redirect('/');
    }

    const supabase = await createClient();
    const {
        data: { user },
    } = await supabase.auth.getUser();

    // Fetch Invite Details
    const { data: invite, error } = await supabase
        .from('staff_invites')
        .select(
            `
            *,
            restaurant:restaurants (
                name
            )
        `
        )
        .eq('code', code)
        .single();

    if (error || !invite) {
        return (
            <div className="flex min-h-screen flex-col items-center justify-center bg-gray-50 p-4 text-center dark:bg-zinc-900">
                <div className="rounded-xl border border-gray-200 bg-white p-8 shadow-xl dark:border-zinc-800 dark:bg-zinc-950">
                    <h1 className="mb-2 text-2xl font-bold text-red-600">Invalid Invite</h1>
                    <p className="text-gray-600 dark:text-gray-400">
                        This invite link is invalid or has expired.
                    </p>
                    <Link
                        href="/"
                        className="bg-brand-accent mt-6 inline-block rounded-lg px-6 py-2 text-sm font-medium text-black transition hover:brightness-105 dark:bg-white dark:text-black dark:hover:bg-gray-200"
                    >
                        Go Home
                    </Link>
                </div>
            </div>
        );
    }

    const restaurantName = invite.restaurant?.name ?? 'Unknown Restaurant';
    const isExpired = new Date(invite.expires_at) < new Date();
    const isUsed = invite.status !== 'pending';

    if (isExpired || isUsed) {
        return (
            <div className="flex min-h-screen flex-col items-center justify-center bg-gray-50 p-4 text-center dark:bg-zinc-900">
                <div className="rounded-xl border border-gray-200 bg-white p-8 shadow-xl dark:border-zinc-800 dark:bg-zinc-950">
                    <h1 className="mb-2 text-2xl font-bold text-red-600">Invite No Longer Valid</h1>
                    <p className="text-gray-600 dark:text-gray-400">
                        {isUsed ? 'This invite has already been used.' : 'This invite has expired.'}
                    </p>
                    <Link
                        href="/"
                        className="bg-brand-accent mt-6 inline-block rounded-lg px-6 py-2 text-sm font-medium text-black transition hover:brightness-105 dark:bg-white dark:text-black dark:hover:bg-gray-200"
                    >
                        Go Home
                    </Link>
                </div>
            </div>
        );
    }

    return (
        <div className="flex min-h-screen flex-col items-center justify-center bg-gray-50 p-6 dark:bg-zinc-900">
            <div className="w-full max-w-md overflow-hidden rounded-xl border border-gray-200 bg-white shadow-xl dark:border-zinc-800 dark:bg-zinc-950">
                <div className="p-8 text-center">
                    <div className="mx-auto mb-6 flex h-16 w-16 items-center justify-center rounded-full bg-blue-50 text-3xl dark:bg-blue-900/20">
                        ≡ƒæï
                    </div>

                    <h1 className="mb-2 text-2xl font-bold text-gray-900 dark:text-white">
                        You&apos;ve been invited!
                    </h1>

                    <p className="mb-6 text-gray-600 dark:text-gray-400">
                        Join{' '}
                        <span className="font-semibold text-gray-900 dark:text-white">
                            {restaurantName}
                        </span>{' '}
                        as a{' '}
                        <span className="font-medium text-blue-600 capitalize dark:text-blue-400">
                            {invite.role}
                        </span>
                        .
                    </p>

                    {user ? (
                        <div className="space-y-4">
                            <p className="text-sm text-gray-500 dark:text-gray-400">
                                Logged in as{' '}
                                <span className="font-medium text-gray-900 dark:text-white">
                                    {user.email}
                                </span>
                            </p>

                            <InviteAcceptButton code={code} />

                            <form
                                action={async () => {
                                    'use server';
                                    await verifyOrigin();
                                    const supabase = await createClient();
                                    await supabase.auth.signOut();
                                    redirect(`/login?next=/invite?code=${code}`);
                                }}
                            >
                                <button className="text-sm text-gray-500 hover:text-gray-900 hover:underline dark:text-gray-400 dark:hover:text-white">
                                    Not you? Switch account
                                </button>
                            </form>
                        </div>
                    ) : (
                        <div className="space-y-3">
                            <Link
                                href={`/login?next=/invite?code=${code}`}
                                className="bg-brand-accent block w-full rounded-xl py-3 text-center text-sm font-semibold text-black shadow-lg transition-all hover:shadow-gray-500/20 hover:brightness-105 active:scale-[0.98] dark:bg-white dark:text-black dark:hover:bg-gray-200"
                            >
                                Log in to Accept
                            </Link>
                            <Link
                                href={`/signup?next=/invite?code=${code}`}
                                className="block w-full rounded-xl border border-gray-200 bg-white py-3 text-center text-sm font-semibold text-gray-900 transition-all hover:bg-gray-50 active:scale-[0.98] dark:border-zinc-700 dark:bg-zinc-900 dark:text-white dark:hover:bg-zinc-800"
                            >
                                Create Account
                            </Link>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

'use client';

import { Suspense, useEffect, useState } from 'react';
import { useSearchParams } from 'next/navigation';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Loader2, Tablet } from 'lucide-react';
import { toast } from 'react-hot-toast';
import { provisionDevice } from './actions';

function DeviceProvisioningContent() {
    const searchParams = useSearchParams();
    const [loading, setLoading] = useState(false);

    const code = searchParams.get('code');
    const role = (searchParams.get('role') ?? '').toLowerCase();
    const inviteLabel = searchParams.get('label');
    const targetModule =
        role === 'kitchen' || role === 'bar'
            ? '/kds/display'
            : role === 'waiter'
              ? '/waiter'
              : '/merchant';

    // Form State
    const [password, setPassword] = useState('');
    const [deviceName, setDeviceName] = useState(inviteLabel ?? '');

    useEffect(() => {
        if (!code) {
            toast.error('Invalid setup link');
            return;
        }
        // Ideally fetch invite details here purely for display
        // For now, we'll infer role from params if available or fetch via server action check
    }, [code]);

    const handleSetup = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);

        try {
            if (!code) throw new Error('No setup code found');

            const result = await provisionDevice({
                code,
                password,
                deviceName: deviceName || `Device-${Math.floor(Math.random() * 1000)}`,
            });

            if (result.error) {
                toast.error(result.error);
            } else {
                toast.success('Device Provisioned Successfully!');
                window.location.replace(result.redirectTo);
            }
        } catch (err: unknown) {
            const message = err instanceof Error ? err.message : 'Setup failed';
            toast.error(message);
        } finally {
            setLoading(false);
        }
    };

    if (!code) {
        return (
            <div className="flex min-h-screen flex-col items-center justify-center p-4">
                <div className="space-y-4 text-center">
                    <h1 className="text-2xl font-bold text-red-600">Invalid Link</h1>
                    <p className="text-gray-500">This setup link is missing a code.</p>
                </div>
            </div>
        );
    }

    return (
        <div className="flex min-h-screen flex-col items-center justify-center bg-gray-50 p-4">
            <div className="w-full max-w-md space-y-8 rounded-xl border border-gray-100 bg-white p-8 shadow-xl">
                {/* Header */}
                <div className="space-y-2 text-center">
                    <div className="mx-auto mb-6 flex h-16 w-16 items-center justify-center rounded-xl bg-blue-50">
                        <Tablet className="h-8 w-8 text-blue-600" />
                    </div>
                    <h1 className="text-2xl font-bold tracking-tight text-gray-900">
                        Device Provisioning
                    </h1>
                    <p className="text-sm text-gray-500">
                        Configure this access key and install the assigned module.
                    </p>
                    <p className="text-xs font-semibold text-blue-700">Target: {targetModule}</p>
                </div>

                <form onSubmit={handleSetup} className="space-y-6">
                    <div className="space-y-4">
                        {/* Device Name Input */}
                        <div>
                            <label className="mb-1 block text-sm font-medium text-gray-700">
                                Device Name
                            </label>
                            <Input
                                type="text"
                                placeholder="e.g. Kitchen Display 1, Waiter Phone"
                                value={deviceName}
                                onChange={e => setDeviceName(e.target.value)}
                                required
                                className="h-12"
                            />
                        </div>

                        {/* Password / Access Code */}
                        <div>
                            <label className="mb-1 block text-sm font-medium text-gray-700">
                                Create Access PIN / Password
                            </label>
                            <Input
                                type="password"
                                placeholder="********"
                                value={password}
                                onChange={e => setPassword(e.target.value)}
                                required
                                minLength={6}
                                className="h-12"
                            />
                            <p className="mt-1 text-xs text-gray-500">
                                This will be used to unlock this device session.
                            </p>
                        </div>
                    </div>

                    <Button
                        type="submit"
                        disabled={loading}
                        className="h-12 w-full bg-blue-600 text-base font-semibold hover:bg-blue-700"
                    >
                        {loading ? (
                            <>
                                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                Provisioning...
                            </>
                        ) : (
                            'Install & Connect'
                        )}
                    </Button>
                </form>

                <p className="text-center text-xs text-gray-400">
                    This device will be linked to your restaurant securely.
                </p>
            </div>
        </div>
    );
}

export default function DeviceProvisioningPage() {
    return (
        <Suspense
            fallback={
                <div className="flex h-screen items-center justify-center">
                    <Loader2 className="h-8 w-8 animate-spin text-gray-400" />
                </div>
            }
        >
            <DeviceProvisioningContent />
        </Suspense>
    );
}

import React from 'react';

// Force dynamic rendering for all auth pages to avoid build-time errors
export const dynamic = 'force-dynamic';

export default function AuthLayout({ children }: { children: React.ReactNode }) {
    return <>{children}</>;
}

'use client';

import { useMemo, useState } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { useRouter } from 'next/navigation';
import { motion } from 'framer-motion';
import { Mail, Lock, Eye, EyeOff } from 'lucide-react';
import { createClient } from '@/lib/supabase';

function getAuthErrorMessage(error: unknown): string {
    if (error instanceof Error) return error.message;
    if (typeof error === 'object' && error && 'message' in error) {
        const message = (error as { message?: unknown }).message;
        if (typeof message === 'string' && message.length > 0) return message;
    }
    return 'Unable to sign in. Please try again.';
}

export default function LoginPage() {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [oauthMessage, setOauthMessage] = useState<string | null>(null);
    const router = useRouter();
    const supabase = useMemo(() => createClient(), []);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError(null);
        setOauthMessage(null);

        try {
            const { data, error: signInError } = await supabase.auth.signInWithPassword({
                email: email.trim(),
                password,
            });

            if (signInError) throw signInError;
            if (!data.user) throw new Error('No authenticated user returned.');

            // Non-blocking role check: login success should not fail because of staff query parsing issues.
            const { data: staff } = await supabase
                .from('restaurant_staff')
                .select('role')
                .eq('user_id', data.user.id)
                .eq('is_active', true)
                .order('created_at', { ascending: true })
                .limit(1)
                .maybeSingle();

            if (staff?.role === 'kitchen') {
                router.push('/post-login');
            } else {
                router.push('/post-login');
            }
            router.refresh();
        } catch (submitError) {
            const message = getAuthErrorMessage(submitError);
            if (/email.*confirm/i.test(message)) {
                setError('Please confirm your email first, then sign in.');
            } else if (/invalid login credentials/i.test(message)) {
                setError('Incorrect email or password.');
            } else {
                setError(message);
            }
        } finally {
            setLoading(false);
        }
    };

    return (
        <main className="grid min-h-screen w-full grid-cols-1 lg:grid-cols-2">
            {/* Left Section: Form */}
            <section className="relative flex flex-col items-center justify-center bg-white px-6 py-12 lg:px-12">
                {/* Logo - Pinned Top Left */}
                <Link
                    href="/"
                    className="absolute top-8 left-8 flex h-8 w-24 items-center pl-1 lg:top-12 lg:left-12"
                >
                    <Image
                        src="/logo-black.svg"
                        alt="Lole"
                        width={96}
                        height={90}
                        className="pointer-events-none absolute top-1/2 left-0 h-[74px] w-auto max-w-none origin-left -translate-y-1/2 md:h-[90px]"
                        style={{ width: 'auto' }}
                        priority
                    />
                </Link>

                <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.4, ease: 'easeOut' }}
                    className="w-full max-w-[440px]"
                >
                    <h1 className="font-manrope text-center text-4xl font-bold tracking-tight text-black lg:text-left lg:text-4xl">
                        Welcome Back!
                    </h1>
                    <p className="font-manrope mt-3 text-center text-base leading-relaxed font-medium text-black/60 lg:text-left">
                        Sign in to access your dashboard and continue managing your restaurant.
                    </p>

                    <form onSubmit={handleSubmit} className="mt-8 space-y-5">
                        {error && (
                            <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-bold text-red-700">
                                {error}
                            </div>
                        )}
                        {oauthMessage && (
                            <div className="rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm font-bold text-amber-800">
                                {oauthMessage}
                            </div>
                        )}

                        <div className="space-y-2">
                            <label className="text-sm font-bold text-black/80">Email</label>
                            <div className="group relative">
                                <Mail className="absolute top-1/2 left-4 h-5 w-5 -translate-y-1/2 text-black/40 transition-colors group-focus-within:text-black" />
                                <input
                                    type="email"
                                    value={email}
                                    onChange={e => setEmail(e.target.value)}
                                    placeholder="Enter your email"
                                    className="font-manrope focus:border-brand-accent focus:ring-brand-accent/5 focus:shadow-brand-accent/10 w-full rounded-xl border border-black/15 bg-white px-12 py-3.5 text-base font-medium text-black transition-all outline-none placeholder:text-black/30 focus:shadow-lg focus:ring-4"
                                    required
                                />
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label className="text-sm font-bold text-black/80">Password</label>
                            <div className="group relative">
