function DemoMenuContent() {
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState<'food' | 'drinks'>('food');
    const [activeCategoryId, setActiveCategoryId] = useState('all');
    const [realItems, setRealItems] = useState<MenuItem[]>([]);
    const { addToCart, count } = useCart();

    useEffect(() => {
        async function fetchDemoMenu() {
            setLoading(true);
            const supabase = createClient();

            try {
                const { data: lastItem } = await supabase
                    .from('menu_items')
                    .select('restaurant_id')
                    .order('created_at', { ascending: false })
                    .limit(1)
                    .maybeSingle();

                let restaurantId = lastItem?.restaurant_id;
                let restaurants: { id: string; slug: string } | null = null;

                if (restaurantId) {
                    const { data } = await supabase
                        .from('restaurants')
                        .select('id, slug')
                        .eq('id', restaurantId)
                        .maybeSingle();
                    restaurants = data;
                } else {
                    const { data } = await supabase
                        .from('restaurants')
                        .select('id, slug')
                        .order('created_at', { ascending: false })
                        .limit(1)
                        .maybeSingle();
                    restaurants = data;
                    restaurantId = restaurants?.id;
                }

                if (!restaurantId || !restaurants) {
                    setRealItems([]);
                    setLoading(false);
                    return;
                }

                DEMO_CONTEXT.restaurant_id = restaurantId;
                if (restaurants.slug) DEMO_CONTEXT.slug = restaurants.slug;

                const { data: tableData } = await supabase
                    .from('tables')
                    .select('table_number')
                    .eq('restaurant_id', restaurantId)
                    .eq('is_active', true)
                    .limit(1)
                    .maybeSingle();

                DEMO_CONTEXT.table = tableData?.table_number ?? '1';

                const { data: categories, error: categoryError } = await supabase
                    .from('categories')
                    .select('id, name, section')
                    .eq('restaurant_id', restaurantId);

                if (categoryError) {
                    setRealItems([]);
                    return;
                }

                const typedCategories = (categories as RawCategory[]) ?? [];
                const categoryIds = typedCategories.map(c => c.id);
                const categoryById = new Map(typedCategories.map(c => [c.id, c]));

                if (categoryIds.length === 0) {
                    setRealItems([]);
                    return;
                }

                const { data: items, error: itemError } = await supabase
                    .from('menu_items')
                    .select(
                        'id, name, price, image_url, rating, preparation_time, description, description_am, popularity, likes_count, category_id'
                    )
                    .eq('is_available', true)
                    .in('category_id', categoryIds);

                if (itemError) {
                    setRealItems([]);
                    return;
                }

                const getSmartImageUrl = (path: string | null) => {
                    if (!path) return FALLBACK_IMAGE_URL;
                    if (path.startsWith('fab')) return path;
                    if (isAllowedRemoteImageUrl(path)) return path;
                    const { data } = supabase.storage.from('menu-images').getPublicUrl(path);
                    return data.publicUrl;
                };

                const formattedItems = ((items as RawMenuItem[]) || [])
                    .map((item: RawMenuItem): MenuItem | null => {
                        const category = categoryById.get(item.category_id);
                        if (!category) return null;

                        const constantItem = FOOD_ITEMS.find(
                            food =>
                                food.title.toLowerCase().trim() === item.name.toLowerCase().trim()
                        );

                        return {
                            id: item.id,
                            name: item.name,
                            title: item.name,
                            imageUrl: constantItem
                                ? constantItem.imageUrl
                                : getSmartImageUrl(item.image_url),
                            preparationTime: item.preparation_time || 15,
                            shopName: 'Saba Grill',
                            price: Number(item.price),
                            rating: item.rating ?? undefined,
                            categories: { name: category.name, section: category.section },
                            description: item.description ?? undefined,
                            description_am: item.description_am ?? undefined,
                            popularity: item.popularity ?? undefined,
                            likesCount: item.likes_count ?? undefined,
                        };
                    })
                    .filter((item): item is MenuItem => item !== null);

                setRealItems(formattedItems);
            } catch (error) {
                console.error('Demo menu error:', error);
                setRealItems([]);
            } finally {
                setLoading(false);
            }
        }

        fetchDemoMenu();
    }, []);

    const filteredItems = realItems.filter(item => {
        if (item.categories?.section !== activeTab) return false;
        if (activeCategoryId === 'all') return true;
        return item.categories?.name?.toLowerCase() === activeCategoryId.toLowerCase();
    });

    // ΓöÇΓöÇ Canvas ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    return (
        <main className="flex min-h-screen w-full items-center justify-center bg-[var(--background)]">
            {/*
             * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ
             *   BLANK CANVAS ΓÇö DEMO TABLE DESIGN GOES HERE
