            if (table === 'table_sessions') {
                return {
                    select: () => ({
                        eq: vi.fn().mockReturnValue({
                            eq: vi.fn().mockReturnValue({
                                eq: vi.fn().mockReturnValue({
                                    maybeSingle: tableSessionMaybeSingle,
                                }),
                            }),
                        }),
                    }),
                    insert: tableSessionInsert,
                };
            }

            if (table === 'payment_sessions') {
                return {
                    delete: vi.fn().mockReturnValue({
                        eq: vi.fn().mockResolvedValue({ error: null }),
                    }),
                };
