import { NextRequest, NextResponse } from 'next/server';
import { createClient } from '@/lib/supabase/server';
import { resolveGuestContext } from '@/lib/security/guestContext';

export async function GET(request: NextRequest) {
    const slug = request.nextUrl.searchParams.get('slug');
    const table = request.nextUrl.searchParams.get('table');
    const sig = request.nextUrl.searchParams.get('sig');
    const exp = request.nextUrl.searchParams.get('exp');

    const supabase = await createClient();
    const context = await resolveGuestContext(supabase, { slug, table, sig, exp });

    if (!context.valid) {
        return NextResponse.json({ error: context.reason }, { status: context.status });
    }

    return NextResponse.json(
        {
            data: {
                restaurant_id: context.data.restaurantId,
                table_id: context.data.tableId,
                table_number: context.data.tableNumber,
                slug: context.data.slug,
                sig: context.data.signature,
                exp: context.data.expiresAt,
            },
        },
        { status: 200 }
    );
}

import { apiError, apiSuccess } from '@/lib/api/response';
import { createServiceRoleClient } from '@/lib/supabase/service-role';
import { listActiveDiscountsForRestaurant } from '@/lib/discounts/service';
import type { SupabaseClient } from '@supabase/supabase-js';
import type { Database } from '@/types/database';

export async function GET(request: Request) {
    const { searchParams } = new URL(request.url);
    const slug = searchParams.get('slug');

    if (!slug) {
        return apiError('slug is required', 400, 'MISSING_SLUG');
    }

    const admin = createServiceRoleClient();
    const { data: restaurant, error } = await admin
        .from('restaurants')
        .select('id')
        .eq('slug', slug)
        .maybeSingle();

    if (error) {
        return apiError(
            'Failed to resolve restaurant',
            500,
            'RESTAURANT_RESOLVE_FAILED',
            error.message
        );
    }

    if (!restaurant) {
        return apiError('Restaurant not found', 404, 'RESTAURANT_NOT_FOUND');
    }

    try {
        const discounts = await listActiveDiscountsForRestaurant(
            admin as SupabaseClient<Database>,
            restaurant.id,
            {
                excludeManagerApproval: true,
            }
        );
        return apiSuccess({ discounts });
    } catch (fetchError) {
        return apiError(
            'Failed to load discounts',
            500,
            'DISCOUNTS_FETCH_FAILED',
            fetchError instanceof Error ? fetchError.message : 'Unknown discount fetch error'
        );
    }
}

