import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';
import { createClient } from '@/lib/supabase/server';
import { createServiceRoleClient } from '@/lib/supabase/service-role';
import { resolveGuestContext } from '@/lib/security/guestContext';

const UpsertGuestSessionSchema = z.object({
    session_id: z.string().uuid().optional(),
    guest_context: z.object({
        slug: z.string().min(1),
        table: z.string().min(1),
        sig: z.string().min(1),
        exp: z.union([z.string(), z.number()]),
    }),
    source: z.enum(['qr', 'campaign_qr', 'direct_link', 'other']).optional(),
    skip_selected: z.boolean().optional().default(false),
});

export async function POST(request: NextRequest) {
    try {
        const body = await request.json();
        const parsed = UpsertGuestSessionSchema.safeParse(body);
        if (!parsed.success) {
            return NextResponse.json(
                { error: 'Invalid request payload', details: parsed.error.flatten() },
                { status: 400 }
            );
        }

        const supabase = await createClient();
        const guestContext = await resolveGuestContext(supabase, parsed.data.guest_context);
        if (!guestContext.valid) {
            return NextResponse.json(
                { error: guestContext.reason },
                { status: guestContext.status }
            );
        }

        const {
            data: { user },
        } = await supabase.auth.getUser();

        const authState = user ? 'authenticated' : 'guest';
        const now = new Date().toISOString();
        const db = createServiceRoleClient();

        if (parsed.data.session_id) {
            const { data: existingSession, error: sessionLookupError } = await db
                .from('guest_menu_sessions')
                .select('id, restaurant_id, table_id, auth_state')
                .eq('id', parsed.data.session_id)
                .maybeSingle();

            if (sessionLookupError) {
                return NextResponse.json({ error: sessionLookupError.message }, { status: 500 });
            }

            if (
                existingSession &&
                existingSession.restaurant_id === guestContext.data.restaurantId &&
                existingSession.table_id === guestContext.data.tableId
            ) {
                const patch: Record<string, unknown> = { last_seen_at: now };

                if (authState === 'authenticated' && user) {
                    patch.auth_state = 'authenticated';
                    patch.user_id = user.id;
                    if (existingSession.auth_state === 'guest') {
                        patch.converted_at = now;
                    }
                }

                if (parsed.data.skip_selected) {
                    patch.metadata = { skip_selected_at: now };
                }

                const { data: updatedSession, error: updateError } = await db
                    .from('guest_menu_sessions')
                    .update(patch)
                    .eq('id', existingSession.id)
                    .select('id, auth_state, user_id, started_at, last_seen_at')
                    .single();

                if (updateError) {
                    return NextResponse.json({ error: updateError.message }, { status: 500 });
                }

                return NextResponse.json({
                    data: {
                        session_id: updatedSession.id,
                        auth_state: updatedSession.auth_state,
                        is_authenticated: updatedSession.auth_state === 'authenticated',
                    },
                });
            }
        }

        const { data: createdSession, error: insertError } = await db
            .from('guest_menu_sessions')
            .insert({
                restaurant_id: guestContext.data.restaurantId,
                table_id: guestContext.data.tableId,
                table_number: guestContext.data.tableNumber,
                slug: guestContext.data.slug,
                source: parsed.data.source ?? 'qr',
                auth_state: authState,
                user_id: user?.id ?? null,
                converted_at: authState === 'authenticated' ? now : null,
                metadata: parsed.data.skip_selected ? { skip_selected_at: now } : {},
            })
            .select('id, auth_state')
            .single();

        if (insertError || !createdSession) {
            return NextResponse.json(
                { error: insertError?.message ?? 'Failed to create session.' },
                { status: 500 }
            );
        }

        return NextResponse.json({
            data: {
                session_id: createdSession.id,
                auth_state: createdSession.auth_state,
                is_authenticated: createdSession.auth_state === 'authenticated',
            },
        });
    } catch (error) {
        return NextResponse.json(
            {
                error: 'Internal server error',
                details: error instanceof Error ? error.message : 'Unknown error',
            },
            { status: 500 }
        );
    }
}

/**
 * GET /api/v1/guest-portal/track?slug=...&order_id=...&sig=...&exp=...&table=...
 *
 * Public guest order tracker endpoint.
 * - Uses the SERVICE ROLE client so RLS is bypassed for unauthenticated guests.
 * - Performs HMAC verification inline (same logic as verifySignedQRCode) so
 *   we don't need a user session to look up the restaurant/table.
 * - Returns the order + kds_order_items so guests can track live prep status.
 */
import { NextRequest } from 'next/server';
import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { verifySignedQRCode } from '@/lib/security/hmac';
import { createServiceRoleClient } from '@/lib/supabase/service-role';
import { logger } from '@/lib/logger';

const log = logger.child('[guest-portal/track]');

const TrackQuerySchema = z.object({
    slug: z.string().min(1).max(128),
    order_id: z.string().uuid(),
    // sig: 64 hex chars ΓÇö accept any length as-is; verifySignedQRCode handles validation
    sig: z.string().min(1),
    // exp comes in as a string from URL params; coerce to number
    exp: z.coerce.number().int().positive(),
    table: z.string().min(1).max(64),
});

export async function GET(request: NextRequest) {
    const url = request.nextUrl;

    const parsed = TrackQuerySchema.safeParse({
        slug: url.searchParams.get('slug'),
        order_id: url.searchParams.get('order_id'),
        sig: url.searchParams.get('sig'),
        exp: url.searchParams.get('exp'),
        table: url.searchParams.get('table'),
    });

    if (!parsed.success) {
        return apiError(
            `Invalid tracking parameters: ${parsed.error.issues.map(i => i.message).join(', ')}`,
            400,
            'INVALID_PARAMS'
        );
    }

    const { slug, order_id, sig, exp, table } = parsed.data;

    // ΓöÇΓöÇ 1. Verify HMAC signature ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    // This is the same check as resolveGuestContext but done without a DB
    // lookup, so unauthenticated guests can pass validation.
    const signatureCheck = verifySignedQRCode(slug, table, sig, exp);
    if (!signatureCheck.valid) {
        return apiError(
            signatureCheck.reason ?? 'Invalid or expired QR context',
            403,
            'INVALID_CONTEXT'
        );
    }

    // ΓöÇΓöÇ 2. Use service-role client (bypasses RLS ΓÇö required for public guests) ΓöÇ
    const supabase = createServiceRoleClient();

    // ΓöÇΓöÇ 3. Resolve restaurant by slug ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const { data: restaurant, error: restaurantError } = await supabase
        .from('restaurants')
        .select('id, is_active')
        .eq('slug', slug)
        .maybeSingle();

    if (restaurantError) {
        return apiError('Failed to resolve restaurant', 500, 'RESTAURANT_RESOLVE_FAILED');
    }
    if (!restaurant || restaurant.is_active === false) {
        return apiError('Restaurant not found or inactive', 404, 'RESTAURANT_NOT_FOUND');
    }

    const restaurantId = restaurant.id;

    // ΓöÇΓöÇ 4. Fetch the order ΓÇö must belong to this restaurant ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const { data: order, error: orderError } = await supabase
        .from('orders')
        .select('id, order_number, table_number, status, created_at, total_price')
        .eq('id', order_id)
        .eq('restaurant_id', restaurantId)
        .maybeSingle();

    if (orderError) {
        log.error('Order fetch failed', orderError);
        return apiError('Failed to fetch order', 500, 'ORDER_FETCH_FAILED');
    }
    if (!order) {
        return apiError('Order not found', 404, 'ORDER_NOT_FOUND');
    }

    // ΓöÇΓöÇ 5. Fetch KDS item-level statuses for live prep tracking ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    // kds_order_items may not exist yet if the KDS hasn't picked up the order;
    // return an empty array in that case ΓÇö tracker will poll again.
    const { data: kdsItems, error: kdsError } = await supabase
        .from('kds_order_items')
        .select('id, name, quantity, station, status, notes, modifiers, started_at, ready_at')
        .eq('order_id', order_id)
        .eq('restaurant_id', restaurantId)
        .order('created_at', { ascending: true });

    if (kdsError) {
        log.warn('kds_order_items fetch warning', { error: kdsError });
    }

    return apiSuccess({
        order: {
            id: order.id,
            order_number: order.order_number,
            table_number: order.table_number,
            status: order.status,
            created_at: order.created_at,
            total_price: Number(order.total_price ?? 0) / 100,
        },
        items: kdsItems ?? [],
    });
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { createServiceRoleClient } from '@/lib/supabase/service-role';
import { logger } from '@/lib/logger';

const log = logger.child('[verify-contact]');

const SendVerificationSchema = z.object({
    guestId: z.string().uuid().optional(),
    sessionId: z.string().uuid().optional(),
    phone: z.string().optional(),
    restaurantId: z.string().uuid().optional(),
    name: z.string().optional(),
    channel: z.enum(['sms', 'email']),
}).refine(data => data.guestId || (data.phone && data.restaurantId), {
    message: 'Either guestId or phone + restaurantId must be provided',
});

const VerifyContactSchema = z.object({
    guestId: z.string().uuid().optional(),
    sessionId: z.string().uuid().optional(),
    phone: z.string().optional(),
    restaurantId: z.string().uuid().optional(),
    code: z.string().length(6, 'Verification code must be 6 digits'),
}).refine(data => data.guestId || (data.phone && data.restaurantId), {
    message: 'Either guestId or phone + restaurantId must be provided',
});

/**
 * POST /api/v1/guest-portal/verify-contact
 * Send verification code to guest's contact
 */
export async function POST(request: Request) {
    try {
        const body = await request.json();
        const parsed = SendVerificationSchema.safeParse(body);

        if (!parsed.success) {
            return apiError('Invalid request', 400, 'INVALID_REQUEST', parsed.error.issues);
        }

        const { guestId, phone, restaurantId, name, channel } = parsed.data;
        const supabase = createServiceRoleClient();

        let guest;
        let currentGuestId = guestId;

        if (currentGuestId) {
            // Get guest by ID
            const { data, error: guestError } = await supabase
                .from('guests')
                .select(
                    'id, restaurant_id, name, phone, email, phone_hash, email_hash, metadata, is_vip, language, tags, visit_count, lifetime_value, notes, created_at, updated_at'
                )
                .eq('id', currentGuestId)
                .single();

            if (guestError || !data) {
                return apiError('Guest not found', 404, 'GUEST_NOT_FOUND');
            }
            guest = data;
        } else if (phone && restaurantId) {
            // Find or create guest by phone and restaurantId
            const { data: existingGuest, error: lookupError } = await supabase
                .from('guests')
                .select(
                    'id, restaurant_id, name, phone, email, phone_hash, email_hash, metadata, is_vip, language, tags, visit_count, lifetime_value, notes, created_at, updated_at'
                )
                .eq('restaurant_id', restaurantId)
                .eq('phone', phone)
                .maybeSingle();

            if (lookupError) {
                return apiError('Database error during guest lookup', 500, 'DB_ERROR', lookupError);
            }

            if (existingGuest) {
                guest = existingGuest;
                currentGuestId = existingGuest.id;
            } else {
                // Create new guest record
                const { data: newGuest, error: createError } = await supabase
                    .from('guests')
                    .insert({
                        restaurant_id: restaurantId,
                        phone: phone,
                        name: name || null,
                        is_verified: false,
                        metadata: {},
                    })
                    .select(
                        'id, restaurant_id, name, phone, email, phone_hash, email_hash, metadata, is_vip, language, tags, visit_count, lifetime_value, notes, created_at, updated_at'
                    )
                    .single();

                if (createError || !newGuest) {
                    return apiError('Failed to create guest record', 500, 'GUEST_CREATE_FAILED', createError);
                }
                guest = newGuest;
                currentGuestId = newGuest.id;
            }
        } else {
            return apiError('Insufficient parameters', 400, 'BAD_REQUEST');
        }

        // Generate verification code (6 digits)
        const code = Math.floor(100000 + Math.random() * 900000).toString();

        const metadata = guest.metadata || {};

        // Store code in guest metadata
        await supabase
            .from('guests')
            .update({
                metadata: {
                    ...metadata,
                    verification_code: code,
                    verification_expires: new Date(Date.now() + 10 * 60 * 1000).toISOString(),
                },
            })
            .eq('id', currentGuestId);

        // Send verification code
        if (channel === 'sms') {
            if (!guest.phone) {
                return apiError('No phone number on file', 400, 'NO_PHONE');
            }

            const { sendSms } = await import('@/lib/notifications/sms');
            const result = await sendSms(
                guest.phone,
                `Your lole verification code is: ${code}. This code expires in 10 minutes.`
            );

            if (!result.success) {
                return apiError('Failed to send SMS', 500, 'SMS_FAILED', result.error);
            }
        } else if (channel === 'email') {
            if (!guest.email) {
                return apiError('No email on file', 400, 'NO_EMAIL');
            }

            const { resend, EMAIL_FROM } = await import('@/lib/email/client');

            if (!resend) {
                return apiError('Email service not configured', 500, 'EMAIL_NOT_CONFIGURED');
            }

            try {
                await resend.emails.send({
                    from: EMAIL_FROM,
                    to: guest.email,
                    subject: 'Verify your contact info - lole',
                    html: `
            <div style="font-family: sans-serif; max-width: 600px; margin: 0 auto;">
              <h1 style="color: #0D3B40;">Verify your contact</h1>
              <p>Your verification code is:</p>
              <div style="font-size: 32px; font-weight: bold; letter-spacing: 8px; padding: 20px; background: #f5f5f5; border-radius: 8px;">
                ${code}
              </div>
              <p style="color: #666; font-size: 14px;">This code expires in 10 minutes.</p>
            </div>
          `,
                });
            } catch (emailError) {
                return apiError('Failed to send email', 500, 'EMAIL_FAILED', String(emailError));
            }
        }

        return apiSuccess({ message: 'Verification code sent' });
    } catch (error) {
        log.error('Error in verify-contact', error);
        return apiError('Internal server error', 500, 'INTERNAL_ERROR');
    }
}

/**
 * PATCH /api/v1/guest-portal/verify-contact
 * Verify the code entered by guest
 */
export async function PATCH(request: Request) {
    try {
        const body = await request.json();
        const parsed = VerifyContactSchema.safeParse(body);

        if (!parsed.success) {
            return apiError('Invalid request', 400, 'INVALID_REQUEST', parsed.error.issues);
        }

        const { guestId, sessionId, phone, restaurantId, code } = parsed.data;
        const supabase = createServiceRoleClient();

        let guest;
        let currentGuestId = guestId;

        if (currentGuestId) {
            // Get guest by ID
            const { data, error: guestError } = await supabase
                .from('guests')
                .select(
                    'id, restaurant_id, name, phone, email, phone_hash, email_hash, metadata, is_vip, language, tags, visit_count, lifetime_value, notes, created_at, updated_at'
                )
                .eq('id', currentGuestId)
                .single();

            if (guestError || !data) {
                return apiError('Guest not found', 404, 'GUEST_NOT_FOUND');
            }
            guest = data;
        } else if (phone && restaurantId) {
            // Find guest by phone and restaurantId
            const { data, error: lookupError } = await supabase
                .from('guests')
                .select(
                    'id, restaurant_id, name, phone, email, phone_hash, email_hash, metadata, is_vip, language, tags, visit_count, lifetime_value, notes, created_at, updated_at'
                )
                .eq('restaurant_id', restaurantId)
                .eq('phone', phone)
                .maybeSingle();

            if (lookupError || !data) {
                return apiError('Guest not found for this phone', 404, 'GUEST_NOT_FOUND');
            }
            guest = data;
            currentGuestId = data.id;
        } else {
            return apiError('Insufficient parameters', 400, 'BAD_REQUEST');
        }

        const metadata = guest.metadata || {};
        const storedCode = metadata.verification_code;
        const expires = metadata.verification_expires;

        // Check code
        if (!storedCode || storedCode !== code) {
            return apiError('Invalid verification code', 400, 'INVALID_CODE');
        }

        // Check expiry
        if (expires && new Date(expires) < new Date()) {
            return apiError('Verification code expired', 400, 'CODE_EXPIRED');
        }

        // Mark as verified
        await supabase
            .from('guests')
            .update({
                is_verified: true,
                metadata: {
                    ...metadata,
                    verification_code: null,
                    verification_expires: null,
                    verified_at: new Date().toISOString(),
                },
            })
            .eq('id', currentGuestId);

        // If a session ID was provided, update the guest_menu_sessions state
        if (sessionId) {
            await supabase
                .from('guest_menu_sessions')
                .update({
                    auth_state: 'verified',
                    metadata: {
                        verified_guest_id: currentGuestId,
                        verified_at: new Date().toISOString()
                    }
                })
                .eq('id', sessionId);
        }

        return apiSuccess({ 
            message: 'Contact verified successfully',
            guestId: currentGuestId,
            guest: {
                id: guest.id,
                name: guest.name,
                phone: guest.phone,
                email: guest.email,
            }
        });
    } catch (error) {
        log.error('Error in verify-contact PATCH', error);
        return apiError('Internal server error', 500, 'INTERNAL_ERROR');
    }
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { parseJsonBody } from '@/lib/api/validation';
import { writeAuditLog } from '@/lib/api/audit';
import { isIdempotencyKeyValid, resolveIdempotencyKey } from '@/lib/api/idempotency';
import type { Json } from '@/types/database';

const RuleIdSchema = z.string().uuid();

const AlertRulePatchSchema = z
    .object({
        name: z.string().trim().min(2).max(120).optional(),
        severity: z.enum(['low', 'medium', 'high', 'critical']).optional(),
        enabled: z.boolean().optional(),
        condition_json: z.record(z.string(), z.unknown()).optional(),
        target_json: z.record(z.string(), z.unknown()).optional(),
    })
    .refine(value => Object.keys(value).length > 0, {
        message: 'At least one field is required',
    });

export async function PATCH(
    request: Request,
    routeContext: { params: Promise<{ ruleId: string }> }
) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p1' });
    if (!context.ok) {
        return context.response;
    }

    const explicitIdempotencyKey = request.headers.get('x-idempotency-key');
    if (explicitIdempotencyKey && !isIdempotencyKeyValid(explicitIdempotencyKey)) {
        return apiError('Invalid idempotency key', 400, 'INVALID_IDEMPOTENCY_KEY');
    }
    const idempotencyKey = resolveIdempotencyKey(explicitIdempotencyKey);

    const parsedBody = await parseJsonBody(request, AlertRulePatchSchema);
    if (!parsedBody.success) {
        return parsedBody.response;
    }

    const { ruleId } = await routeContext.params;
    const parsedRuleId = RuleIdSchema.safeParse(ruleId);
    if (!parsedRuleId.success) {
        return apiError(
            'Invalid alert rule id',
            400,
            'INVALID_ALERT_RULE_ID',
            parsedRuleId.error.flatten()
        );
    }

    const { data: existing, error: fetchError } = await context.supabase
        .from('alert_rules')
        .select('id, name, severity, enabled, condition_json, target_json')
        .eq('id', parsedRuleId.data)
        .eq('restaurant_id', context.restaurantId)
        .maybeSingle();

    if (fetchError) {
        return apiError(
            'Failed to load alert rule',
            500,
            'ALERT_RULE_FETCH_FAILED',
            fetchError.message
        );
    }
    if (!existing) {
        return apiError('Alert rule not found', 404, 'ALERT_RULE_NOT_FOUND');
    }

    const updatePayload = {
        ...parsedBody.data,
        condition_json: parsedBody.data.condition_json as Json | undefined,
        target_json: parsedBody.data.target_json as Json | undefined,
    };

    const { data: updated, error: updateError } = await context.supabase
        .from('alert_rules')
        .update(updatePayload)
        .eq('id', parsedRuleId.data)
        .eq('restaurant_id', context.restaurantId)
        // HIGH-013: Explicit column selection
        .select(
            'id, restaurant_id, name, severity, enabled, condition_json, target_json, created_at, updated_at'
        )
        .single();

    if (updateError) {
        return apiError(
            'Failed to update alert rule',
            500,
            'ALERT_RULE_UPDATE_FAILED',
            updateError.message
        );
    }

    await writeAuditLog(context.supabase, {
        restaurant_id: context.restaurantId,
        user_id: auth.user.id,
        action: 'alert_rule_updated',
        entity_type: 'alert_rule',
        entity_id: updated.id,
        old_value: existing as unknown as Json,
        new_value: updated as unknown as Json,
        metadata: {
            source: 'merchant_dashboard',
            idempotency_key: idempotencyKey,
        },
    });

    return apiSuccess({ rule: updated, idempotency_key: idempotencyKey });
}

