            expires_at: expiresAt,
            status: 'pending',
        })
        // HIGH-013: Explicit column selection
        .select(
            'id, code, email, role, restaurant_id, created_by, expires_at, status, pin_code, created_at, updated_at'
        )
        .single();

    if (error) {
        return apiError(
            'Failed to create staff invite',
            500,
            'STAFF_INVITE_CREATE_FAILED',
            error.message
        );
    }

    // Fetch restaurant name for the email
    const { data: restaurant } = await context.supabase
        .from('restaurants')
        .select('name')
        .eq('id', context.restaurantId)
        .single();

    const inviteQuery = new URLSearchParams({ code, role: parsed.data.role });
    if (parsed.data.label) {
        inviteQuery.set('label', parsed.data.label);
    }
    const { getAppUrl } = await import('@/lib/config/env');
    const inviteUrl = `${getAppUrl()}/auth/join?${inviteQuery.toString()}`;
    let emailSent = false;

    if (parsed.data.email && resend) {
        log.info('Attempting to send email', { email: parsed.data.email });
        try {
            const { data: emailData, error: emailError } = await resend.emails.send({
                from: EMAIL_FROM,
                to: parsed.data.email,
                subject: `Provision access for ${restaurant?.name ?? 'lole'}`,
                html: StaffInviteEmail({
                    inviteUrl,
                    restaurantName: restaurant?.name ?? 'lole',
                    role: parsed.data.role,
                }),
            });

            if (emailError) {
                log.error('Resend API returned error', emailError);
            } else {
                log.info('Email sent successfully', { emailData });
                emailSent = true;
            }
        } catch (emailError) {
            log.error('Failed to send invite email', emailError);
            // We don't fail the request if email fails, but we'll flag it in the response
        }
    } else {
        log.warn('Skipping email', { hasEmail: Boolean(parsed.data.email), resendReady: Boolean(resend) });
    }

    await writeAuditLog(context.supabase, {
        restaurant_id: context.restaurantId,
        user_id: auth.user.id,
        action: 'staff_invite_created',
        entity_type: 'staff_invite',
        entity_id: data.id,
        metadata: {
            role: parsed.data.role,
            has_email: Boolean(parsed.data.email),
            email_sent: emailSent,
            label: parsed.data.label ?? null,
        },
        new_value: {
            status: data.status,
            expires_at: data.expires_at,
        },
    });

    return apiSuccess(
        {
            invite: data,
            invite_url: inviteUrl,
            email_sent: emailSent,
        },
        201
    );
}

import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { createServiceRoleClient } from '@/lib/supabase/service-role';
import { logger } from '@/lib/logger';

const log = logger.child('merchant-core-staff');

export async function GET() {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id);
    if (!context.ok) {
        return context.response;
    }

    // Query the enriched view that joins restaurant_staff with auth.users
    // This gives us real email/name which requires service role access to auth.users
    let adminClient;
    try {
        adminClient = createServiceRoleClient();
    } catch (e) {
        log.error('Service Role Client Creation Failed', e);
        // Fallback to regular client if service role fails, though data might be incomplete due to RLS
        return apiError(
            'Server configuration error: Missing Service Role Key',
            500,
            'CONFIG_ERROR'
        );
    }

    const { data: baseStaff, error: baseError } = await adminClient
        .from('restaurant_staff')
        .select('id, user_id, role, is_active, created_at, name, pin_code, assigned_zones')
        .eq('restaurant_id', context.restaurantId)
        .order('created_at', { ascending: true });

    if (baseError) {
        return apiError('Failed to fetch staff list', 500, 'STAFF_FETCH_FAILED', baseError.message);
    }

    const staffRows = (baseStaff ?? []) as Array<{
        id: string;
        user_id: string | null;
        role: string;
        is_active: boolean | null;
        created_at: string | null;
        name?: string | null;
        pin_code?: string | null;
        assigned_zones?: string[] | null;
    }>;

    const userIds = staffRows
        .map(row => row.user_id)
        .filter((value): value is string => typeof value === 'string' && value.length > 0);

    let enrichedByStaffId = new Map<
        string,
        {
            email?: string | null;
            name?: string | null;
            full_name?: string | null;
            first_name?: string | null;
            last_name?: string | null;
        }
    >();

    if (userIds.length > 0) {
        const { data: enrichedRows, error: enrichedError } = await adminClient
            .from('restaurant_staff_with_users')
            .select('id, user_id, email, name, full_name, first_name, last_name')
            .eq('restaurant_id', context.restaurantId)
            .in('user_id', userIds);

        if (enrichedError) {
            log.warn('Enriched view fetch failed', { message: enrichedError.message });
        } else {
            enrichedByStaffId = new Map(
                ((enrichedRows ?? []) as Array<Record<string, unknown>>).map(row => [
                    String(row.id ?? ''),
                    {
                        email: (row.email as string | null | undefined) ?? null,
                        name: (row.name as string | null | undefined) ?? null,
                        full_name: (row.full_name as string | null | undefined) ?? null,
                        first_name: (row.first_name as string | null | undefined) ?? null,
                        last_name: (row.last_name as string | null | undefined) ?? null,
                    },
                ])
            );
        }
    }

    const staff = staffRows.map(row => {
        const enriched = enrichedByStaffId.get(row.id);
        return {
            id: row.id,
            user_id: row.user_id,
            role: row.role,
            is_active: row.is_active,
            created_at: row.created_at,
            name: enriched?.name ?? row.name ?? null,
            full_name: enriched?.full_name ?? null,
            first_name: enriched?.first_name ?? null,
            last_name: enriched?.last_name ?? null,
            email: enriched?.email ?? null,
            pin_code: row.pin_code ?? null,
            assigned_zones: row.assigned_zones ?? [],
        };
    });

    return apiSuccess({ staff });
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { logger } from '@/lib/logger';
import { parseJsonBody, parseQuery } from '@/lib/api/validation';
import { writeAuditLog } from '@/lib/api/audit';
import { isIdempotencyKeyValid, resolveIdempotencyKey } from '@/lib/api/idempotency';
import { createServiceRoleClient } from '@/lib/supabase/service-role';
import type { Json } from '@/types/database';
import { STAFF_ROLES } from '@/types/status';

const log = logger.child('merchant-core-staff/schedule');

const ScheduleQuerySchema = z.object({
    start_date: z
        .string()
        .regex(/^\d{4}-\d{2}-\d{2}$/)
        .optional(),
    end_date: z
        .string()
        .regex(/^\d{4}-\d{2}-\d{2}$/)
        .optional(),
});

const ShiftCreateSchema = z.object({
    staff_id: z.string().uuid(),
    role: z.enum(STAFF_ROLES).optional(),
    shift_date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
    start_time: z.string().regex(/^\d{2}:\d{2}$/),
    end_time: z.string().regex(/^\d{2}:\d{2}$/),
    station: z.string().trim().max(80).optional().nullable(),
    notes: z.string().trim().max(400).optional().nullable(),
});

function normalizeWindow(input: { start_date?: string; end_date?: string }) {
    const now = new Date();
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());

    const start = input.start_date ? new Date(`${input.start_date}T00:00:00`) : today;
    const end = input.end_date
        ? new Date(`${input.end_date}T00:00:00`)
        : new Date(today.getTime() + 6 * 24 * 60 * 60 * 1000);

    const daySpan = Math.round((end.getTime() - start.getTime()) / (24 * 60 * 60 * 1000));
    return {
        startIso: start.toISOString().slice(0, 10),
        endIso: end.toISOString().slice(0, 10),
        daySpan,
    };
}

function overlaps(aStart: string, aEnd: string, bStart: string, bEnd: string) {
    return aStart < bEnd && bStart < aEnd;
}

export async function GET(request: Request) {
    try {
        const auth = await getAuthenticatedUser();
        if (!auth.ok) {
            return auth.response;
        }

        const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p1' });
        if (!context.ok) {
            return context.response;
        }

        const query = parseQuery(
            Object.fromEntries(new URL(request.url).searchParams.entries()),
            ScheduleQuerySchema
        );
        if (!query.success) {
            return query.response;
        }

        const { startIso, endIso, daySpan } = normalizeWindow(query.data);
        if (daySpan < 0 || daySpan > 31) {
            return apiError(
                'Invalid schedule window. Maximum span is 31 days.',
                400,
                'INVALID_SCHEDULE_WINDOW'
            );
        }

        log.info('Fetching schedule data', { restaurantId: context.restaurantId, startIso, endIso });

        const adminClient = createServiceRoleClient();

        // Use Promise.allSettled to debug which query fails if any
        const results = await Promise.allSettled([
            adminClient
                .from('shifts')
                .select(
                    'id, staff_id, role, shift_date, start_time, end_time, station, status, notes, created_at, updated_at'
                )
                .eq('restaurant_id', context.restaurantId)
                .gte('shift_date', startIso)
                .lte('shift_date', endIso)
                .order('shift_date', { ascending: true })
                .order('start_time', { ascending: true }),
            adminClient
                .from('restaurant_staff_with_users')
                .select(
                    'id, user_id, role, is_active, name, full_name, first_name, last_name, email'
                )
                .eq('restaurant_id', context.restaurantId)
                .eq('is_active', true)
                .order('created_at', { ascending: true }),
        ]);

        const shiftsRes = results[0];
        const staffRes = results[1];

        if (shiftsRes.status === 'rejected') {
            log.error('Shifts query failed', shiftsRes.reason);
            throw new Error('Shifts query failed');
        }
        if (staffRes.status === 'rejected') {
            log.error('Staff query failed', staffRes.reason);
            throw new Error('Staff query failed');
        }

        if (shiftsRes.value.error) {
            log.error('Shifts DB error', shiftsRes.value.error);
            return apiError(
                'Failed to fetch schedule',
                500,
                'SCHEDULE_FETCH_FAILED',
                shiftsRes.value.error.message
            );
        }
        if (staffRes.value.error) {
            log.error('Staff DB error', staffRes.value.error);
            // Fallback: If view query fails, try basic staff table?
            // For now, return error to see what's wrong.
            return apiError(
                'Failed to fetch staff',
                500,
                'STAFF_FETCH_FAILED',
                staffRes.value.error.message
            );
        }

        const staffData = staffRes.value.data ?? [];

        // Fix names: specific logic for "Owner" name replacement
        // If the name is "Owner" but the role is NOT owner, try to use email part or "Staff Member"
        const processedStaff = staffData.map(s => {
            let displayName = s.full_name || s.name || s.first_name || s.last_name;

            // If name is effectively "Owner" but they are not the actual owner role,
            // OR even if they are owner but we want a better name (user requested removing "Owner" as name).
            // Let's rely on email if name is generic "Owner".
            if (!displayName || displayName === 'Owner') {
                if (s.email) {
                    displayName = s.email.split('@')[0]; // Use 'makeemoneyonly' from 'makeemoneyonly@gmail.com'
                } else {
                    displayName = 'User';
                }
            }
            return {
                ...s,
                // We overwrite the raw fields or just ensure the UI uses a computed one?
                // The UI might use `name` or `first_name`. Let's populate specific fields.
                name: displayName,
                first_name: displayName.split(' ')[0],
                last_name: displayName.split(' ').slice(1).join(' ') || '',
            };
        });

        return apiSuccess({
            window: {
                start_date: startIso,
                end_date: endIso,
            },
            shifts: shiftsRes.value.data ?? [],
            staff: processedStaff,
        });
    } catch (e: unknown) {
        const message = e instanceof Error ? e.message : 'Unknown error';
        log.error('Unexpected error', e);
        return apiError('Internal Server Error', 500, 'INTERNAL_ERROR', message);
    }
}

export async function POST(request: Request) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p1' });
    if (!context.ok) {
        return context.response;
    }

    const explicitIdempotencyKey = request.headers.get('x-idempotency-key');
    if (explicitIdempotencyKey && !isIdempotencyKeyValid(explicitIdempotencyKey)) {
        return apiError('Invalid idempotency key', 400, 'INVALID_IDEMPOTENCY_KEY');
    }
    const idempotencyKey = resolveIdempotencyKey(explicitIdempotencyKey);

    const parsed = await parseJsonBody(request, ShiftCreateSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    if (parsed.data.end_time <= parsed.data.start_time) {
        return apiError('end_time must be after start_time', 400, 'INVALID_SHIFT_TIME_RANGE');
    }

    const { data: staffMember, error: staffError } = await context.supabase
        .from('restaurant_staff')
        .select('id, role, is_active')
        .eq('id', parsed.data.staff_id)
        .eq('restaurant_id', context.restaurantId)
        .maybeSingle();

    if (staffError) {
        return apiError(
            'Failed to load staff member',
            500,
            'STAFF_FETCH_FAILED',
            staffError.message
        );
    }
    if (!staffMember || staffMember.is_active === false) {
        return apiError('Staff member not found or inactive', 404, 'STAFF_NOT_FOUND');
    }

    const { data: existingShifts, error: existingError } = await context.supabase
        .from('shifts')
        .select('id, start_time, end_time, status')
        .eq('restaurant_id', context.restaurantId)
        .eq('staff_id', parsed.data.staff_id)
        .eq('shift_date', parsed.data.shift_date)
        .in('status', ['scheduled', 'in_progress']);

    if (existingError) {
        return apiError(
            'Failed to validate schedule overlap',
            500,
            'SCHEDULE_OVERLAP_CHECK_FAILED',
            existingError.message
        );
    }

    const overlap = (existingShifts ?? []).find(shift =>
        overlaps(parsed.data.start_time, parsed.data.end_time, shift.start_time, shift.end_time)
    );
    if (overlap) {
        return apiError(
            'Shift overlaps with an existing active shift for this staff member',
            409,
            'SHIFT_OVERLAP_CONFLICT'
        );
    }

    const row = {
        restaurant_id: context.restaurantId,
        staff_id: parsed.data.staff_id,
        role: parsed.data.role ?? staffMember.role,
        shift_date: parsed.data.shift_date,
        start_time: parsed.data.start_time,
        end_time: parsed.data.end_time,
        station: parsed.data.station ?? null,
        notes: parsed.data.notes ?? null,
        status: 'scheduled',
        created_by: auth.user.id,
    };

    // HIGH-013: Explicit column selection
    const { data: inserted, error: insertError } = await context.supabase
        .from('shifts')
        .insert(row)
        .select(
            'id, restaurant_id, staff_id, shift_date, start_time, end_time, role, station, notes, status, created_by, created_at, updated_at'
        )
        .single();

    if (insertError) {
        return apiError('Failed to create shift', 500, 'SHIFT_CREATE_FAILED', insertError.message);
    }

    await writeAuditLog(context.supabase, {
        restaurant_id: context.restaurantId,
        user_id: auth.user.id,
        action: 'shift_created',
        entity_type: 'shift',
        entity_id: inserted.id,
        metadata: {
            source: 'merchant_dashboard',
            idempotency_key: idempotencyKey,
        },
        new_value: inserted as unknown as Json,
    });

    return apiSuccess({ shift: inserted, idempotency_key: idempotencyKey }, 201);
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { parseJsonBody } from '@/lib/api/validation';
import { writeAuditLog } from '@/lib/api/audit';
import { isIdempotencyKeyValid, resolveIdempotencyKey } from '@/lib/api/idempotency';
import type { Json } from '@/types/database';

const ClockActionSchema = z.object({
    staff_id: z.string().uuid(),
    action: z.enum(['in', 'out']),
    shift_id: z.string().uuid().optional(),
    occurred_at: z.string().datetime().optional(),
    source: z.enum(['dashboard', 'mobile', 'kiosk', 'api']).optional(),
    note: z.string().trim().max(240).optional(),
});

export async function POST(request: Request) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p1' });
    if (!context.ok) {
        return context.response;
    }

    const explicitIdempotencyKey = request.headers.get('x-idempotency-key');
    if (explicitIdempotencyKey && !isIdempotencyKeyValid(explicitIdempotencyKey)) {
        return apiError('Invalid idempotency key', 400, 'INVALID_IDEMPOTENCY_KEY');
    }
    const idempotencyKey = resolveIdempotencyKey(explicitIdempotencyKey);

    const parsed = await parseJsonBody(request, ClockActionSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    const occurredAt = parsed.data.occurred_at ?? new Date().toISOString();

    const { data: staffMember, error: staffError } = await context.supabase
        .from('restaurant_staff')
        .select('id, is_active')
        .eq('id', parsed.data.staff_id)
        .eq('restaurant_id', context.restaurantId)
        .maybeSingle();

    if (staffError) {
        return apiError(
            'Failed to load staff member',
            500,
            'STAFF_FETCH_FAILED',
            staffError.message
        );
    }
    if (!staffMember || staffMember.is_active === false) {
        return apiError('Staff member not found or inactive', 404, 'STAFF_NOT_FOUND');
    }

    const { data: openEntry, error: openEntryError } = await context.supabase
        .from('time_entries')
        .select('id, shift_id, staff_id, clock_in_at, clock_out_at')
        .eq('restaurant_id', context.restaurantId)
        .eq('staff_id', parsed.data.staff_id)
        .is('clock_out_at', null)
        .order('clock_in_at', { ascending: false })
        .limit(1)
        .maybeSingle();

    if (openEntryError) {
        return apiError(
            'Failed to load open time entry',
            500,
            'TIME_ENTRY_FETCH_FAILED',
            openEntryError.message
        );
    }

    if (parsed.data.action === 'in') {
        if (openEntry) {
            return apiError('Staff member is already clocked in', 409, 'CLOCK_ALREADY_OPEN');
        }

        const { data: inserted, error: insertError } = await context.supabase
            .from('time_entries')
            .insert({
                restaurant_id: context.restaurantId,
                staff_id: parsed.data.staff_id,
                shift_id: parsed.data.shift_id || null,
                clock_in_at: occurredAt,
            })
            // HIGH-013: Explicit column selection
            .select(
                'id, restaurant_id, staff_id, shift_id, clock_in_at, clock_out_at, status, source, metadata, created_by, created_at, updated_at'
            )
            .single();

        if (insertError) {
            return apiError('Failed to clock in', 500, 'CLOCK_IN_FAILED', insertError.message);
        }

        if (parsed.data.shift_id) {
            await context.supabase
                .from('shifts')
                .update({ status: 'in_progress' })
                .eq('id', parsed.data.shift_id)
                .eq('restaurant_id', context.restaurantId);
        }

        await writeAuditLog(context.supabase, {
            restaurant_id: context.restaurantId,
            user_id: auth.user.id,
            action: 'staff_clock_in',
            entity_type: 'time_entry',
            entity_id: inserted.id,
            metadata: {
                source: parsed.data.source ?? 'dashboard',
                idempotency_key: idempotencyKey,
            } as Json,
            new_value: inserted as unknown as Json,
        });

        return apiSuccess(
            {
                entry: inserted,
                action: 'in',
                idempotency_key: idempotencyKey,
            },
            201
        );
    }

    if (!openEntry) {
        return apiError(
            'No open time entry found for staff member',
            409,
            'CLOCK_OUT_WITHOUT_OPEN_ENTRY'
        );
    }

    const { data: updated, error: updateError } = await context.supabase
        .from('time_entries')
        .update({
            clock_out_at: occurredAt,
            status: 'closed',
        })
        .eq('id', openEntry.id)
        .eq('restaurant_id', context.restaurantId)
        // HIGH-013: Explicit column selection
        .select(
            'id, restaurant_id, staff_id, shift_id, clock_in_at, clock_out_at, status, source, metadata, created_by, created_at, updated_at'
        )
        .single();

    if (updateError) {
        return apiError('Failed to clock out', 500, 'CLOCK_OUT_FAILED', updateError.message);
    }

    if (openEntry.shift_id) {
        const { data: stillOpenForShift } = await context.supabase
            .from('time_entries')
            .select('id')
            .eq('restaurant_id', context.restaurantId)
            .eq('shift_id', openEntry.shift_id)
            .eq('status', 'open')
            .limit(1);

        if (!stillOpenForShift || stillOpenForShift.length === 0) {
            await context.supabase
                .from('shifts')
                .update({ status: 'completed' })
                .eq('id', openEntry.shift_id)
                .eq('restaurant_id', context.restaurantId)
                .neq('status', 'cancelled');
        }
    }

    await writeAuditLog(context.supabase, {
        restaurant_id: context.restaurantId,
        user_id: auth.user.id,
        action: 'staff_clock_out',
        entity_type: 'time_entry',
        entity_id: updated.id,
        old_value: null,
        new_value: updated as unknown as Json,
        metadata: {
            source: parsed.data.source ?? 'dashboard',
            idempotency_key: idempotencyKey,
        } as Json,
    });

    return apiSuccess({
        entry: updated,
        action: 'out',
        idempotency_key: idempotencyKey,
    });
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { parseJsonBody } from '@/lib/api/validation';
import { createServiceRoleClient } from '@/lib/supabase/service-role';
import { buildStaffSessionExpiry, verifyStoredStaffPin } from '@/domains/staff/pin';
import { logger } from '@/lib/logger';

const VerifyPinSchema = z.object({
    restaurantId: z.string().uuid(),
    pin: z.string().length(4), // Assume a 4-digit numeric PIN
});

export async function POST(request: Request) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const parsed = await parseJsonBody(request, VerifyPinSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    // Usually, the device (iPad) itself has an authenticated session (auth.user.id).
    // We check if this device is authorized for this restaurant.
    const context = await getAuthorizedRestaurantContext(auth.user.id);
    if (!context.ok) {
        return context.response;
    }

    // We also make sure the device is verifying a PIN for its own restaurant
    if (context.restaurantId !== parsed.data.restaurantId) {
        return apiError('Unauthorized', 403, 'RESTAURANT_MISMATCH');
    }

    // Now, let's find the specific staff member using this PIN
    // Use service role to bypass RLS for this specific verification step
    // to ensure reliable login on shared terminals.
    const adminClient = createServiceRoleClient();

    const { data: staffRows, error } = await adminClient
        .from('restaurant_staff_with_users')
        .select('id, user_id, role, name, email, pin_code, staff_name')
        .eq('restaurant_id', context.restaurantId)
        .eq('is_active', true);

    if (error || !staffRows) {
        logger.error('[Verify PIN] Failed to fetch staff rows', { error: error?.message });
        return apiError('Invalid PIN', 400, 'INVALID_PIN');
    }

    const staff = staffRows.find((candidate: { pin_code: string | null }) =>
        verifyStoredStaffPin(candidate.pin_code, parsed.data.pin)
    );

    if (!staff) {
        return apiError('Invalid PIN', 400, 'INVALID_PIN');
    }

    return apiSuccess(
        {
            staff: {
                id: staff.id,
                role: staff.role,
                name: staff.staff_name || staff.name || staff.email || 'Waitstaff',
                user_id: staff.user_id,
                session_expires_at: buildStaffSessionExpiry(),
            },
        },
        200
    );
}

import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { generateSignedQRCode } from '@/lib/security/hmac';
import { getRequestOrigin } from '@/lib/api/requestOrigin';

export async function POST(request: Request, context: { params: Promise<{ tableId: string }> }) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const restaurantContext = await getAuthorizedRestaurantContext(auth.user.id);
    if (!restaurantContext.ok) {
        return restaurantContext.response;
    }

    const { tableId } = await context.params;
    const { data: table, error: tableError } = await restaurantContext.supabase
        .from('tables')
        .select('id, table_number, qr_version, restaurant_id')
        .eq('id', tableId)
        .eq('restaurant_id', restaurantContext.restaurantId)
        .maybeSingle();

    if (tableError) {
        return apiError('Failed to fetch table', 500, 'TABLE_FETCH_FAILED', tableError.message);
    }
    if (!table) {
        return apiError('Table not found', 404, 'TABLE_NOT_FOUND');
    }

    const { data: restaurant, error: restaurantError } = await restaurantContext.supabase
        .from('restaurants')
        .select('slug')
        .eq('id', table.restaurant_id as string)
        .maybeSingle();

    if (restaurantError) {
        return apiError(
            'Failed to fetch restaurant slug',
            500,
            'RESTAURANT_FETCH_FAILED',
            restaurantError.message
        );
    }
    if (!restaurant?.slug) {
        return apiError('Restaurant slug missing', 500, 'RESTAURANT_SLUG_MISSING');
    }

    const origin = getRequestOrigin(request);
    const qr = generateSignedQRCode(restaurant.slug, table.table_number, origin);

    const { data: updatedTable, error: updateError } = await restaurantContext.supabase
        .from('tables')
        .update({
            qr_code_url: qr.url,
            qr_version: (table.qr_version ?? 1) + 1,
        })
        .eq('id', table.id)
        .select('id, table_number, qr_code_url, qr_version')
        .single();

    if (updateError) {
        return apiError(
            'Failed to update table QR code',
            500,
            'TABLE_QR_UPDATE_FAILED',
            updateError.message
        );
    }

    return apiSuccess({
        table: updatedTable,
        qr: {
            url: qr.url,
            signature: qr.signature,
            expires_at: qr.expiresAt,
        },
    });
}

