import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { parseJsonBody } from '@/lib/api/validation';
import { createServiceRoleClient } from '@/lib/supabase/service-role';
import { queueAndDispatchManagedDeviceAction } from '@/lib/devices/management';

const DeviceManagementActionSchema = z.object({
    action: z.enum(['reboot', 'wipe', 'push_update']),
    package_name: z.string().trim().max(200).optional(),
    app_version: z.string().trim().max(40).optional(),
});

export async function POST(
    request: Request,
    { params }: { params: Promise<{ deviceId: string }> }
) {
    const { deviceId } = await params;

    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id);
    if (!context.ok) {
        return context.response;
    }

    const parsed = await parseJsonBody(request, DeviceManagementActionSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    const admin = createServiceRoleClient();
    const { data: device, error: deviceError } = await admin
        .from('hardware_devices')
        .select(
            'id, restaurant_id, name, management_provider, management_device_id, device_profile, device_type'
        )
        .eq('id', deviceId)
        .eq('restaurant_id', context.restaurantId)
        .maybeSingle();

    if (deviceError || !device) {
        return apiError('Device not found', 404, 'DEVICE_NOT_FOUND', deviceError?.message);
    }

    if (device.management_provider !== 'esper' || !device.management_device_id) {
        return apiError(
            'This device is not fully configured for Esper remote actions',
            409,
            'DEVICE_NOT_MANAGED'
        );
    }

    try {
        const result = await queueAndDispatchManagedDeviceAction({
            admin,
            restaurantId: context.restaurantId,
            userId: auth.user.id,
            device: device as Record<string, unknown>,
            action: parsed.data.action,
            packageName: parsed.data.package_name,
            appVersion: parsed.data.app_version,
        });

        return apiSuccess({
            action_id: result.actionId,
            provider_job_id: result.providerJobId,
            status: result.status,
        });
    } catch (error) {
        return apiError(
            'Failed to dispatch remote device action',
            502,
            'DEVICE_ACTION_DISPATCH_FAILED',
            error instanceof Error ? error.message : undefined
        );
    }
}

import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { writeAuditLog } from '@/lib/api/audit';
import type { Json } from '@/types/database';
import {
    revokeGatewayIdentityMetadata,
    rotateGatewayIdentityMetadata,
} from '@/lib/auth/offline-authz';
import { DEVICE_PAIRING_CODE_LENGTH } from '@/lib/devices/config';
import { z } from 'zod';

const DeviceIdentityActionSchema = z.object({
    action: z.enum(['rotate_identity', 'revoke_identity']),
});

function generatePairingCode(length = DEVICE_PAIRING_CODE_LENGTH): string {
    const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    return Array.from({ length }, () => alphabet[Math.floor(Math.random() * alphabet.length)]).join(
        ''
    );
}

export async function DELETE(
    _request: Request,
    { params }: { params: Promise<{ deviceId: string }> }
) {
    const { deviceId } = await params;

    const auth = await getAuthenticatedUser();
    if (!auth.ok) return auth.response;

    const context = await getAuthorizedRestaurantContext(auth.user.id);
    if (!context.ok) return context.response;

    // Verify the device belongs to this restaurant before deleting
    const { data: device, error: fetchError } = await context.supabase
        .from('hardware_devices')
        .select('id, name, device_type')
        .eq('id', deviceId)
        .eq('restaurant_id', context.restaurantId)
        .single();

    if (fetchError || !device) {
        return apiError('Device not found or access denied', 404, 'DEVICE_NOT_FOUND');
    }

    const { error: deleteError } = await context.supabase
        .from('hardware_devices')
        .delete()
        .eq('id', deviceId)
        .eq('restaurant_id', context.restaurantId);

    if (deleteError) {
        return apiError(
            'Failed to delete device',
            500,
            'DEVICE_DELETE_FAILED',
            deleteError.message
        );
    }

    await writeAuditLog(context.supabase, {
        restaurant_id: context.restaurantId,
        user_id: auth.user.id,
        action: 'device_deleted',
        entity_type: 'hardware_devices',
        entity_id: deviceId,
        metadata: { name: device.name, device_type: device.device_type },
    });

    return apiSuccess({ deleted: true });
}

export async function PATCH(
    request: Request,
    { params }: { params: Promise<{ deviceId: string }> }
) {
    const { deviceId } = await params;
    const auth = await getAuthenticatedUser();
    if (!auth.ok) return auth.response;

    const context = await getAuthorizedRestaurantContext(auth.user.id);
    if (!context.ok) return context.response;

    const parsed = DeviceIdentityActionSchema.safeParse(await request.json());
    if (!parsed.success) {
        return apiError('Invalid device identity action', 400, 'INVALID_DEVICE_IDENTITY_ACTION');
    }

    const { data: device, error: fetchError } = await context.supabase
        .from('hardware_devices')
        .select('id, name, device_type, restaurant_id, metadata')
        .eq('id', deviceId)
        .eq('restaurant_id', context.restaurantId)
        .single();

    if (fetchError || !device) {
        return apiError('Device not found or access denied', 404, 'DEVICE_NOT_FOUND');
    }

    const now = new Date().toISOString();
    const currentMetadata =
        typeof device.metadata === 'object' && device.metadata !== null
            ? (device.metadata as Record<string, unknown>)
            : null;
    const rotating = parsed.data.action === 'rotate_identity';
    const nextMetadata = rotating
        ? rotateGatewayIdentityMetadata(currentMetadata, now)
        : revokeGatewayIdentityMetadata(currentMetadata, now);
    const updatePayload = rotating
        ? {
              metadata: nextMetadata as Json,
              device_token: null,
              pairing_state: 'ready',
              pairing_code: generatePairingCode(),
              pairing_code_expires_at: new Date(Date.now() + 30 * 60 * 1000).toISOString(),
              paired_at: null,
              pairing_completed_at: null,
          }
        : {
              metadata: nextMetadata as Json,
              device_token: null,
              pairing_state: 'revoked',
              pairing_code: null,
              pairing_code_expires_at: null,
              paired_at: null,
              pairing_completed_at: null,
          };

    const { data: updatedDevice, error: updateError } = await context.supabase
        .from('hardware_devices')
        .update(updatePayload)
        .eq('id', deviceId)
        .eq('restaurant_id', context.restaurantId)
        .select('id, pairing_state, device_token, metadata, pairing_code, pairing_code_expires_at')
        .single();

    if (updateError || !updatedDevice) {
        return apiError(
            'Failed to update device identity',
            500,
            'DEVICE_IDENTITY_UPDATE_FAILED',
            updateError?.message
        );
    }

    await writeAuditLog(context.supabase, {
        restaurant_id: context.restaurantId,
        user_id: auth.user.id,
        action: rotating ? 'device_identity_rotated' : 'device_identity_revoked',
        entity_type: 'hardware_devices',
        entity_id: deviceId,
        metadata: {
            name: device.name,
            device_type: device.device_type,
            pairing_state: updatedDevice.pairing_state,
        },
    });

    return apiSuccess({
        device: updatedDevice,
    });
}

import { apiError, apiSuccess } from '@/lib/api/response';
import { parseJsonBody } from '@/lib/api/validation';
import {
    HardwareDeviceTypeSchema,
    DeviceProfileSchema,
    normalizeDeviceMetadata,
    type DeviceProfile,
    type HardwareDeviceType,
} from '@/lib/devices/config';
import {
    hydrateEnterpriseDeviceRecord,
    isEnterpriseDeviceSchemaError,
    mergeEnterpriseShellMetadata,
    readEnterpriseShellMetadata,
} from '@/lib/devices/schema-compat';
import {
    PairDeviceSchema,
    generateDeviceToken,
    getDeviceBootPathFromRecord,
    normalizePairingCode,
} from '@/lib/devices/pairing';
import { createServiceRoleClient } from '@/lib/supabase/service-role';
import { setDeviceTokenCookies, type DeviceMetadata } from '@/lib/auth/device-token-cookies';
import {
    buildGatewayIdentityMetadata,
    buildOfflineStaffOutagePolicyMetadata,
} from '@/lib/auth/offline-authz';

export async function POST(request: Request) {
    const parsed = await parseJsonBody(request, PairDeviceSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    const code = normalizePairingCode(parsed.data.code ?? parsed.data.pairing_code ?? '');
    if (code.length < 4) {
        return apiError('Invalid pairing code', 400, 'INVALID_PAIRING_CODE');
    }

    const adminClient = createServiceRoleClient();
    const fetchEnterpriseDevice = () =>
        adminClient
            .from('hardware_devices')
            .select(
                'id, restaurant_id, location_id, device_type, device_profile, name, assigned_zones, metadata, pairing_state, pairing_code_expires_at'
            )
            .eq('pairing_code', code)
            .in('pairing_state', ['ready', 'paired'])
            .maybeSingle();

    let device: Record<string, unknown> | null = null;
    let error: { message: string } | null = null;

    const enterpriseResult = await fetchEnterpriseDevice();
    device = (enterpriseResult.data as Record<string, unknown> | null) ?? null;
    error = enterpriseResult.error;

    if (error && isEnterpriseDeviceSchemaError(error.message)) {
        const legacyResult = await adminClient
            .from('hardware_devices')
            .select('id, restaurant_id, device_type, name, assigned_zones, metadata, paired_at')
            .eq('pairing_code', code)
            .maybeSingle();

        device = (legacyResult.data as Record<string, unknown> | null) ?? null;
        error = legacyResult.error;

        if (device) {
            const shell = readEnterpriseShellMetadata(
                typeof device.metadata === 'object' && device.metadata !== null
                    ? (device.metadata as Record<string, unknown>)
                    : {},
                HardwareDeviceTypeSchema.safeParse(device.device_type).success
                    ? (device.device_type as HardwareDeviceType)
                    : 'pos'
            );

            if (shell.pairing_state !== 'ready' && shell.pairing_state !== 'paired') {
                device = null;
            } else {
                device = {
                    ...device,
                    location_id: shell.location_id,
                    device_profile: shell.device_profile,
                    pairing_state: shell.pairing_state,
                    pairing_code_expires_at: shell.pairing_code_expires_at,
                } as Record<string, unknown>;
            }
        }
    }

    if (error || !device) {
        return apiError('Invalid or expired pairing code', 400, 'INVALID_PAIRING_CODE');
    }

    if (
        typeof device.pairing_code_expires_at === 'string' &&
        new Date(device.pairing_code_expires_at).getTime() < Date.now()
    ) {
        await adminClient
            .from('hardware_devices')
            .update({ pairing_state: 'expired' })
            .eq('id', String(device.id));
        return apiError('Pairing code has expired', 410, 'PAIRING_CODE_EXPIRED');
    }

    const { data: restaurant } = await adminClient
        .from('restaurants')
        .select('slug')
        .eq('id', String(device.restaurant_id))
        .maybeSingle();

    const device_token = generateDeviceToken();
    const now = new Date().toISOString();
    const rawMetadata =
        typeof device.metadata === 'object' && device.metadata !== null
            ? (device.metadata as Record<string, unknown>)
            : {};
    const resolvedDeviceType = HardwareDeviceTypeSchema.safeParse(device.device_type).success
        ? (device.device_type as HardwareDeviceType)
        : 'pos';
    const resolvedProfile = DeviceProfileSchema.safeParse(device.device_profile).success
        ? (device.device_profile as DeviceProfile)
        : null;
    const normalizedMetadata = normalizeDeviceMetadata(
        resolvedDeviceType,
        {
            ...rawMetadata,
            runtime: {
                ...((rawMetadata.runtime as Record<string, unknown> | undefined) ?? {}),
                native_platform: parsed.data.platform ?? null,
                native_version: parsed.data.app_version ?? null,
                last_heartbeat_at: now,
            },
            printer: parsed.data.printer
                ? {
                      ...((rawMetadata.printer as Record<string, unknown> | undefined) ?? {}),
                      ...parsed.data.printer,
                      auto_connect: true,
                      last_selected_at: now,
                  }
                : (rawMetadata.printer as Record<string, unknown> | undefined),
        },
        resolvedProfile
    );
    const gatewayAwareMetadata = buildOfflineStaffOutagePolicyMetadata({
        metadata: buildGatewayIdentityMetadata(normalizedMetadata, now),
        deviceType: resolvedDeviceType,
        deviceProfile: resolvedProfile,
        nowIso: now,
    });

    let updateError: { message: string } | null = null;

    const enterpriseUpdate = await adminClient
        .from('hardware_devices')
        .update({
            device_token,
            pairing_state: 'paired',
            paired_at: now,
            pairing_completed_at: now,
            last_active_at: now,
            hardware_fingerprint: parsed.data.device_uuid ?? null,
            app_version: parsed.data.app_version ?? null,
            printer_connection_type: parsed.data.printer?.connection_type ?? null,
            printer_device_id: parsed.data.printer?.device_id ?? null,
            printer_device_name: parsed.data.printer?.device_name ?? null,
            printer_mac_address: parsed.data.printer?.mac_address ?? null,
            metadata: gatewayAwareMetadata,
        })
        .eq('id', String(device.id));

    updateError = enterpriseUpdate.error;

    if (updateError && isEnterpriseDeviceSchemaError(updateError.message)) {
        const legacyMetadata = mergeEnterpriseShellMetadata(gatewayAwareMetadata, {
            device_profile: resolvedProfile,
            location_id: (device.location_id as string | null | undefined) ?? null,
            pairing_state: 'paired',
            pairing_completed_at: now,
            hardware_fingerprint: parsed.data.device_uuid ?? null,
        });

        const legacyUpdate = await adminClient
            .from('hardware_devices')
            .update({
                device_token,
                paired_at: now,
                last_active_at: now,
                metadata: legacyMetadata,
            })
            .eq('id', String(device.id));

        updateError = legacyUpdate.error;
    }

    if (updateError) {
        return apiError('Failed to pair device', 500, 'DEVICE_PAIR_FAILED', updateError.message);
    }

    const hydratedDevice = hydrateEnterpriseDeviceRecord(
        device as unknown as Parameters<typeof hydrateEnterpriseDeviceRecord>[0]
    ) as any; // eslint-disable-line @typescript-eslint/no-explicit-any

    const boot_path = getDeviceBootPathFromRecord({
        device_profile: hydratedDevice.device_profile,
        device_type: hydratedDevice.device_type,
        restaurant_slug: restaurant?.slug ?? null,
    });

    // Set secure httpOnly cookies for device authentication
    // The token is also returned in the response body for backward compatibility
    // with existing clients that use localStorage/header-based auth
    const deviceMetadata: DeviceMetadata = {
        device_type: String(device.device_type),
        restaurant_id: String(device.restaurant_id),
        location_id: (device.location_id as string | null | undefined) ?? undefined,
        name: (device.name as string | null | undefined) ?? undefined,
        created_at: now,
        last_used_at: now,
    };
    await setDeviceTokenCookies(device_token, deviceMetadata);

    return apiSuccess(
        {
            device_token,
            restaurant_id: hydratedDevice.restaurant_id,
            location_id: hydratedDevice.location_id ?? null,
            device_type: hydratedDevice.device_type,
            device_profile: hydratedDevice.device_profile,
            name: hydratedDevice.name,
            assigned_zones: hydratedDevice.assigned_zones,
            metadata: gatewayAwareMetadata,
            boot_path,
            restaurant_slug: restaurant?.slug ?? null,
        },
        200
    );
}

import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { parseJsonBody } from '@/lib/api/validation';
import { createServiceRoleClient } from '@/lib/supabase/service-role';
import { normalizeDeviceMetadata, type DeviceManagementMetadata } from '@/lib/devices/config';
import {
    hydrateEnterpriseDeviceRecord,
    isEnterpriseDeviceSchemaError,
    mergeEnterpriseShellMetadata,
} from '@/lib/devices/schema-compat';
import {
    ProvisionDeviceSchema,
    buildPairingExpiry,
    generatePairingCode,
    getDeviceBootPathFromRecord,
    resolveProvisionedDeviceShape,
} from '@/lib/devices/pairing';

export async function POST(request: Request) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id);
    if (!context.ok) {
        return context.response;
    }

    const parsed = await parseJsonBody(request, ProvisionDeviceSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    const { deviceType, deviceProfile } = resolveProvisionedDeviceShape(parsed.data);
    const pairing_code = generatePairingCode();
    const adminClient = createServiceRoleClient();
    const rawMetadata =
        parsed.data.metadata && typeof parsed.data.metadata === 'object'
            ? parsed.data.metadata
            : undefined;
    const pairingCodeExpiresAt = buildPairingExpiry();
    const managementMetadata: DeviceManagementMetadata = {
        ...((rawMetadata?.management as Record<string, unknown> | undefined) ?? {}),
        provider: 'esper' as const,
    };
    const normalizedMetadata = normalizeDeviceMetadata(
        deviceType,
        {
            ...(rawMetadata ?? {}),
            management: managementMetadata,
        },
        deviceProfile
    );

    const insertEnterprise = () =>
        adminClient
            .from('hardware_devices')
            .insert({
                restaurant_id: context.restaurantId,
                name: parsed.data.name,
                location_id: parsed.data.location_id ?? null,
                device_type: deviceType,
                device_profile: deviceProfile,
                pairing_code,
                pairing_code_expires_at: pairingCodeExpiresAt,
                pairing_state: 'ready',
                management_provider: 'esper',
                management_status: 'pending',
                assigned_zones: parsed.data.assigned_zones ?? [],
                metadata: normalizedMetadata,
            })
            // HIGH-013: Explicit column selection
            .select(
                'id, restaurant_id, name, device_type, device_profile, status, pairing_code, pairing_code_expires_at, pairing_state, management_provider, management_status, management_device_id, assigned_zones, metadata, last_active_at, created_at, updated_at'
            )
            .single();

    let { data, error } = await insertEnterprise();

    if (error && isEnterpriseDeviceSchemaError(error.message)) {
        const legacyMetadata = mergeEnterpriseShellMetadata(normalizedMetadata, {
            device_profile: deviceProfile,
            location_id: parsed.data.location_id ?? null,
            pairing_state: 'ready',
            pairing_code_expires_at: pairingCodeExpiresAt,
            management_provider: 'esper',
            management_status: 'pending',
        });

        const legacyResult = await adminClient
            .from('hardware_devices')
            .insert({
                restaurant_id: context.restaurantId,
                name: parsed.data.name,
                device_type: deviceType,
                pairing_code,
                assigned_zones: parsed.data.assigned_zones ?? [],
                metadata: legacyMetadata,
            })
            // HIGH-013: Explicit column selection
            .select(
                'id, restaurant_id, name, device_type, device_profile, status, pairing_code, pairing_code_expires_at, pairing_state, management_provider, management_status, management_device_id, assigned_zones, metadata, last_active_at, created_at, updated_at'
            )
            .single();

        data = legacyResult.data;
        error = legacyResult.error;
    }

    if (error) {
        if (
            deviceType === 'terminal' &&
            /device_type|hardware_devices_device_type_check|violates check constraint/i.test(
                error.message
            )
        ) {
            return apiError(
                'Terminal provisioning requires the latest database migration. Apply the new hardware device migration and try again.',
                500,
                'TERMINAL_DEVICE_MIGRATION_REQUIRED',
                error.message
            );
        }

        return apiError(
            'Failed to provision device',
            500,
            'DEVICE_PROVISION_FAILED',
            error.message
        );
    }

    const { data: restaurant } = await adminClient
        .from('restaurants')
        .select('slug')
        .eq('id', context.restaurantId)
        .maybeSingle();

    const setupPath = restaurant?.slug
        ? `/${restaurant.slug}/setup?code=${encodeURIComponent(pairing_code)}`
        : null;
    const appBaseUrl = process.env.NEXT_PUBLIC_APP_URL?.replace(/\/$/, '') ?? null;
    const bootPath = getDeviceBootPathFromRecord({
        device_profile: data?.device_profile ?? deviceProfile,
        device_type: data?.device_type ?? deviceType,
        restaurant_slug: restaurant?.slug ?? null,
    });

    return apiSuccess(
        {
            device: data
                ? hydrateEnterpriseDeviceRecord(
                      data as Parameters<typeof hydrateEnterpriseDeviceRecord>[0]
                  )
                : data,
            rollout: {
                pairing_code,
                pairing_code_expires_at: pairingCodeExpiresAt,
                setup_path: setupPath,
                setup_url: setupPath && appBaseUrl ? `${appBaseUrl}${setupPath}` : null,
                boot_path: bootPath,
            },
        },
        201
    );
}

import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';

export async function GET() {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id);
    if (!context.ok) {
        return context.response;
    }

    // List all hardware devices for the restaurant
    const { data, error } = await context.supabase
        .from('hardware_devices')
        // HIGH-013: Explicit column selection
        .select(
            'id, restaurant_id, name, device_type, device_profile, status, pairing_code, pairing_code_expires_at, pairing_state, management_provider, management_status, management_device_id, assigned_zones, metadata, last_active_at, created_at, updated_at'
        )
        .eq('restaurant_id', context.restaurantId)
        .order('created_at', { ascending: false });

    if (error) {
        return apiError('Failed to fetch devices', 500, 'DEVICES_FETCH_FAILED', error.message);
    }

    return apiSuccess({ devices: data ?? [] });
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { parseJsonBody } from '@/lib/api/validation';
import { writeAuditLog } from '@/lib/api/audit';
import { redisRateLimiters } from '@/lib/security';
import type { NextRequest } from 'next/server';

const GuestIdSchema = z.string().uuid();

const UpdateGuestSchema = z
    .object({
        name: z.string().trim().min(1).max(140).optional(),
        language: z.enum(['en', 'am']).optional(),
        tags: z.array(z.string().trim().min(1).max(40)).max(20).optional(),
        is_vip: z.boolean().optional(),
        notes: z.string().trim().max(1000).nullable().optional(),
    })
    .refine(value => Object.keys(value).length > 0, {
        message: 'At least one field is required',
    });

export async function GET(
    _request: Request,
    routeContext: { params: Promise<{ guestId: string }> }
) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p1' });
    if (!context.ok) {
        return context.response;
    }

    const { guestId } = await routeContext.params;
    const guestIdParsed = GuestIdSchema.safeParse(guestId);
    if (!guestIdParsed.success) {
        return apiError('Invalid guest id', 400, 'INVALID_GUEST_ID', guestIdParsed.error.flatten());
    }

    const { data, error } = await context.supabase
        .from('guests')
        .select(
            'id, restaurant_id, name, phone_hash, email_hash, language, tags, is_vip, notes, first_seen_at, last_seen_at, visit_count, lifetime_value, created_at, updated_at'
        )
        .eq('id', guestIdParsed.data)
        .eq('restaurant_id', context.restaurantId)
        .maybeSingle();

    if (error) {
        return apiError('Failed to fetch guest', 500, 'GUEST_FETCH_FAILED', error.message);
    }
    if (!data) {
        return apiError('Guest not found', 404, 'GUEST_NOT_FOUND');
    }

    return apiSuccess(data);
}

export async function PATCH(
    request: Request,
    routeContext: { params: Promise<{ guestId: string }> }
) {
    // Apply rate limiting for guest mutations
    const rateLimitResponse = await redisRateLimiters.guestCreate(request as NextRequest);
    if (rateLimitResponse) {
        return rateLimitResponse;
    }

    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p1' });
    if (!context.ok) {
        return context.response;
    }

    const { guestId } = await routeContext.params;
    const guestIdParsed = GuestIdSchema.safeParse(guestId);
    if (!guestIdParsed.success) {
        return apiError('Invalid guest id', 400, 'INVALID_GUEST_ID', guestIdParsed.error.flatten());
    }

    const parsed = await parseJsonBody(request, UpdateGuestSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    const { data: existing, error: existingError } = await context.supabase
        .from('guests')
        .select('id, name, language, tags, is_vip, notes')
        .eq('id', guestIdParsed.data)
        .eq('restaurant_id', context.restaurantId)
        .maybeSingle();

    if (existingError) {
        return apiError('Failed to load guest', 500, 'GUEST_FETCH_FAILED', existingError.message);
    }
    if (!existing) {
        return apiError('Guest not found', 404, 'GUEST_NOT_FOUND');
    }

    const payload: Record<string, unknown> = {
        updated_at: new Date().toISOString(),
    };
    if (parsed.data.name !== undefined) {
        payload.name = parsed.data.name;
    }
    if (parsed.data.language !== undefined) {
        payload.language = parsed.data.language;
    }
    if (parsed.data.tags !== undefined) {
        payload.tags = parsed.data.tags;
    }
    if (parsed.data.is_vip !== undefined) {
        payload.is_vip = parsed.data.is_vip;
    }
    if (parsed.data.notes !== undefined) {
        payload.notes = parsed.data.notes;
    }

    const { data, error } = await context.supabase
        .from('guests')
        .update(payload)
        .eq('id', guestIdParsed.data)
        .eq('restaurant_id', context.restaurantId)
        .select(
            'id, restaurant_id, name, phone_hash, email_hash, language, tags, is_vip, notes, first_seen_at, last_seen_at, visit_count, lifetime_value, created_at, updated_at'
        )
        .single();

    if (error) {
        return apiError('Failed to update guest', 500, 'GUEST_UPDATE_FAILED', error.message);
    }

    await writeAuditLog(context.supabase, {
        restaurant_id: context.restaurantId,
        user_id: auth.user.id,
        action: 'guest_updated',
        entity_type: 'guest',
        entity_id: guestIdParsed.data,
        old_value: {
            name: existing.name,
            language: existing.language,
            tags: existing.tags,
            is_vip: existing.is_vip,
            notes: existing.notes,
        },
        new_value: {
            name: data.name,
            language: data.language,
            tags: data.tags,
            is_vip: data.is_vip,
            notes: data.notes,
        },
        metadata: { source: 'merchant_dashboard' },
    });

    return apiSuccess(data);
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { parseQuery } from '@/lib/api/validation';

const GuestIdSchema = z.string().uuid();

const GuestVisitsQuerySchema = z.object({
    limit: z.coerce.number().int().min(1).max(200).optional().default(50),
});

export async function GET(
    request: Request,
    routeContext: { params: Promise<{ guestId: string }> }
) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p1' });
    if (!context.ok) {
        return context.response;
    }

    const { guestId } = await routeContext.params;
    const guestIdParsed = GuestIdSchema.safeParse(guestId);
    if (!guestIdParsed.success) {
        return apiError('Invalid guest id', 400, 'INVALID_GUEST_ID', guestIdParsed.error.flatten());
    }

    const url = new URL(request.url);
    const parsed = parseQuery(
        {
            limit: url.searchParams.get('limit') ?? undefined,
        },
        GuestVisitsQuerySchema
    );
    if (!parsed.success) {
        return parsed.response;
    }

    const { data: guest, error: guestError } = await context.supabase
        .from('guests')
        .select('id')
        .eq('id', guestIdParsed.data)
        .eq('restaurant_id', context.restaurantId)
        .maybeSingle();

    if (guestError) {
        return apiError('Failed to load guest', 500, 'GUEST_FETCH_FAILED', guestError.message);
    }
    if (!guest) {
        return apiError('Guest not found', 404, 'GUEST_NOT_FOUND');
    }

    const { data, error } = await context.supabase
        .from('guest_visits')
        .select(
            'id, order_id, table_id, channel, visited_at, spend, metadata, orders(order_number, status, table_number, total_price)'
        )
        .eq('restaurant_id', context.restaurantId)
        .eq('guest_id', guestIdParsed.data)
        .order('visited_at', { ascending: false })
        .limit(parsed.data.limit);

    if (error) {
        return apiError(
            'Failed to fetch guest visits',
            500,
            'GUEST_VISITS_FETCH_FAILED',
            error.message
        );
    }

    return apiSuccess({
        visits: data ?? [],
        total: data?.length ?? 0,
    });
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { parseQuery } from '@/lib/api/validation';

const GuestsQuerySchema = z.object({
    query: z.string().trim().max(120).optional(),
    segment: z.enum(['all', 'vip', 'returning', 'new']).optional().default('all'),
    tag: z.string().trim().max(40).optional(),
    limit: z.coerce.number().int().min(1).max(200).optional().default(50),
});

export async function GET(request: Request) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p1' });
    if (!context.ok) {
        return context.response;
    }

    const url = new URL(request.url);
    const parsed = parseQuery(
        {
            query: url.searchParams.get('query') ?? undefined,
            segment: url.searchParams.get('segment') ?? undefined,
            tag: url.searchParams.get('tag') ?? undefined,
            limit: url.searchParams.get('limit') ?? undefined,
        },
        GuestsQuerySchema
    );
    if (!parsed.success) {
        return parsed.response;
    }

    let query = context.supabase
        .from('guests')
        .select(
            'id, name, language, tags, is_vip, first_seen_at, last_seen_at, visit_count, lifetime_value, created_at, updated_at'
        )
        .eq('restaurant_id', context.restaurantId)
        .order('last_seen_at', { ascending: false })
        .limit(parsed.data.limit);

    if (parsed.data.query) {
        query = query.ilike('name', `%${parsed.data.query}%`);
    }

    if (parsed.data.segment === 'vip') {
        query = query.eq('is_vip', true);
    } else if (parsed.data.segment === 'returning') {
        query = query.gte('visit_count', 2);
    } else if (parsed.data.segment === 'new') {
        query = query.lte('visit_count', 1);
    }

    if (parsed.data.tag) {
        query = query.contains('tags', [parsed.data.tag]);
    }

    const { data, error } = await query;
    if (error) {
        return apiError('Failed to fetch guests', 500, 'GUESTS_FETCH_FAILED', error.message);
    }

    return apiSuccess({
        guests: data ?? [],
        total: data?.length ?? 0,
    });
}

import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { API_METRIC_ACTION } from '@/lib/api/metrics';
import type { Json } from '@/types/database';

type RangeOption = 'today' | 'week' | 'month';

type EndpointSloTarget = {
    endpoint: string;
    p95_latency_ms: number;
    error_rate_percent: number;
};

const SLO_TARGETS: EndpointSloTarget[] = [
    { endpoint: '/api/v1/merchant/insights/analytics/overview', p95_latency_ms: 500, error_rate_percent: 1 },
    { endpoint: '/api/v1/merchant/operations/orders', p95_latency_ms: 400, error_rate_percent: 1 },
    { endpoint: '/api/v1/merchant/operations/orders/:id/status', p95_latency_ms: 300, error_rate_percent: 0.5 },
];

function getRangeStart(range: string | null) {
    const now = new Date();
    const normalized: RangeOption = range === 'today' || range === 'month' ? range : 'week';

    if (normalized === 'today') {
        const d = new Date(now);
        d.setHours(0, 0, 0, 0);
        return { range: normalized, sinceIso: d.toISOString() };
    }

    if (normalized === 'month') {
        const d = new Date(now);
        d.setDate(now.getDate() - 30);
        return { range: normalized, sinceIso: d.toISOString() };
    }

    const d = new Date(now);
    d.setDate(now.getDate() - 7);
    return { range: normalized, sinceIso: d.toISOString() };
}

function percentile(values: number[], p: number) {
    if (values.length === 0) return 0;
    const sorted = [...values].sort((a, b) => a - b);
    const index = Math.ceil((p / 100) * sorted.length) - 1;
    const safeIndex = Math.max(0, Math.min(sorted.length - 1, index));
    return sorted[safeIndex];
}

function formatBucket(dateIso: string, range: RangeOption) {
    const d = new Date(dateIso);
    if (range === 'today') {
        return `${String(d.getHours()).padStart(2, '0')}:00`;
    }
    return d.toISOString().slice(0, 10);
}

function asMetricMetadata(value: Json | null) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) {
        return null;
    }
    return value as Record<string, unknown>;
}

export async function GET(request: Request) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id);
    if (!context.ok) {
        return context.response;
    }

    const url = new URL(request.url);
    const { range, sinceIso } = getRangeStart(url.searchParams.get('range'));

    const { data, error } = await context.supabase
        .from('audit_logs')
        .select('created_at, metadata')
        .eq('restaurant_id', context.restaurantId)
        .eq('action', API_METRIC_ACTION)
        .gte('created_at', sinceIso)
        .order('created_at', { ascending: true })
        .limit(5000);

    if (error) {
        return apiError(
            'Failed to load API metrics',
            500,
            'API_METRICS_FETCH_FAILED',
            error.message
        );
    }

    const endpointMap = new Map<string, { durations: number[]; total: number; errors: number }>();
    const trendMap = new Map<
        string,
        { endpoint: string; bucket: string; total: number; errors: number; durations: number[] }
    >();

    for (const row of data ?? []) {
        const meta = asMetricMetadata(row.metadata);
        if (!meta) continue;

        const endpoint = typeof meta.endpoint === 'string' ? meta.endpoint : null;
        const durationMs = typeof meta.duration_ms === 'number' ? meta.duration_ms : null;
        const isError = typeof meta.is_error === 'boolean' ? meta.is_error : null;
        const createdAt = row.created_at;

        if (!endpoint || durationMs === null || isError === null || !createdAt) {
            continue;
        }

        const endpointEntry = endpointMap.get(endpoint) ?? { durations: [], total: 0, errors: 0 };
        endpointEntry.total += 1;
        endpointEntry.errors += isError ? 1 : 0;
        endpointEntry.durations.push(durationMs);
        endpointMap.set(endpoint, endpointEntry);

        const bucket = formatBucket(createdAt, range);
        const trendKey = `${endpoint}|${bucket}`;
        const trendEntry = trendMap.get(trendKey) ?? {
            endpoint,
            bucket,
            total: 0,
            errors: 0,
            durations: [],
        };
        trendEntry.total += 1;
        trendEntry.errors += isError ? 1 : 0;
        trendEntry.durations.push(durationMs);
        trendMap.set(trendKey, trendEntry);
    }

    const endpointStats = SLO_TARGETS.map(target => {
        const entry = endpointMap.get(target.endpoint) ?? { durations: [], total: 0, errors: 0 };
        const errorRate =
            entry.total > 0 ? Number(((entry.errors / entry.total) * 100).toFixed(2)) : 0;
        const p95 = percentile(entry.durations, 95);
        const p50 = percentile(entry.durations, 50);
        const avg =
            entry.total > 0
                ? Math.round(entry.durations.reduce((sum, n) => sum + n, 0) / entry.total)
                : 0;

        const latencyStatus = entry.total > 0 && p95 > target.p95_latency_ms ? 'breach' : 'healthy';
        const errorStatus =
            entry.total > 0 && errorRate > target.error_rate_percent ? 'breach' : 'healthy';

        return {
            endpoint: target.endpoint,
            requests: entry.total,
            errors: entry.errors,
            error_rate_percent: errorRate,
            latency_ms: {
                p50,
                p95,
                avg,
            },
            slo: {
                latency_target_p95_ms: target.p95_latency_ms,
                error_rate_target_percent: target.error_rate_percent,
                latency_status: entry.total === 0 ? 'no_data' : latencyStatus,
                error_status: entry.total === 0 ? 'no_data' : errorStatus,
            },
        };
    });

    const trend = Array.from(trendMap.values())
        .map(entry => ({
            endpoint: entry.endpoint,
            bucket: entry.bucket,
            requests: entry.total,
            errors: entry.errors,
            error_rate_percent:
                entry.total > 0 ? Number(((entry.errors / entry.total) * 100).toFixed(2)) : 0,
            p95_latency_ms: percentile(entry.durations, 95),
        }))
        .sort((a, b) => a.bucket.localeCompare(b.bucket) || a.endpoint.localeCompare(b.endpoint));

    return apiSuccess({
        range,
        range_start: sinceIso,
        generated_at: new Date().toISOString(),
        endpoints: endpointStats,
        trend,
    });
}

import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';

export async function POST(request: Request) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id);
    if (!context.ok) {
        return context.response;
    }

    const body = await request.json();
    const { mood, rating } = body;

    if (!mood || !rating) {
        return apiError('Missing required fields', 400, 'MISSING_FIELDS');
    }

    // Insert the mood rating into the reviews table so it shows up in metrics
    const { error } = await context.supabase.from('reviews').insert({
        restaurant_id: context.restaurantId,
        rating: rating,
        user_name: 'Manager Check-in',
        comment: mood,
        created_at: new Date().toISOString(),
    });

    if (error) {
        return apiError('Failed to log mood', 500, 'MOOD_LOG_FAILED', error.message);
    }

    return apiSuccess({ success: true });
}

/**
 * Notification Delivery Report API
 *
 * Provides detailed delivery reports with date range filtering:
 * - GET /api/analytics/notifications/report - Get delivery report
 *
 * Requires authentication and restaurant context.
 */

import { NextResponse } from 'next/server';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { getDeliveryReport, type DateRange } from '@/lib/monitoring/notification-metrics';
import { logger } from '@/lib/logger';

const log = logger.child('[analytics/notifications/report]');

/**
 * Range options for date filtering
 */
type RangeOption = 'today' | 'week' | 'month' | 'custom';

/**
 * Parse date range from query parameters
 */
function getDateRange(url: URL): DateRange {
    const range = url.searchParams.get('range') as RangeOption | null;
    const now = new Date();
    let endDate = new Date(now);
    endDate.setHours(23, 59, 59, 999);

    let startDate: Date;

    switch (range) {
        case 'today':
            startDate = new Date(now);
            startDate.setHours(0, 0, 0, 0);
            break;

        case 'week':
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 7);
            break;

        case 'month':
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 30);
            break;

        case 'custom':
            // Parse custom date range
            const startParam = url.searchParams.get('startDate');
            const endParam = url.searchParams.get('endDate');

            if (startParam && endParam) {
                startDate = new Date(startParam);
                endDate = new Date(endParam);
            } else {
                // Default to week if custom is specified but dates are missing
                startDate = new Date(now);
                startDate.setDate(now.getDate() - 7);
            }
            break;

        default:
            // Default to week
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 7);
    }

    return { startDate, endDate };
}

/**
 * GET /api/analytics/notifications/report
