    }

    return { startDate, endDate };
}

/**
 * GET /api/analytics/notifications
 *
 * Get current notification metrics for the authenticated restaurant.
 * Optionally includes global metrics if no restaurant context.
 *
 * Query params:
 * - range: 'today' | 'week' | 'month' (default: 'week')
 * - channel: 'sms' | 'push' | 'email' (optional filter)
 */
export async function GET(request: Request) {
    // Authenticate user
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    // Get restaurant context (optional - allows global metrics)
    const context = await getAuthorizedRestaurantContext(auth.user.id);
    const restaurantId = context.ok ? context.restaurantId : null;

    const url = new URL(request.url);
    const range = url.searchParams.get('range') as RangeOption | null;
    const channel = url.searchParams.get('channel');

    try {
        // Get metrics for the restaurant or global if no context
        const metrics = await getNotificationMetrics(restaurantId || undefined);

        // Filter by channel if requested
        let filteredMetrics = metrics;
        if (channel && ['sms', 'push', 'email'].includes(channel)) {
            const channelData = metrics.byChannel[channel as keyof typeof metrics.byChannel];
            const totalSent = channelData.sent;
            const totalFailed = channelData.failed;

            filteredMetrics = {
                totalSent,
                totalFailed,
                successRate:
                    totalSent + totalFailed > 0
                        ? Math.round((totalSent / (totalSent + totalFailed)) * 10000) / 100
                        : 0,
                avgLatencyMs: channelData.avgLatencyMs,
                byChannel: {
                    ...metrics.byChannel,
                    [channel]: channelData,
                },
            };
        }

        return NextResponse.json({
            success: true,
            data: filteredMetrics,
            meta: {
                restaurantId: restaurantId || null,
                range: range || 'week',
                channel: channel || 'all',
                generatedAt: new Date().toISOString(),
            },
        });
    } catch (error) {
        log.error('Error fetching metrics', error);

        return NextResponse.json(
            {
                success: false,
                error: {
                    code: 'METRICS_FETCH_ERROR',
                    message: 'Failed to fetch notification metrics',
                    details: error instanceof Error ? error.message : undefined,
                },
            },
            { status: 500 }
        );
    }
}

import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import {
    getAnalyticsOverview,
    getRangeStart,
    type AnalyticsRange,
} from '@/lib/services/timescaleAnalyticsService';
import { getCacheHeaders, CACHE_PRESETS } from '@/lib/api/cache';
import { logger } from '@/lib/logger';

const log = logger.child('[analytics/overview]');

export async function GET(request: Request) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id);
    if (!context.ok) {
        return context.response;
    }

    const url = new URL(request.url);
    const rangeParam = (url.searchParams.get('range') as AnalyticsRange) || 'today';
    const since = getRangeStart(rangeParam);

    // Calculate previous period start
    const sinceDate = new Date(since);
    const prevDate = new Date(sinceDate);
    if (rangeParam === 'week') prevDate.setDate(prevDate.getDate() - 7);
    else if (rangeParam === 'month') prevDate.setMonth(prevDate.getMonth() - 1);
    else if (rangeParam === 'year') prevDate.setFullYear(prevDate.getFullYear() - 1);
    else prevDate.setDate(prevDate.getDate() - 1); // Default is today (1 day)

    const prevSince = prevDate.toISOString();

    // Try to get TimescaleDB analytics first (faster for large datasets)
    let timeseriesMetrics: Awaited<ReturnType<typeof getAnalyticsOverview>> | null = null;
    try {
        timeseriesMetrics = await getAnalyticsOverview(
            context.supabase,
            context.restaurantId,
            rangeParam
        );
    } catch (error) {
        log.warn('TimescaleDB not available, using direct queries', { error });
    }

    // If TimescaleDB has data, use it; otherwise fall back to direct queries
    const useTimeseries = timeseriesMetrics && timeseriesMetrics.total_orders > 0;

    const [ordersRes, prevOrdersRes, requestsRes, tablesRes, reviewsRes] = await Promise.all([
        // Only fetch orders if not using timeseries
        useTimeseries
            ? Promise.resolve({ data: [], error: null })
            : context.supabase
                  .from('orders')
                  .select('id, status, total_price, created_at, order_items(name, quantity, price)')
                  .eq('restaurant_id', context.restaurantId)
                  .gte('created_at', since),
        useTimeseries
            ? Promise.resolve({ count: timeseriesMetrics?.previous_completed_orders || 0 })
            : context.supabase
                  .from('orders')
                  .select('id', { count: 'exact', head: true })
                  .eq('restaurant_id', context.restaurantId)
                  .in('status', ['served', 'completed'])
                  .gte('created_at', prevSince)
                  .lt('created_at', since),
        context.supabase
            .from('service_requests')
            .select('id, status, created_at')
            .eq('restaurant_id', context.restaurantId)
            .gte('created_at', since),
        context.supabase
            .from('tables')
            .select('id, status, is_active')
            .eq('restaurant_id', context.restaurantId),
        context.supabase
            .from('reviews')
            .select('rating, created_at')
            .eq('restaurant_id', context.restaurantId),
    ]);

    if (ordersRes.error) {
        return apiError(
            'Failed to fetch analytics orders data',
            500,
            'ANALYTICS_ORDERS_FETCH_FAILED',
            ordersRes.error.message
        );
    }
    if (requestsRes.error) {
        return apiError(
            'Failed to fetch analytics requests data',
            500,
            'ANALYTICS_REQUESTS_FETCH_FAILED',
            requestsRes.error.message
        );
    }
    if (tablesRes.error) {
        return apiError(
            'Failed to fetch analytics tables data',
            500,
            'ANALYTICS_TABLES_FETCH_FAILED',
            tablesRes.error.message
        );
    }
    // review fetch failure is non-critical, we can default to 0

    const orders = ordersRes.data ?? [];
    const requests = requestsRes.data ?? [];
    const tables = tablesRes.data ?? [];
    const reviews = reviewsRes.data ?? [];

    // total_price is stored in santim ΓÇö divide by 100 to get ETB
    const totalRevenue =
        orders.reduce((sum, order) => sum + Number(order.total_price ?? 0), 0) / 100;
    const totalOrders = orders.length;
    const completedOrders = orders.filter(order =>
        ['served', 'completed'].includes(order.status ?? '')
    ).length;
    const previousCompletedOrders = prevOrdersRes.count ?? 0;

    const pendingOrders = orders.filter(order =>
        ['pending', 'acknowledged', 'preparing', 'ready'].includes(order.status ?? '')
    ).length;
    const openRequests = requests.filter(r => (r.status ?? 'pending') === 'pending').length;

    // Table Metrics
    const activeTables = tables.filter(
        t => t.is_active !== false && t.status !== 'available'
    ).length;
    const totalTables = tables.length;

    // Review Metrics
    const totalReviews = reviews.length;
    const avgRating =
        totalReviews > 0
            ? Number(
                  (reviews.reduce((acc, r) => acc + (r.rating || 0), 0) / totalReviews).toFixed(1)
              )
            : 0;

    const oneWeekAgo = new Date();
    oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);
    const reviewsThisWeek = reviews.filter(
        r => r.created_at && new Date(r.created_at) > oneWeekAgo
    ).length;

    // Calculate Top Selling Items
    const itemSales: Record<string, { count: number; revenue: number }> = {};
    orders.forEach(order => {
        const items = order.order_items || [];
        items.forEach((item: { name: string; quantity: number | null; price: number }) => {
            const name = item.name || 'Unknown Item';
            const qty = item.quantity || 1;
            const price = item.price || 0;

            if (!itemSales[name]) {
                itemSales[name] = { count: 0, revenue: 0 };
            }
            itemSales[name].count += qty;
            itemSales[name].revenue += (price / 100) * qty;
        });
    });

    const topItems = Object.entries(itemSales)
        .map(([name, stats]) => ({ name, ...stats }))
        .sort((a, b) => b.count - a.count)
        .slice(0, 5);

    // Calculate Trends (buckets)
    const trendBuckets: Record<string, { revenue: number; orders: number }> = {};
    const now = new Date();
    const isToday = !url.searchParams.get('range') || url.searchParams.get('range') === 'today';

    // Initialize buckets
    for (let i = 0; i < (isToday ? 24 : 7); i++) {
        const key = isToday
            ? i.toString().padStart(2, '0') + ':00'
            : new Date(now.getTime() - (6 - i) * 86400000).toLocaleDateString('en-US', {
                  weekday: 'short',
              });
        trendBuckets[key] = { revenue: 0, orders: 0 };
    }

    orders.forEach(order => {
        if (!order.created_at) return;
        const date = new Date(order.created_at);
        let key = '';

        if (isToday) {
            key = date.getHours().toString().padStart(2, '0') + ':00';
        } else {
            key = date.toLocaleDateString('en-US', { weekday: 'short' });
        }

        if (trendBuckets[key]) {
            trendBuckets[key].revenue += Number(order.total_price ?? 0) / 100;
            trendBuckets[key].orders += 1;
        }
    });

    const trends = Object.entries(trendBuckets).map(([label, data]) => ({
        label,
        ...data,
    }));

    return apiSuccess(
        {
            range_start: since,
            metrics: {
                total_revenue: totalRevenue,
                total_orders: totalOrders,
                completed_orders: completedOrders,
                previous_completed_orders: previousCompletedOrders,
                pending_orders: pendingOrders,
                open_requests: openRequests,
                active_tables: activeTables,
                total_tables: totalTables,
                conversion_rate:
                    totalOrders > 0 ? Math.round((completedOrders / totalOrders) * 100) : 0,
                avg_order_value: totalOrders > 0 ? Math.round(totalRevenue / totalOrders) : 0,
                avg_rating: avgRating,
                total_reviews: totalReviews,
                reviews_this_week: reviewsThisWeek,
                top_items: topItems,
                trends: trends,
            },
        },
        200,
        getCacheHeaders(CACHE_PRESETS.analytics)
    );
}

/**
 * System Metrics API Endpoint
 *
 * Provides aggregated metrics for dashboard consumption.
 * This endpoint is intended for internal/monitoring use and returns
 * system-wide statistics without restaurant scoping.
 *
 * Security: Requires API key or HMAC signature verification.
 *
 * @see docs/implementation/observability-setup.md
 */

import { NextRequest, NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';
import { verifyQRSignature } from '@/lib/security/hmac';
import { METRIC_ACTIONS } from '@/lib/monitoring/metrics';

const METRICS_API_KEY = process.env.METRICS_API_KEY;

// Initialize admin client for system-wide queries
function getSupabaseAdmin() {
    return createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SECRET_KEY!);
}

/**
 * Verify API key authentication
 */
function authenticate(request: NextRequest): boolean {
    // Check API key header
    const apiKey = request.headers.get('x-metrics-api-key');
    if (apiKey && apiKey === METRICS_API_KEY) {
        return true;
    }

    // Check HMAC signature for internal service authentication
    const signature = request.headers.get('x-hmac-signature');
    const timestamp = request.headers.get('x-timestamp');
    if (signature && timestamp) {
        const data = `metrics:${timestamp}`;
        return verifyQRSignature(data, signature);
    }

    return false;
}

/**
 * Get time range for metrics queries
 */
function getTimeRange(range: string | null) {
    const now = new Date();
    let since: Date;

    switch (range) {
        case 'hour':
            since = new Date(now.getTime() - 60 * 60 * 1000);
            break;
        case 'day':
            since = new Date(now.getTime() - 24 * 60 * 60 * 1000);
            break;
        case 'week':
            since = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
            break;
        case 'month':
            since = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
            break;
        default:
            since = new Date(now.getTime() - 24 * 60 * 60 * 1000);
    }

    return { since: since.toISOString(), until: now.toISOString() };
}

/**
 * Calculate percentile from array
 */
function percentile(values: number[], p: number): number {
    if (values.length === 0) return 0;
    const sorted = [...values].sort((a, b) => a - b);
    const index = Math.ceil((p / 100) * sorted.length) - 1;
    return sorted[Math.max(0, Math.min(sorted.length - 1, index))];
}

/**
 * Fetch API metrics from audit_logs
 */
async function fetchApiMetrics(since: string, until: string) {
    const supabase = getSupabaseAdmin();

    const { data, error } = await supabase
        .from('audit_logs')
        .select('created_at, metadata, restaurant_id')
        .eq('action', METRIC_ACTIONS.API)
        .gte('created_at', since)
        .lte('created_at', until)
        .limit(10000);

    if (error || !data) {
        return {
            requests: 0,
            errors: 0,
            avgLatency: 0,
            p95Latency: 0,
            p99Latency: 0,
            errorRate: 0,
        };
    }

    const durations: number[] = [];
    let errorCount = 0;

    for (const row of data) {
        const meta = row.metadata as Record<string, unknown>;
        const duration = meta?.duration_ms as number | undefined;
        const isError = meta?.is_error as boolean | undefined;

        if (duration !== undefined && duration !== null) {
            durations.push(duration);
        }
        if (isError) {
            errorCount++;
        }
    }

    const requests = data.length;
    const avgLatency =
        durations.length > 0
            ? Math.round(durations.reduce((a, b) => a + b, 0) / durations.length)
            : 0;

    return {
        requests,
        errors: errorCount,
        avgLatency,
        p95Latency: percentile(durations, 95),
        p99Latency: percentile(durations, 99),
        errorRate: requests > 0 ? Number(((errorCount / requests) * 100).toFixed(2)) : 0,
    };
}

/**
 * Fetch order metrics
 */
async function fetchOrderMetrics(since: string, until: string) {
    const supabase = getSupabaseAdmin();

    const { data, error } = await supabase
        .from('audit_logs')
        .select('metadata')
        .eq('action', METRIC_ACTIONS.ORDER)
        .gte('created_at', since)
        .lte('created_at', until)
        .limit(5000);

    if (error || !data) {
        return { total: 0, completed: 0, cancelled: 0 };
    }

    let completed = 0;
    let cancelled = 0;

    for (const row of data) {
        const meta = row.metadata as Record<string, unknown>;
        const event = meta?.event as string | undefined;

        if (event === 'completed') completed++;
        if (event === 'cancelled') cancelled++;
    }

    return { total: data.length, completed, cancelled };
}

/**
 * Fetch payment metrics
 */
async function fetchPaymentMetrics(since: string, until: string) {
    const supabase = getSupabaseAdmin();

    const { data, error } = await supabase
        .from('audit_logs')
        .select('metadata')
        .eq('action', METRIC_ACTIONS.PAYMENT)
        .gte('created_at', since)
        .lte('created_at', until)
        .limit(5000);

    if (error || !data) {
        return { total: 0, completed: 0, failed: 0, totalAmount: 0 };
    }

    let completed = 0;
    let failed = 0;
    let totalAmount = 0;

    for (const row of data) {
        const meta = row.metadata as Record<string, unknown>;
        const event = meta?.event as string | undefined;
        const amount = meta?.amount as number | undefined;

        if (event === 'completed') completed++;
        if (event === 'failed') failed++;
        if (amount !== undefined && amount !== null) {
            totalAmount += amount;
        }
    }

    return { total: data.length, completed, failed, totalAmount };
}

/**
 * Fetch session metrics (active sessions estimate)
 */
async function fetchSessionMetrics(since: string, until: string) {
    const supabase = getSupabaseAdmin();

    const { data, error } = await supabase
        .from('audit_logs')
        .select('metadata, restaurant_id')
        .eq('action', METRIC_ACTIONS.SESSION)
        .gte('created_at', since)
        .lte('created_at', until)
        .limit(5000);

    if (error || !data) {
        return { total: 0, active: 0, closed: 0 };
    }

    let closed = 0;

    for (const row of data) {
        const meta = row.metadata as Record<string, unknown>;
        const event = meta?.event as string | undefined;

        if (event === 'closed' || event === 'timed_out') closed++;
    }

    const opened = data.length - closed;
    return { total: data.length, active: opened, closed };
}

/**
 * Fetch active users count (unique restaurant_ids in the time window)
 */
async function fetchActiveRestaurants(since: string, until: string) {
    const supabase = getSupabaseAdmin();

    const { data, error } = await supabase
        .from('audit_logs')
        .select('restaurant_id')
        .gte('created_at', since)
        .lte('created_at', until)
        .not('restaurant_id', 'is', null)
        .limit(10000);

    if (error || !data) {
        return 0;
    }

    const uniqueRestaurants = new Set(data.map(row => row.restaurant_id).filter(Boolean));

    return uniqueRestaurants.size;
}

/**
 * GET /api/metrics
 * Returns aggregated system metrics
 */
export async function GET(request: NextRequest) {
    if (!authenticate(request)) {
        return NextResponse.json(
            { error: { code: 'UNAUTHORIZED', message: 'Invalid API key or signature' } },
            { status: 401 }
        );
    }

    try {
        const url = new URL(request.url);
        const range = url.searchParams.get('range') || 'day';
        const { since, until } = getTimeRange(range);

        const [apiMetrics, orderMetrics, paymentMetrics, sessionMetrics, activeRestaurants] =
            await Promise.all([
                fetchApiMetrics(since, until),
                fetchOrderMetrics(since, until),
                fetchPaymentMetrics(since, until),
                fetchSessionMetrics(since, until),
                fetchActiveRestaurants(since, until),
            ]);

        const response = {
            data: {
                period: {
                    range,
                    since,
                    until,
                },
                generated_at: new Date().toISOString(),
                api: apiMetrics,
                orders: orderMetrics,
                payments: paymentMetrics,
                sessions: sessionMetrics,
                business: {
                    active_restaurants: activeRestaurants,
                },
            },
        };

        return NextResponse.json(response);
    } catch (_error) {
        return NextResponse.json(
            {
                error: {
                    code: 'METRICS_FETCH_FAILED',
                    message: 'Failed to fetch system metrics',
                },
            },
            { status: 500 }
        );
    }
}

