import { isIdempotencyKeyValid, resolveIdempotencyKey } from '@/lib/api/idempotency';
import { isSchemaNotReadyError } from '@/lib/api/schemaFallback';
import type { Json } from '@/types/database';
import type { SupabaseClient } from '@supabase/supabase-js';
import type { Database } from '@/types/database';

interface CampaignDeliveryRow {
    campaign_id: string;
    status: string;
    conversion_order_id: string | null;
}

interface CampaignInsertResult {
    id: string;
    name: string;
    channel: string;
    status: string;
    segment_id: string | null;
}

const CampaignsQuerySchema = z.object({
    status: z.enum(['draft', 'scheduled', 'running', 'completed', 'cancelled']).optional(),
    limit: z.coerce.number().int().min(1).max(200).optional().default(100),
});

const CreateCampaignSchema = z.object({
    name: z.string().trim().min(2).max(140),
    channel: z.enum(['sms', 'email', 'whatsapp', 'in_app']),
    segment_id: z.string().uuid().optional(),
    template_json: z.record(z.string(), z.unknown()).optional(),
    scheduled_at: z.string().datetime().optional(),
});

export async function GET(request: Request) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p2' });
    if (!context.ok) {
        return context.response;
    }

    const db = context.supabase as SupabaseClient<Database>;

    const url = new URL(request.url);
    const parsed = parseQuery(
        {
            status: url.searchParams.get('status') ?? undefined,
            limit: url.searchParams.get('limit') ?? undefined,
        },
        CampaignsQuerySchema
    );
    if (!parsed.success) {
        return parsed.response;
    }

    let campaignQuery = db
        .from('campaigns')
        // HIGH-013: Explicit column selection
        .select(
            'id, restaurant_id, name, channel, segment_id, status, template_json, scheduled_at, launched_at, created_by, created_at, updated_at'
        )
        .eq('restaurant_id', context.restaurantId)
        .order('created_at', { ascending: false })
        .limit(parsed.data.limit);

    if (parsed.data.status) {
        campaignQuery = campaignQuery.eq('status', parsed.data.status);
    }

    const [{ data: campaigns, error: campaignError }, { data: segments, error: segmentError }] =
        await Promise.all([
            campaignQuery,
            db
                .from('segments')
                .select('id, name, rule_json, created_at')
                .eq('restaurant_id', context.restaurantId)
                .order('created_at', { ascending: false }),
        ]);

    if (campaignError) {
        if (isSchemaNotReadyError(campaignError)) {
            return apiSuccess({ campaigns: [], segments: [] });
        }
        return apiError(
            'Failed to fetch campaigns',
            500,
            'CAMPAIGNS_FETCH_FAILED',
            campaignError.message
        );
    }
    if (segmentError) {
        if (isSchemaNotReadyError(segmentError)) {
            return apiSuccess({ campaigns: [], segments: [] });
        }
        return apiError(
            'Failed to fetch segments',
            500,
            'SEGMENTS_FETCH_FAILED',
            segmentError.message
        );
    }

    const campaignIds = (campaigns ?? []).map((item: { id: string }) => item.id);
    const deliveriesByCampaign = new Map<
        string,
        {
            total: number;
            sent: number;
            opened: number;
            clicked: number;
            converted: number;
            failed: number;
        }
    >();

    if (campaignIds.length > 0) {
        const { data: deliveries, error: deliveryError } = await db
            .from('campaign_deliveries')
            .select('campaign_id, status, conversion_order_id')
            .in('campaign_id', campaignIds);

        if (deliveryError) {
            if (isSchemaNotReadyError(deliveryError)) {
                return apiSuccess({
                    campaigns: (campaigns ?? []).map((campaign: Record<string, unknown>) => ({
                        ...campaign,
                        tracking: {
                            total: 0,
                            sent: 0,
                            opened: 0,
                            clicked: 0,
                            converted: 0,
                            failed: 0,
                        },
                    })),
                    segments: segments ?? [],
                });
            }
            return apiError(
                'Failed to fetch campaign tracking',
                500,
                'CAMPAIGN_TRACKING_FETCH_FAILED',
                deliveryError.message
            );
        }

        for (const delivery of deliveries ?? []) {
            const typedDelivery = delivery as CampaignDeliveryRow;
            const current = deliveriesByCampaign.get(typedDelivery.campaign_id) ?? {
                total: 0,
                sent: 0,
                opened: 0,
                clicked: 0,
                converted: 0,
                failed: 0,
            };
            current.total += 1;
            if (typedDelivery.status === 'sent') current.sent += 1;
            if (typedDelivery.status === 'opened') current.opened += 1;
            if (typedDelivery.status === 'clicked') current.clicked += 1;
            if (typedDelivery.status === 'converted' || Boolean(typedDelivery.conversion_order_id))
                current.converted += 1;
            if (typedDelivery.status === 'failed') current.failed += 1;
            deliveriesByCampaign.set(typedDelivery.campaign_id, current);
        }
    }

    return apiSuccess({
        campaigns: (campaigns ?? []).map((campaign: Record<string, unknown>) => ({
            ...campaign,
            tracking: deliveriesByCampaign.get(campaign.id as string) ?? {
                total: 0,
                sent: 0,
                opened: 0,
                clicked: 0,
                converted: 0,
                failed: 0,
            },
        })),
        segments: segments ?? [],
    });
}

export async function POST(request: Request) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p2' });
    if (!context.ok) {
        return context.response;
    }

    const db = context.supabase as SupabaseClient<Database>;

    const explicitIdempotencyKey = request.headers.get('x-idempotency-key');
    if (explicitIdempotencyKey && !isIdempotencyKeyValid(explicitIdempotencyKey)) {
        return apiError('Invalid idempotency key', 400, 'INVALID_IDEMPOTENCY_KEY');
    }
    const idempotencyKey = resolveIdempotencyKey(explicitIdempotencyKey);

    const parsed = await parseJsonBody(request, CreateCampaignSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    if (parsed.data.segment_id) {
        const { data: segment, error: segmentError } = await db
            .from('segments')
            .select('id')
            .eq('id', parsed.data.segment_id)
            .eq('restaurant_id', context.restaurantId)
            .maybeSingle();

        if (segmentError) {
            return apiError(
                'Failed to validate segment',
                500,
                'SEGMENT_VALIDATION_FAILED',
                segmentError.message
            );
        }
        if (!segment) {
            return apiError('Segment not found', 404, 'SEGMENT_NOT_FOUND');
        }
    }

    const hasSchedule = Boolean(parsed.data.scheduled_at);

    const { data, error } = await db
        .from('campaigns')
        .insert({
            restaurant_id: context.restaurantId,
            channel: parsed.data.channel,
            name: parsed.data.name,
            segment_id: parsed.data.segment_id ?? null,
            template_json: (parsed.data.template_json ?? {}) as Json,
            status: hasSchedule ? 'scheduled' : 'draft',
            scheduled_at: parsed.data.scheduled_at ?? null,
            created_by: auth.user.id,
        })
        // HIGH-013: Explicit column selection
        .select(
            'id, restaurant_id, name, channel, segment_id, status, template_json, scheduled_at, launched_at, created_by, created_at, updated_at'
        )
        .single();

    if (error) {
        return apiError('Failed to create campaign', 500, 'CAMPAIGN_CREATE_FAILED', error.message);
    }

    await writeAuditLog(context.supabase as SupabaseClient<Database>, {
        restaurant_id: context.restaurantId,
        user_id: auth.user.id,
        action: 'campaign_created',
        entity_type: 'campaign',
        entity_id: (data as CampaignInsertResult).id,
        new_value: {
            name: (data as CampaignInsertResult).name,
            channel: (data as CampaignInsertResult).channel,
            status: (data as CampaignInsertResult).status,
            segment_id: (data as CampaignInsertResult).segment_id,
        },
        metadata: {
            source: 'merchant_dashboard',
            idempotency_key: idempotencyKey,
        },
    });

    return apiSuccess({ campaign: data, idempotency_key: idempotencyKey }, 201);
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { parseJsonBody } from '@/lib/api/validation';
import { writeAuditLog } from '@/lib/api/audit';
import { isIdempotencyKeyValid, resolveIdempotencyKey } from '@/lib/api/idempotency';
import type { Json } from '@/types/database';

const DeliveryConnectSchema = z.object({
    provider: z.enum(['beu', 'deliver_addis', 'zmall', 'telebirr_food', 'esoora', 'custom_local']),
    display_name: z.string().trim().min(2).max(80).optional(),
    credentials_ref: z.string().trim().min(3).max(200).optional(),
    settings_json: z.record(z.string(), z.unknown()).optional(),
});

export async function POST(request: Request) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p1' });
    if (!context.ok) {
        return context.response;
    }

    const explicitIdempotencyKey = request.headers.get('x-idempotency-key');
    if (explicitIdempotencyKey && !isIdempotencyKeyValid(explicitIdempotencyKey)) {
        return apiError('Invalid idempotency key', 400, 'INVALID_IDEMPOTENCY_KEY');
    }
    const idempotencyKey = resolveIdempotencyKey(explicitIdempotencyKey);

    const parsed = await parseJsonBody(request, DeliveryConnectSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    const payload = {
        restaurant_id: context.restaurantId,
        provider: parsed.data.provider,
        display_name: parsed.data.display_name ?? parsed.data.provider,
        status: 'connected' as const,
        credentials_ref: parsed.data.credentials_ref ?? null,
        settings_json: (parsed.data.settings_json ?? {}) as Json,
        last_sync_at: new Date().toISOString(),
        created_by: auth.user.id,
    };

    const { data, error } = await context.supabase
        .from('delivery_partners')
        .upsert(payload, { onConflict: 'restaurant_id,provider' })
        // HIGH-013: Explicit column selection
        .select(
            'id, restaurant_id, provider, display_name, status, credentials_ref, settings_json, api_key, last_sync_at, created_by, created_at, updated_at'
        )
        .single();

    if (error) {
        return apiError(
            'Failed to connect delivery partner',
            500,
            'DELIVERY_PARTNER_CONNECT_FAILED',
            error.message
        );
    }

    await writeAuditLog(context.supabase, {
        restaurant_id: context.restaurantId,
        user_id: auth.user.id,
        action: 'delivery_partner_connected',
        entity_type: 'delivery_partner',
        entity_id: data.id,
        new_value: {
            provider: data.provider,
            status: data.status,
            display_name: data.display_name,
        },
        metadata: {
            source: 'merchant_dashboard',
            idempotency_key: idempotencyKey,
        },
    });

    return apiSuccess(
        {
            partner: data,
            idempotency_key: idempotencyKey,
        },
        201
    );
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { parseJsonBody } from '@/lib/api/validation';
import { writeAuditLog } from '@/lib/api/audit';
import { isIdempotencyKeyValid, resolveIdempotencyKey } from '@/lib/api/idempotency';

const ExternalOrderIdSchema = z.string().uuid();

const AckPayloadSchema = z.object({
    note: z.string().trim().max(240).optional(),
});

export async function POST(
    request: Request,
    routeContext: { params: Promise<{ externalOrderId: string }> }
) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p1' });
    if (!context.ok) {
        return context.response;
    }

    const explicitIdempotencyKey = request.headers.get('x-idempotency-key');
    if (explicitIdempotencyKey && !isIdempotencyKeyValid(explicitIdempotencyKey)) {
        return apiError('Invalid idempotency key', 400, 'INVALID_IDEMPOTENCY_KEY');
    }
    const idempotencyKey = resolveIdempotencyKey(explicitIdempotencyKey);

    const parsedBody = await parseJsonBody(request, AckPayloadSchema);
    if (!parsedBody.success) {
        return parsedBody.response;
    }

    const { externalOrderId } = await routeContext.params;
    const parsedOrderId = ExternalOrderIdSchema.safeParse(externalOrderId);
    if (!parsedOrderId.success) {
        return apiError(
            'Invalid external order id',
            400,
            'INVALID_EXTERNAL_ORDER_ID',
            parsedOrderId.error.flatten()
        );
    }

    const { data: existing, error: fetchError } = await context.supabase
        .from('external_orders')
        .select('id, restaurant_id, provider, normalized_status, acknowledged_at')
        .eq('id', parsedOrderId.data)
        .eq('restaurant_id', context.restaurantId)
        .maybeSingle();

    if (fetchError) {
        return apiError(
            'Failed to load external order',
            500,
            'EXTERNAL_ORDER_FETCH_FAILED',
            fetchError.message
        );
    }
    if (!existing) {
        return apiError('External order not found', 404, 'EXTERNAL_ORDER_NOT_FOUND');
    }

    if (existing.acknowledged_at) {
        return apiSuccess({
            order_id: existing.id,
            acknowledged: true,
            already_acknowledged: true,
            idempotency_key: idempotencyKey,
        });
    }

    const nextStatus =
        existing.normalized_status === 'new' ? 'acknowledged' : existing.normalized_status;
    const ackedAt = new Date().toISOString();

    const { data: updated, error: updateError } = await context.supabase
        .from('external_orders')
        .update({
            acknowledged_at: ackedAt,
            acked_by: auth.user.id,
            normalized_status: nextStatus,
        })
        .eq('id', existing.id)
        .eq('restaurant_id', context.restaurantId)
        .select('id, provider, normalized_status, acknowledged_at')
        .single();

    if (updateError) {
        return apiError(
            'Failed to acknowledge external order',
            500,
            'EXTERNAL_ORDER_ACK_FAILED',
            updateError.message
        );
    }

    await writeAuditLog(context.supabase, {
        restaurant_id: context.restaurantId,
        user_id: auth.user.id,
        action: 'external_order_acknowledged',
        entity_type: 'external_order',
        entity_id: existing.id,
        old_value: {
            normalized_status: existing.normalized_status,
            acked_at: existing.acknowledged_at,
        },
        new_value: {
            normalized_status: updated.normalized_status,
            acked_at: updated.acknowledged_at,
        },
        metadata: {
            source: 'merchant_dashboard',
            idempotency_key: idempotencyKey,
            note: parsedBody.data.note ?? null,
        },
    });

    return apiSuccess({
        order: updated,
        idempotency_key: idempotencyKey,
    });
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { parseQuery } from '@/lib/api/validation';

const DeliveryOrdersQuerySchema = z.object({
    provider: z
        .enum([
            'beu',
            'deliver_addis',
            'zmall',
            'telebirr_food',
            'esoora',
            'direct_web',
            'custom_local',
        ])
        .optional(),
    status: z
        .enum([
            'new',
            'acknowledged',
            'preparing',
            'ready',
            'out_for_delivery',
            'completed',
            'cancelled',
            'failed',
        ])
        .optional(),
    limit: z.coerce.number().int().min(1).max(200).optional().default(50),
});

export async function GET(request: Request) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p1' });
    if (!context.ok) {
        return context.response;
    }

    const url = new URL(request.url);
    const parsed = parseQuery(
        {
            provider: url.searchParams.get('provider') ?? undefined,
            status: url.searchParams.get('status') ?? undefined,
            limit: url.searchParams.get('limit') ?? undefined,
        },
        DeliveryOrdersQuerySchema
    );
    if (!parsed.success) {
        return parsed.response;
    }

    let query = context.supabase
        .from('external_orders')
        .select(
            'id, provider, provider_order_id, source_channel, normalized_status, total_amount, currency, payload_json, acked_at, created_at, updated_at'
        )
        .eq('restaurant_id', context.restaurantId)
        .order('created_at', { ascending: false })
        .limit(parsed.data.limit);

    if (parsed.data.provider) {
        query = query.eq('provider', parsed.data.provider);
    }
    if (parsed.data.status) {
        query = query.eq('normalized_status', parsed.data.status);
    }

    const { data, error } = await query;
    if (error) {
        return apiError(
            'Failed to fetch delivery orders',
            500,
            'DELIVERY_ORDERS_FETCH_FAILED',
            error.message
        );
    }

    return apiSuccess({
        orders: data ?? [],
        total: data?.length ?? 0,
    });
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { parseJsonBody } from '@/lib/api/validation';
import { writeAuditLog } from '@/lib/api/audit';

const OnlineOrderingSettingsSchema = z
    .object({
        enabled: z.boolean().optional(),
        accepts_scheduled_orders: z.boolean().optional(),
        auto_accept_orders: z.boolean().optional(),
        prep_time_minutes: z.number().int().min(5).max(180).optional(),
        max_daily_orders: z.number().int().min(1).max(5000).optional(),
        service_hours: z
            .object({
                start: z.string().regex(/^\d{2}:\d{2}$/),
                end: z.string().regex(/^\d{2}:\d{2}$/),
            })
            .optional(),
        order_throttling_enabled: z.boolean().optional(),
        throttle_limit_per_15m: z.number().int().min(1).max(500).optional(),
    })
    .refine(value => Object.keys(value).length > 0, {
        message: 'At least one field is required',
    });

const defaultOnlineOrderingSettings = {
    enabled: true,
    accepts_scheduled_orders: true,
    auto_accept_orders: false,
    prep_time_minutes: 30,
    max_daily_orders: 300,
    service_hours: {
        start: '08:00',
        end: '22:00',
    },
    order_throttling_enabled: false,
    throttle_limit_per_15m: 40,
};

export async function GET() {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p1' });
    if (!context.ok) {
        return context.response;
    }

    const { data, error } = await context.supabase
        .from('restaurants')
        .select('settings, slug')
        .eq('id', context.restaurantId)
        .single();

    if (error || !data) {
        return apiError(
            'Failed to fetch online ordering settings',
            500,
            'ONLINE_ORDERING_SETTINGS_FETCH_FAILED',
            error?.message ?? 'Restaurant not found'
        );
    }

    const settings = (data.settings ?? {}) as Record<string, unknown>;
    const channels = (settings.channels ?? {}) as Record<string, unknown>;
    const onlineOrdering = (channels.online_ordering ?? {}) as Record<string, unknown>;

    return apiSuccess({
        ...defaultOnlineOrderingSettings,
        ...onlineOrdering,
        slug: data.slug,
    });
}

export async function PATCH(request: Request) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p1' });
    if (!context.ok) {
        return context.response;
    }

    const parsed = await parseJsonBody(request, OnlineOrderingSettingsSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    const { data: restaurant, error: fetchError } = await context.supabase
        .from('restaurants')
        .select('settings')
        .eq('id', context.restaurantId)
        .single();

    if (fetchError || !restaurant) {
        return apiError(
            'Failed to fetch current settings',
            500,
            'SETTINGS_FETCH_FAILED',
            fetchError?.message ?? 'Restaurant not found'
        );
    }

    const currentSettings = (restaurant.settings ?? {}) as Record<string, unknown>;
    const currentChannels = (currentSettings.channels ?? {}) as Record<string, unknown>;
    const currentOnlineOrdering = {
        ...defaultOnlineOrderingSettings,
        ...((currentChannels.online_ordering ?? {}) as Record<string, unknown>),
    };
    const nextOnlineOrdering = {
        ...currentOnlineOrdering,
        ...parsed.data,
    };

    const nextChannels = {
        ...currentChannels,
        online_ordering: nextOnlineOrdering,
    };
    const nextSettings = {
        ...currentSettings,
        channels: nextChannels,
    };

    const { error: updateError } = await context.supabase
        .from('restaurants')
        .update({ settings: nextSettings })
        .eq('id', context.restaurantId);

    if (updateError) {
        return apiError(
            'Failed to update online ordering settings',
            500,
            'ONLINE_ORDERING_SETTINGS_UPDATE_FAILED',
            updateError.message
        );
    }

    await writeAuditLog(context.supabase, {
        restaurant_id: context.restaurantId,
        user_id: auth.user.id,
        action: 'online_ordering_settings_updated',
        entity_type: 'restaurant_settings',
        entity_id: context.restaurantId,
        old_value: currentOnlineOrdering,
        new_value: nextOnlineOrdering,
        metadata: { source: 'merchant_dashboard' },
    });

    return apiSuccess(nextOnlineOrdering);
}

import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';

export async function GET() {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p1' });
    if (!context.ok) {
        return context.response;
    }

    const [partnersResult, ordersResult] = await Promise.all([
        context.supabase
            .from('delivery_partners')
            .select('id, provider, status, updated_at, last_sync_at')
            .eq('restaurant_id', context.restaurantId)
            .order('provider', { ascending: true }),
        context.supabase
            .from('external_orders')
            .select('id, provider, normalized_status, created_at, acknowledged_at, source_channel')
            .eq('restaurant_id', context.restaurantId)
            .order('created_at', { ascending: false })
            .limit(300),
    ]);

    if (partnersResult.error) {
        return apiError(
            'Failed to fetch channel partners',
            500,
            'CHANNEL_PARTNERS_FETCH_FAILED',
            partnersResult.error.message
        );
    }
    if (ordersResult.error) {
        return apiError(
            'Failed to fetch external order summary',
            500,
            'EXTERNAL_ORDERS_FETCH_FAILED',
            ordersResult.error.message
        );
    }

    const partners = partnersResult.data ?? [];
    const orders = ordersResult.data ?? [];
    const now = Date.now();
    const oneDayAgo = now - 24 * 60 * 60 * 1000;

    const byProvider: Record<string, number> = {};
    const byStatus: Record<string, number> = {};
    let externalOrders24h = 0;
    let unackedOrders = 0;

    for (const order of orders) {
        byProvider[order.provider] = (byProvider[order.provider] ?? 0) + 1;
        byStatus[order.normalized_status] = (byStatus[order.normalized_status] ?? 0) + 1;
        if (order.acknowledged_at === null) {
            unackedOrders += 1;
        }
        if (new Date(order.created_at).getTime() >= oneDayAgo) {
            externalOrders24h += 1;
        }
    }

    const connectedPartners = partners.filter(partner => partner.status === 'connected').length;
    const degradedPartners = partners.filter(partner => partner.status === 'error').length;

    return apiSuccess({
        totals: {
            delivery_partners: partners.length,
            connected_partners: connectedPartners,
            degraded_partners: degradedPartners,
            external_orders_24h: externalOrders24h,
            external_orders_total: orders.length,
            unacked_orders: unackedOrders,
        },
        providers: byProvider,
        statuses: byStatus,
        partners,
    });
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { parseJsonBody } from '@/lib/api/validation';
import { writeAuditLog } from '@/lib/api/audit';
import { listActiveDiscountsForRestaurant } from '@/lib/discounts/service';

const CreateDiscountSchema = z.object({
    name: z.string().trim().min(1).max(120),
    name_am: z.string().trim().max(120).optional().nullable(),
    type: z.enum(['percentage', 'fixed_amount', 'bogo', 'item_override']),
    value: z.number().int().min(0),
    applies_to: z.enum(['order', 'item', 'category']).default('order'),
    target_menu_item_id: z.string().uuid().optional().nullable(),
    target_category_id: z.string().uuid().optional().nullable(),
    requires_manager_pin: z.boolean().optional().default(false),
    max_uses_per_day: z.number().int().min(1).optional().nullable(),
    valid_from: z.string().datetime().optional().nullable(),
    valid_until: z.string().datetime().optional().nullable(),
    is_active: z.boolean().optional().default(true),
});

export async function GET() {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p1' });
    if (!context.ok) {
        return context.response;
    }

    try {
        const discounts = await listActiveDiscountsForRestaurant(
            context.supabase,
            context.restaurantId
        );
        return apiSuccess({ discounts });
    } catch (error) {
        return apiError(
            'Failed to load discounts',
            500,
            'DISCOUNTS_FETCH_FAILED',
            error instanceof Error ? error.message : 'Unknown discount fetch error'
        );
    }
}

export async function POST(request: Request) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p1' });
    if (!context.ok) {
        return context.response;
    }

    const parsed = await parseJsonBody(request, CreateDiscountSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    if (parsed.data.applies_to === 'item' && !parsed.data.target_menu_item_id) {
        return apiError(
            'target_menu_item_id is required for item discounts',
            400,
            'DISCOUNT_TARGET_REQUIRED'
        );
    }

    if (parsed.data.applies_to === 'category' && !parsed.data.target_category_id) {
        return apiError(
            'target_category_id is required for category discounts',
            400,
            'DISCOUNT_TARGET_REQUIRED'
        );
    }

    const db = context.supabase;
    const { data, error } = await db
        .from('discounts')
        .insert({
            restaurant_id: context.restaurantId,
            ...parsed.data,
        })
        // HIGH-013: Explicit column selection
        .select(
            'id, restaurant_id, name, name_am, type, value, applies_to, target_menu_item_id, target_category_id, requires_manager_pin, max_uses_per_day, valid_from, valid_until, is_active, created_at, updated_at'
        )
        .single();

    if (error || !data) {
        return apiError('Failed to create discount', 500, 'DISCOUNT_CREATE_FAILED', error?.message);
    }

    await writeAuditLog(context.supabase, {
        restaurant_id: context.restaurantId,
        user_id: auth.user.id,
        action: 'discount_created',
        entity_type: 'discount',
        entity_id: data.id,
        metadata: { source: 'discounts_api' },
        new_value: data,
    });

    return apiSuccess({ discount: data }, 201);
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { parseJsonBody } from '@/lib/api/validation';
import { writeAuditLog } from '@/lib/api/audit';
import { isIdempotencyKeyValid, resolveIdempotencyKey } from '@/lib/api/idempotency';
import type { Json } from '@/types/database';
import type { SupabaseClient } from '@supabase/supabase-js';
import type { Database } from '@/types/database';

interface GiftCardRecord {
    id: string;
    restaurant_id: string;
    status: string;
    current_balance: number;
    expires_at: string | null;
    created_at?: string;
    updated_at?: string;
}

const GiftCardIdSchema = z.string().uuid();

const RedeemGiftCardSchema = z.object({
    amount: z.coerce.number().min(0.01).max(500000),
    order_id: z.string().uuid().optional(),
    metadata: z.record(z.string(), z.unknown()).optional(),
});

export async function POST(
    request: Request,
    routeContext: { params: Promise<{ giftCardId: string }> }
) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p2' });
    if (!context.ok) {
        return context.response;
    }

    const db = context.supabase as SupabaseClient<Database>;

    const { giftCardId } = await routeContext.params;
    const giftCardIdParsed = GiftCardIdSchema.safeParse(giftCardId);
    if (!giftCardIdParsed.success) {
        return apiError(
            'Invalid gift card id',
            400,
            'INVALID_GIFT_CARD_ID',
            giftCardIdParsed.error.flatten()
        );
    }

    const explicitIdempotencyKey = request.headers.get('x-idempotency-key');
    if (explicitIdempotencyKey && !isIdempotencyKeyValid(explicitIdempotencyKey)) {
        return apiError('Invalid idempotency key', 400, 'INVALID_IDEMPOTENCY_KEY');
    }
    const idempotencyKey = resolveIdempotencyKey(explicitIdempotencyKey);

    const parsed = await parseJsonBody(request, RedeemGiftCardSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    const { data: giftCard, error: giftCardError } = (await db
        .from('gift_cards')
        // HIGH-013: Explicit column selection
        .select(
            'id, restaurant_id, code, currency, initial_balance, current_balance, status, expires_at, metadata, created_by, created_at, updated_at'
        )
        .eq('id', giftCardIdParsed.data)
        .eq('restaurant_id', context.restaurantId)
        .maybeSingle()) as { data: GiftCardRecord | null; error: unknown };

    if (giftCardError) {
        return apiError(
            'Failed to load gift card',
            500,
            'GIFT_CARD_FETCH_FAILED',
            (giftCardError as { message?: string })?.message ?? 'Unknown error'
        );
    }
    if (!giftCard) {
        return apiError('Gift card not found', 404, 'GIFT_CARD_NOT_FOUND');
    }
    if (giftCard.status !== 'active') {
        return apiError('Gift card is not active', 409, 'GIFT_CARD_NOT_ACTIVE');
    }

    if (giftCard.expires_at && new Date(giftCard.expires_at).getTime() < Date.now()) {
        return apiError('Gift card is expired', 409, 'GIFT_CARD_EXPIRED');
    }

    const nextBalance =
        Number(Number(giftCard.current_balance).toFixed(2)) - Number(parsed.data.amount.toFixed(2));
    if (nextBalance < 0) {
        return apiError('Insufficient gift card balance', 409, 'GIFT_CARD_INSUFFICIENT_BALANCE');
    }

    const nextStatus = nextBalance === 0 ? 'redeemed' : 'active';

    const { data: updated, error: updateError } = (await db
        .from('gift_cards')
        .update({
            current_balance: nextBalance,
            status: nextStatus,
            updated_at: new Date().toISOString(),
        })
        .eq('id', giftCard.id)
        .eq('restaurant_id', context.restaurantId)
        // HIGH-013: Explicit column selection
        .select(
            'id, restaurant_id, code, currency, initial_balance, current_balance, status, expires_at, metadata, created_by, created_at, updated_at'
        )
        .single()) as { data: GiftCardRecord | null; error: unknown };

    if (updateError) {
        return apiError(
            'Failed to redeem gift card',
            500,
            'GIFT_CARD_REDEEM_FAILED',
            (updateError as { message?: string })?.message ?? 'Unknown error'
        );
    }

    const { data: transaction, error: txError } = (await db
        .from('gift_card_transactions')
        .insert({
            restaurant_id: context.restaurantId,
            gift_card_id: giftCard.id,
            order_id: parsed.data.order_id ?? null,
            amount_delta: -Number(parsed.data.amount.toFixed(2)),
            balance_after: nextBalance,
            type: 'redeem',
            metadata: {
                source: 'merchant_dashboard',
                ...parsed.data.metadata,
                idempotency_key: idempotencyKey,
            } as Json,
            created_by: auth.user.id,
        })
        // HIGH-013: Explicit column selection
        .select(
            'id, restaurant_id, gift_card_id, order_id, amount_delta, balance_after, type, metadata, created_by, created_at'
        )
        .single()) as { data: { id: string } | null; error: unknown };

    if (txError) {
        return apiError(
            'Failed to create gift card transaction',
            500,
            'GIFT_CARD_TRANSACTION_CREATE_FAILED',
            (txError as { message?: string })?.message ?? 'Unknown error'
        );
    }

    await writeAuditLog(context.supabase as SupabaseClient<Database>, {
        restaurant_id: context.restaurantId,
        user_id: auth.user.id,
        action: 'gift_card_redeemed',
        entity_type: 'gift_card',
        entity_id: giftCard.id,
        old_value: {
            current_balance: giftCard.current_balance,
            status: giftCard.status,
        },
        new_value: {
            current_balance: (updated as GiftCardRecord).current_balance,
            status: (updated as GiftCardRecord).status,
            amount: parsed.data.amount,
        },
        metadata: {
            order_id: parsed.data.order_id ?? null,
            transaction_id: (transaction as { id: string }).id,
            idempotency_key: idempotencyKey,
        },
    });

    return apiSuccess({
        gift_card: updated,
        transaction,
        idempotency_key: idempotencyKey,
    });
}

