import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import {
    getAuthenticatedUser,
    getAuthorizedRestaurantContext,
    getDeviceContext,
} from '@/lib/api/authz';
import { parseJsonBody } from '@/lib/api/validation';
import { writeAuditLog } from '@/lib/api/audit';

const CourseFireModeSchema = z.object({
    fire_mode: z.enum(['auto', 'manual']).optional(),
    current_course: z.enum(['appetizer', 'main', 'dessert', 'beverage', 'side']).optional(),
});

export async function PATCH(request: Request, context: { params: Promise<{ orderId: string }> }) {
    const auth = await getAuthenticatedUser();
    let actorUserId: string | null = null;
    let restaurantId: string;
    let db: Awaited<ReturnType<typeof getAuthorizedRestaurantContext>>['supabase'] | undefined;

    if (auth.ok) {
        const restaurantContext = await getAuthorizedRestaurantContext(auth.user.id);
        if (!restaurantContext.ok) {
            return restaurantContext.response;
        }
        actorUserId = auth.user.id;
        restaurantId = restaurantContext.restaurantId;
        db = restaurantContext.supabase;
    } else {
        const deviceContext = await getDeviceContext(request);
        if (!deviceContext.ok) {
            return auth.response;
        }
        restaurantId = deviceContext.restaurantId;
        db = deviceContext.admin;
    }

    const parsed = await parseJsonBody(request, CourseFireModeSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    const { orderId } = await context.params;

    // Get current order to check status
    const { data: order, error: orderError } = await db
        .from('orders')
        .select('id, status, fire_mode, current_course')
        .eq('restaurant_id', restaurantId)
        .eq('id', orderId)
        .maybeSingle();

    if (orderError) {
        return apiError('Failed to load order', 500, 'ORDER_FETCH_FAILED', orderError.message);
    }

    if (!order) {
        return apiError('Order not found', 404, 'ORDER_NOT_FOUND');
    }

    // Build update payload
    const updatePayload: Record<string, unknown> = {};

    if (parsed.data.fire_mode !== undefined) {
        updatePayload.fire_mode = parsed.data.fire_mode;
    }

    if (parsed.data.current_course !== undefined) {
        updatePayload.current_course = parsed.data.current_course;
    }

    if (Object.keys(updatePayload).length === 0) {
        return apiError('No valid fields to update', 400, 'NO_FIELDS_TO_UPDATE');
    }

    const { data: updatedOrder, error: updateError } = await db
        .from('orders')
        .update(updatePayload)
        .eq('restaurant_id', restaurantId)
        .eq('id', orderId)
        .select('id, fire_mode, current_course')
        .single();

    if (updateError) {
        return apiError('Failed to update order', 500, 'ORDER_UPDATE_FAILED', updateError.message);
    }

    await writeAuditLog(db, {
        restaurant_id: restaurantId,
        user_id: actorUserId,
        action: 'order_course_fire_updated',
        entity_type: 'order',
        entity_id: orderId,
        metadata: {
            previous_fire_mode: order.fire_mode,
            new_fire_mode: updatedOrder.fire_mode,
            previous_course: order.current_course,
            new_course: updatedOrder.current_course,
        },
    });

    return apiSuccess({
        order: {
            id: updatedOrder.id,
            fire_mode: updatedOrder.fire_mode,
            current_course: updatedOrder.current_course,
        },
    });
}

/**
 * Price Override API Endpoint
 * TASK-POS-001: Price Overrides with Audit Trail
 *
 * POST /api/orders/[orderId]/items/[itemId]/override-price
 */

import { NextRequest, NextResponse } from 'next/server';
import { createServerClient } from '@supabase/ssr';
import { cookies } from 'next/headers';
import { logger } from '@/lib/logger';
import {
    canOverridePrices,
    createPriceOverride,
    validatePriceOverrideInput,
} from '@/lib/services/priceOverrideService';

const log = logger.child('merchant-operations/orders/items/override-price');

export async function POST(
    request: NextRequest,
    { params }: { params: Promise<{ orderId: string; itemId: string }> }
) {
    try {
        const { orderId, itemId } = await params;
        const cookieStore = await cookies();

        const supabase = createServerClient(
            process.env.NEXT_PUBLIC_SUPABASE_URL!,
            process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY!,
            {
                cookies: {
                    getAll() {
                        return cookieStore.getAll();
                    },
                    setAll(cookiesToSet) {
                        try {
                            cookiesToSet.forEach(({ name, value, options }) =>
                                cookieStore.set(name, value, options)
                            );
                        } catch {
                            // Ignore errors in middleware
                        }
                    },
                },
            }
        );

        // Get authenticated user
        const {
            data: { user },
            error: authError,
        } = await supabase.auth.getUser();

        if (authError || !user) {
            return NextResponse.json(
                { error: { code: 'UNAUTHORIZED', message: 'Authentication required' } },
                { status: 401 }
            );
        }

        // Parse request body
        const body = await request.json();

        // Validate input
        const validation = validatePriceOverrideInput({
            orderId,
            orderItemId: itemId,
            ...body,
        });

        if (!validation.valid) {
            return NextResponse.json(
                {
                    error: {
                        code: 'VALIDATION_ERROR',
                        message: 'Invalid input',
                        details: validation.errors,
                    },
                },
                { status: 400 }
            );
        }

        // Get user's restaurant membership
        const { data: staffEntry, error: staffError } = await supabase
            .from('restaurant_staff')
            .select('restaurant_id, role')
            .eq('user_id', user.id)
            .eq('is_active', true)
            .maybeSingle();

        if (staffError || !staffEntry) {
            return NextResponse.json(
                { error: { code: 'FORBIDDEN', message: 'Not a staff member' } },
                { status: 403 }
            );
        }

        const restaurantId = staffEntry.restaurant_id;

        // Check permission
        const permissionCheck = await canOverridePrices(supabase, user.id, restaurantId);
        if (!permissionCheck.allowed) {
            return NextResponse.json(
                { error: { code: 'FORBIDDEN', message: permissionCheck.reason } },
                { status: 403 }
            );
        }

        // Create price override
        const result = await createPriceOverride(supabase, restaurantId, {
            orderId,
            orderItemId: itemId,
            originalPrice: body.originalPrice,
            newPrice: body.newPrice,
            reasonCode: body.reasonCode,
            reasonNotes: body.reasonNotes,
            staffId: user.id,
            approvedBy: body.approvedBy,
        });

        if (!result.success) {
            return NextResponse.json(
                { error: { code: 'OVERRIDE_FAILED', message: result.error } },
                { status: 400 }
            );
        }

        // Log to audit
        await supabase.from('audit_logs').insert({
            action: 'price_override',
            entity_type: 'order_item',
            entity_id: itemId,
            restaurant_id: restaurantId,
            user_id: user.id,
            metadata: {
                order_id: orderId,
                original_price: body.originalPrice,
                new_price: body.newPrice,
                reason_code: body.reasonCode,
            },
        });

        return NextResponse.json({
            data: result.override,
            meta: { message: 'Price override applied successfully' },
        });
    } catch (error) {
        log.error('Error', error);
        return NextResponse.json(
            { error: { code: 'INTERNAL_ERROR', message: 'An unexpected error occurred' } },
            { status: 500 }
        );
    }
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { sendOrderStatusSms } from '@/lib/notifications/sms';
import { writeAuditLog } from '@/lib/api/audit';
import { isIdempotencyKeyValid, resolveIdempotencyKey } from '@/lib/api/idempotency';
import type { SupabaseClient } from '@supabase/supabase-js';
import type { Database } from '@/types/database';

const OrderIdSchema = z.string().uuid();

const NotifyStatusSchema = z.object({
    status: z.enum(['preparing', 'ready', 'served', 'completed', 'cancelled']),
    notify_methods: z
        .array(z.enum(['sms', 'push']))
        .optional()
        .default(['sms']),
    custom_message: z.string().max(500).optional(),
    eta_minutes: z.number().int().min(1).max(180).optional(),
});

/**
 * POST /api/orders/[orderId]/notify-status
 *
 * Sends order status notifications to the customer via SMS and/or push.
 * This is the P0 SMS Order Notifications feature.
 */
export async function POST(
    request: Request,
    routeContext: { params: Promise<{ orderId: string }> }
) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id);
    if (!context.ok) {
        return context.response;
    }

    const { orderId } = await routeContext.params;
    const orderIdParsed = OrderIdSchema.safeParse(orderId);
    if (!orderIdParsed.success) {
        return apiError('Invalid order id', 400, 'INVALID_ORDER_ID', orderIdParsed.error.flatten());
    }

    const explicitIdempotencyKey = request.headers.get('x-idempotency-key');
    if (explicitIdempotencyKey && !isIdempotencyKeyValid(explicitIdempotencyKey)) {
        return apiError('Invalid idempotency key', 400, 'INVALID_IDEMPOTENCY_KEY');
    }
    const idempotencyKey = resolveIdempotencyKey(explicitIdempotencyKey);

    const parsed = await parseJsonBody(request, NotifyStatusSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    const db = context.supabase as SupabaseClient<Database>;

    // Fetch the order with customer details
    const { data: order, error: orderError } = (await db
        .from('orders')
        .select(
            `
            id,
            order_number,
            status,
            customer_phone,
            customer_name,
            restaurant_id,
            table_sessions (
                id,
                guests (
                    id,
                    phone,
                    user_id
                )
            )
        `
        )
        .eq('id', orderIdParsed.data)
        .eq('restaurant_id', context.restaurantId)
        .maybeSingle()) as {
        data: {
            id: string;
            order_number: string;
            status: string | null;
            customer_phone: string | null;
            customer_name: string | null;
            restaurant_id: string;
            table_sessions: {
                id: string;
                guests: {
                    id: string;
                    phone: string | null;
                    user_id: string | null;
                } | null;
            } | null;
        } | null;
        error: { message: string } | null;
    };

    if (orderError) {
        return apiError('Failed to fetch order', 500, 'ORDER_FETCH_FAILED', orderError.message);
    }

    if (!order) {
        return apiError('Order not found', 404, 'ORDER_NOT_FOUND');
    }

    // Determine the phone number to notify
    let phoneToNotify = order.customer_phone;

    // If no direct customer phone, check table session guests
    if (!phoneToNotify && order.table_sessions?.guests?.phone) {
        phoneToNotify = order.table_sessions.guests.phone;
    }

    if (!phoneToNotify) {
        return apiError(
            'No customer phone number available for notification',
            400,
            'NO_CUSTOMER_PHONE'
        );
    }

    const notifyMethods = parsed.data.notify_methods ?? ['sms'];
    const results: { method: string; success: boolean; error?: string }[] = [];

    // Send SMS notification
    if (notifyMethods.includes('sms')) {
        const smsResult = await sendOrderStatusSms({
            toPhone: phoneToNotify,
            orderNumber: order.order_number,
            status: parsed.data.status,
            etaMinutes: parsed.data.eta_minutes,
        });

        results.push({
            method: 'sms',
            success: smsResult.success,
            error: smsResult.error,
        });

        // Log to notification_logs if available
        try {
            await db.from('notification_logs').insert({
                restaurant_id: context.restaurantId,
                order_id: order.id,
                type: 'order_status_sms',
                recipient: phoneToNotify,
                status: smsResult.success ? 'sent' : 'failed',
                provider: smsResult.provider,
                error_message: smsResult.error ?? null,
                metadata: {
                    order_status: parsed.data.status,
                    idempotency_key: idempotencyKey,
                },
            });
        } catch {
            // Non-critical: don't fail if logging fails
        }
    }

    // Send Push notification (if push token exists)
    if (notifyMethods.includes('push')) {
        try {
            // Check for push tokens for this customer
            const { data: pushTokens } = await db
                .from('push_tokens')
                .select('token')
                .eq('phone', phoneToNotify)
                .eq('is_active', true);

            if (pushTokens && pushTokens.length > 0) {
                // Import push notification service
                const { sendBatchPushNotifications } = await import('@/lib/notifications/push');

                // Send to all registered devices
                const pushResults = await sendBatchPushNotifications(
                    pushTokens.map((t: { token: string }) => ({
                        token: t.token,
                        title: `Order #${order.order_number} Update`,
                        body: `Your order status is now: ${parsed.data.status}`,
                        data: {
                            order_id: order.id,
                            order_number: order.order_number,
                            status: parsed.data.status,
                            type: 'order_status_update',
                        },
                    }))
                );

                const anySuccess = pushResults.some(r => r.success);
                const errors = pushResults
                    .filter(r => !r.success)
                    .map(r => r.error)
                    .filter(Boolean);

                results.push({
                    method: 'push',
                    success: anySuccess,
                    error: errors.length > 0 ? errors.join('; ') : undefined,
                });
            } else {
                results.push({
                    method: 'push',
                    success: false,
                    error: 'No push tokens registered for this customer',
                });
            }
        } catch (pushError) {
            results.push({
                method: 'push',
                success: false,
                error: pushError instanceof Error ? pushError.message : 'Push notification failed',
            });
        }
    }

    // Update order status if provided
    if (parsed.data.status && order.status !== parsed.data.status) {
        await db
            .from('orders')
            .update({
                status: parsed.data.status,
                updated_at: new Date().toISOString(),
            })
            .eq('id', order.id);
    }

    // Write audit log
    await writeAuditLog(context.supabase as SupabaseClient<Database>, {
        restaurant_id: context.restaurantId,
        user_id: auth.user.id,
        action: 'order_status_notification_sent',
        entity_type: 'order',
        entity_id: order.id,
        new_value: {
            status: parsed.data.status,
            notify_methods: notifyMethods,
            results,
        },
        metadata: {
            customer_phone: phoneToNotify.slice(-4).padStart(phoneToNotify.length, '*'), // Masked
            idempotency_key: idempotencyKey,
        },
    });

    const allSuccess = results.every(r => r.success);

    return apiSuccess(
        {
            order_id: order.id,
            order_number: order.order_number,
            notifications: results,
            all_success: allSuccess,
            idempotency_key: idempotencyKey,
        },
        allSuccess ? 200 : 207 // 207 Multi-Status if partial failure
    );
}

// Helper function to parse JSON body with Zod validation
async function parseJsonBody<T extends z.ZodTypeAny>(
    request: Request,
    schema: T
): Promise<{ success: true; data: z.infer<T> } | { success: false; response: Response }> {
    try {
        const body = await request.json();
        const parsed = schema.safeParse(body);
        if (!parsed.success) {
            return {
                success: false,
                response: apiError(
                    'Invalid request body',
                    400,
                    'VALIDATION_ERROR',
                    parsed.error.flatten()
                ),
            };
        }
        return { success: true, data: parsed.data };
    } catch {
        return {
            success: false,
            response: apiError('Invalid JSON body', 400, 'INVALID_JSON'),
        };
    }
}

import { createClient } from '@/lib/supabase/server';
import { apiError, apiSuccess } from '@/lib/api/response';
import { enforcePilotAccess } from '@/lib/api/pilotGate';

async function resolveRestaurantIdForUser(userId: string) {
    const supabase = await createClient();

    // Parallelize both lookups ΓÇö only one will have a result
    const [staffResult, agencyResult] = await Promise.all([
        supabase
            .from('restaurant_staff')
            .select('restaurant_id')
            .eq('user_id', userId)
            .eq('is_active', true)
            .limit(1)
            .maybeSingle(),
        supabase.from('agency_users').select('restaurant_ids').eq('user_id', userId).maybeSingle(),
    ]);

    if (staffResult.error) return { error: staffResult.error.message };
    if (staffResult.data?.restaurant_id) return { restaurantId: staffResult.data.restaurant_id };

    if (agencyResult.error) return { error: agencyResult.error.message };
    return { restaurantId: agencyResult.data?.restaurant_ids?.[0] ?? null };
}

export async function GET(_request: Request, context: { params: Promise<{ orderId: string }> }) {
    try {
        const { orderId } = await context.params;
        const supabase = await createClient();

        // Get authenticated user
        const {
            data: { user },
            error: userError,
        } = await supabase.auth.getUser();

        if (userError || !user) {
            return apiError('Unauthorized', 401, 'UNAUTHORIZED');
        }

        // Now resolve restaurant + fetch order + fetch events all in parallel
        const { restaurantId, error: restaurantError } = await resolveRestaurantIdForUser(user.id);

        if (restaurantError) {
            return apiError(
                'Failed to resolve restaurant context',
                500,
                'RESTAURANT_RESOLVE_FAILED',
                restaurantError
            );
        }
        if (!restaurantId) {
            return apiError('No restaurant found for user', 404, 'RESTAURANT_NOT_FOUND');
        }

        const pilotGateResponse = enforcePilotAccess(restaurantId);
        if (pilotGateResponse) return pilotGateResponse;

        // Parallelize: order fetch + events fetch at the same time
        const [{ data: order, error: orderError }, { data: events, error: eventsError }] =
            await Promise.all([
                supabase
                    .from('orders')
                    .select(
                        'id, restaurant_id, table_number, status, total_price, customer_name, customer_phone, notes, idempotency_key, created_at, updated_at'
                    )
                    .eq('restaurant_id', restaurantId)
                    .eq('id', orderId)
                    .maybeSingle(),
                supabase
                    .from('order_events')
                    .select(
                        'id, event_type, from_status, to_status, created_at, actor_user_id, metadata'
                    )
                    .eq('restaurant_id', restaurantId)
                    .eq('order_id', orderId)
                    .order('created_at', { ascending: false })
                    .limit(50),
            ]);

        if (orderError) {
            return apiError('Failed to fetch order', 500, 'ORDER_FETCH_FAILED', orderError.message);
        }
        if (!order) {
            return apiError('Order not found', 404, 'ORDER_NOT_FOUND');
        }
        if (eventsError) {
            return apiError(
                'Failed to fetch order events',
                500,
                'ORDER_EVENTS_FETCH_FAILED',
                eventsError.message
            );
        }

        return apiSuccess({
            order: { ...order, total_price: Number(order.total_price ?? 0) / 100 },
            events: events ?? [],
        });
    } catch (error) {
        return apiError(
            'Internal server error',
            500,
            'INTERNAL_ERROR',
            error instanceof Error ? error.message : 'Unknown error'
        );
    }
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import {
    getAuthenticatedUser,
    getAuthorizedRestaurantContext,
    getDeviceContext,
} from '@/lib/api/authz';
import { parseJsonBody } from '@/lib/api/validation';
import { writeAuditLog } from '@/lib/api/audit';
import { resolveIdempotencyKey } from '@/lib/api/idempotency';
import type { Json, TablesInsert } from '@/types/database';
import { redisRateLimiters } from '@/lib/security';
import type { NextRequest } from 'next/server';
import { createClient as _createClient } from '@/lib/supabase/server';

const SplitMethodSchema = z.enum(['even', 'items', 'custom']);

const SplitRequestLineSchema = z.object({
    guest_name: z.string().trim().max(80).optional(),
    item_ids: z.array(z.string().uuid()).max(250).optional(),
    amount: z.coerce.number().min(0).max(100000000).optional(),
    metadata: z.record(z.string(), z.unknown()).optional(),
});

const UpsertOrderSplitSchema = z.object({
    method: SplitMethodSchema,
    splits: z.array(SplitRequestLineSchema).min(2).max(20),
});

type SplitMethod = z.infer<typeof SplitMethodSchema>;
type SplitRequest = z.infer<typeof UpsertOrderSplitSchema>;

function toCents(amount: number): number {
    return Math.round(amount * 100);
}

function fromCents(cents: number): number {
    return Number((cents / 100).toFixed(2));
}

function buildEvenAmounts(totalPrice: number, splitCount: number): number[] {
    const totalCents = toCents(totalPrice);
    const base = Math.floor(totalCents / splitCount);
    const remainder = totalCents - base * splitCount;

    const cents = Array.from({ length: splitCount }, (_, idx) =>
        idx < remainder ? base + 1 : base
    );
    return cents.map(fromCents);
}

export async function GET(_request: Request, context: { params: Promise<{ orderId: string }> }) {
    const auth = await getAuthenticatedUser();
    let restaurantId: string;
    let db: Awaited<ReturnType<typeof getAuthorizedRestaurantContext>>['supabase'] | undefined;

    if (auth.ok) {
        const restaurantContext = await getAuthorizedRestaurantContext(auth.user.id);
        if (!restaurantContext.ok) {
            return restaurantContext.response;
        }
        restaurantId = restaurantContext.restaurantId;
        db = restaurantContext.supabase;
    } else {
        const deviceContext = await getDeviceContext(_request);
        if (!deviceContext.ok) {
            return auth.response;
        }
        restaurantId = deviceContext.restaurantId;
        db = deviceContext.admin;
    }

    const { orderId } = await context.params;

    const { data: order, error: orderError } = await db
        .from('orders')
        .select('id, total_price, status')
        .eq('restaurant_id', restaurantId)
        .eq('id', orderId)
        .maybeSingle();

    if (orderError) {
        return apiError('Failed to load order', 500, 'ORDER_FETCH_FAILED', orderError.message);
    }
    if (!order) {
        return apiError('Order not found', 404, 'ORDER_NOT_FOUND');
    }

    // HIGH-013: Explicit column selection
    const { data: splits, error: splitsError } = await db
        .from('order_check_splits')
        .select(
            'id, restaurant_id, order_id, split_index, split_label, requested_amount, computed_amount, status, metadata, created_by, created_at, updated_at'
        )
        .eq('restaurant_id', restaurantId)
        .eq('order_id', orderId)
        .order('split_index', { ascending: true });

    if (splitsError) {
        return apiError(
            'Failed to load check splits',
            500,
            'ORDER_SPLITS_FETCH_FAILED',
            splitsError.message
        );
    }

    const splitRows = (splits ?? []) as unknown as Array<Record<string, unknown>>;
    const splitIds = splitRows.map(row => String(row.id)).filter(Boolean);

    let splitItems: Array<Record<string, unknown>> = [];
    let splitPayments: Array<Record<string, unknown>> = [];
    let orderItems: Array<Record<string, unknown>> = [];

    const { data: orderItemsData, error: orderItemsError } = await db
        .from('order_items')
        .select('id, name, quantity, price, notes, created_at')
        .eq('order_id', orderId)
        .order('created_at', { ascending: true });

    if (orderItemsError) {
        return apiError(
            'Failed to load order items',
            500,
            'ORDER_ITEMS_FETCH_FAILED',
            orderItemsError.message
        );
    }

    orderItems = (orderItemsData ?? []) as Array<Record<string, unknown>>;

    if (splitIds.length > 0) {
        const [
            { data: splitItemsData, error: splitItemsError },
            { data: splitPaymentsData, error: splitPaymentsError },
        ] = await Promise.all([
            db
                .from('order_check_split_items')
                .select(
                    'id, restaurant_id, order_id, split_id, order_item_id, quantity, line_amount, idempotency_key, created_at'
                )
                .eq('restaurant_id', restaurantId)
                .eq('order_id', orderId),
            db
                .from('payments')
                .select('id, split_id, amount, tip_amount, method, status, created_at')
                .eq('restaurant_id', restaurantId)
                .in('split_id', splitIds),
        ]);

        if (splitItemsError) {
            return apiError(
                'Failed to load split items',
                500,
                'ORDER_SPLIT_ITEMS_FETCH_FAILED',
                splitItemsError.message
            );
        }
        if (splitPaymentsError) {
            return apiError(
                'Failed to load split payments',
                500,
                'ORDER_SPLIT_PAYMENTS_FETCH_FAILED',
                splitPaymentsError.message
            );
        }

        splitItems = (splitItemsData ?? []) as unknown as Array<Record<string, unknown>>;
        splitPayments = (splitPaymentsData ?? []) as Array<Record<string, unknown>>;
    }

    const inferredMethod: SplitMethod =
        splitItems.length > 0
            ? 'items'
            : splitRows.some(
                    row => row.requested_amount !== null && row.requested_amount !== undefined
                )
              ? 'custom'
              : 'even';

    return apiSuccess({
        order: {
            id: order.id,
            total_price: Number(order.total_price ?? 0),
            status: order.status,
        },
        method: inferredMethod,
        order_items: orderItems,
        splits: splitRows,
        split_items: splitItems,
        split_payments: splitPayments,
    });
}

type ComputedSplit = {
    split_index: number;
    split_label: string | null;
    requested_amount: number | null;
    computed_amount: number;
    item_ids: string[];
    metadata: Json;
};

export async function POST(request: Request, context: { params: Promise<{ orderId: string }> }) {
    // Apply rate limiting for order split (mutation endpoint)
    const rateLimitResponse = await redisRateLimiters.mutation(request as NextRequest);
    if (rateLimitResponse) {
        return rateLimitResponse;
    }

    const auth = await getAuthenticatedUser();
    let actorUserId: string | null = null;
    let restaurantId: string;
    let db: Awaited<ReturnType<typeof getAuthorizedRestaurantContext>>['supabase'] | undefined;

    if (auth.ok) {
        const restaurantContext = await getAuthorizedRestaurantContext(auth.user.id);
        if (!restaurantContext.ok) {
            return restaurantContext.response;
        }
        actorUserId = auth.user.id;
        restaurantId = restaurantContext.restaurantId;
        db = restaurantContext.supabase;
    } else {
        const deviceContext = await getDeviceContext(request);
        if (!deviceContext.ok) {
            return auth.response;
        }
        restaurantId = deviceContext.restaurantId;
        db = deviceContext.admin;
    }

    // Extract idempotency key from headers for retry safety
    const explicitIdempotencyKey = request.headers.get('x-idempotency-key');
    const idempotencyKey = resolveIdempotencyKey(explicitIdempotencyKey);

    const parsed = await parseJsonBody(request, UpsertOrderSplitSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    const payload = parsed.data;
    const { orderId } = await context.params;

    const { data: order, error: orderError } = await db
        .from('orders')
        .select('id, total_price, status')
        .eq('restaurant_id', restaurantId)
        .eq('id', orderId)
        .maybeSingle();

    if (orderError) {
        return apiError('Failed to load order', 500, 'ORDER_FETCH_FAILED', orderError.message);
    }
    if (!order) {
        return apiError('Order not found', 404, 'ORDER_NOT_FOUND');
    }
    if (order.status === 'cancelled' || order.status === 'completed') {
        return apiError(
            'Order cannot be split in current status',
            409,
            'ORDER_SPLIT_INVALID_STATUS'
        );
    }

    const totalPrice = Number(order.total_price ?? 0);
    const computed = await computeSplitPlan(db, restaurantId, orderId, totalPrice, payload);
    if (!computed.ok) {
        return computed.response;
    }

    const { error: deleteItemsError } = await db
        .from('order_check_split_items')
        .delete()
        .eq('restaurant_id', restaurantId)
        .eq('order_id', orderId);

    if (deleteItemsError) {
        return apiError(
            'Failed to reset existing split items',
            500,
            'ORDER_SPLIT_RESET_FAILED',
            deleteItemsError.message
        );
    }

    const { error: deleteSplitsError } = await db
        .from('order_check_splits')
        .delete()
        .eq('restaurant_id', restaurantId)
        .eq('order_id', orderId);

    if (deleteSplitsError) {
        return apiError(
            'Failed to reset existing splits',
            500,
            'ORDER_SPLIT_RESET_FAILED',
            deleteSplitsError.message
        );
    }

    const splitRowsToInsert: TablesInsert<'order_check_splits'>[] = computed.plan.map(split => ({
        restaurant_id: restaurantId,
        order_id: orderId,
        split_index: split.split_index,
        split_label: split.split_label,
        requested_amount: split.requested_amount,
        computed_amount: split.computed_amount,
        status: 'open',
        metadata: split.metadata,
        created_by: actorUserId,
    }));

    // HIGH-013: Explicit column selection
    const { data: insertedSplits, error: insertSplitsError } = await db
        .from('order_check_splits')
        .insert(splitRowsToInsert)
        .select(
            'id, restaurant_id, order_id, split_index, split_label, requested_amount, computed_amount, status, metadata, created_by, created_at, updated_at'
        )
        .order('split_index', { ascending: true });

    if (insertSplitsError) {
        return apiError(
            'Failed to create check splits',
            500,
            'ORDER_SPLIT_CREATE_FAILED',
            insertSplitsError.message
        );
    }

    const splitIdByIndex = new Map<number, string>();
    for (const row of (insertedSplits ?? []) as unknown as Array<Record<string, unknown>>) {
        const splitIndex = Number(row.split_index);
        const splitId = String(row.id ?? '');
        if (Number.isFinite(splitIndex) && splitId.length > 0) {
            splitIdByIndex.set(splitIndex, splitId);
        }
    }

    const splitItemRows = computed.plan.flatMap(split => {
        const splitId = splitIdByIndex.get(split.split_index);
        if (!splitId) return [];
        return split.item_ids.map(orderItemId => ({
            restaurant_id: restaurantId,
            order_id: orderId,
            split_id: splitId,
            order_item_id: orderItemId,
            quantity: 1 as number,
            line_amount: computed.itemAmountById.get(orderItemId) ?? 0,
        }));
    }) as TablesInsert<'order_check_split_items'>[];

    let insertedSplitItems: Array<Record<string, unknown>> = [];
    if (splitItemRows.length > 0) {
        // HIGH-013: Explicit column selection
        const { data: insertItemsData, error: insertItemsError } = await db
            .from('order_check_split_items')
            .insert(splitItemRows)
            .select(
                'id, restaurant_id, order_id, split_id, order_item_id, quantity, line_amount, idempotency_key, created_at'
            );

        if (insertItemsError) {
            return apiError(
                'Failed to create split item mapping',
                500,
                'ORDER_SPLIT_ITEMS_CREATE_FAILED',
                insertItemsError.message
            );
        }

        insertedSplitItems = (insertItemsData ?? []) as unknown as Array<Record<string, unknown>>;
    }

    await writeAuditLog(db, {
        restaurant_id: restaurantId,
        user_id: actorUserId,
        action: 'order_split_configured',
        entity_type: 'order',
        entity_id: orderId,
        metadata: {
            method: payload.method,
            split_count: payload.splits.length,
            source: 'merchant_dashboard',
            idempotency_key: idempotencyKey,
        },
        new_value: {
            method: payload.method,
            splits: splitRowsToInsert,
        } as Json,
    });

    return apiSuccess(
        {
            order_id: orderId,
            method: payload.method,
            splits: insertedSplits ?? [],
            split_items: insertedSplitItems,
        },
        201
    );
}

async function computeSplitPlan(
    db: Awaited<ReturnType<typeof getAuthorizedRestaurantContext>>['supabase'],
    restaurantId: string,
    orderId: string,
    totalPrice: number,
    payload: SplitRequest
): Promise<
    | { ok: true; plan: ComputedSplit[]; itemAmountById: Map<string, number> }
    | { ok: false; response: ReturnType<typeof apiError> }
> {
    const plan: ComputedSplit[] = [];
    const itemAmountById = new Map<string, number>();
    const splitCount = payload.splits.length;

    if (payload.method === 'even') {
        const amounts = buildEvenAmounts(totalPrice, splitCount);
        for (let index = 0; index < splitCount; index += 1) {
            const input = payload.splits[index];
            plan.push({
                split_index: index,
                split_label: input.guest_name?.trim() || `Guest ${index + 1}`,
                requested_amount: null,
                computed_amount: amounts[index],
                item_ids: [],
                metadata: (input.metadata ?? {}) as Json,
            });
        }
        return { ok: true, plan, itemAmountById };
    }

    if (payload.method === 'custom') {
        const amounts = payload.splits.map((split, index) => {
            if (
                typeof split.amount !== 'number' ||
                !Number.isFinite(split.amount) ||
                split.amount <= 0
            ) {
                return { index, amount: null };
            }
            return { index, amount: Number(split.amount.toFixed(2)) };
        });

        if (amounts.some(entry => entry.amount === null)) {
            return {
                ok: false,
                response: apiError(
                    'Custom split requires an amount for each guest',
                    400,
                    'ORDER_SPLIT_INVALID_CUSTOM_AMOUNTS'
                ),
            };
        }

        const sum = amounts.reduce((acc, entry) => acc + (entry.amount ?? 0), 0);
        if (Math.abs(sum - totalPrice) > 0.01) {
            return {
                ok: false,
                response: apiError(
                    'Custom split amounts must match order total',
                    400,
                    'ORDER_SPLIT_TOTAL_MISMATCH',
                    {
                        expected_total: Number(totalPrice.toFixed(2)),
                        provided_total: Number(sum.toFixed(2)),
                    }
                ),
            };
        }

        for (const entry of amounts) {
            const input = payload.splits[entry.index];
            const amount = entry.amount ?? 0;
            plan.push({
                split_index: entry.index,
                split_label: input.guest_name?.trim() || `Guest ${entry.index + 1}`,
                requested_amount: amount,
                computed_amount: amount,
                item_ids: [],
                metadata: (input.metadata ?? {}) as Json,
            });
        }
        return { ok: true, plan, itemAmountById };
    }

    if (!db) {
        return {
            ok: false,
            response: apiError('Database not initialized', 500, 'DB_NOT_INITIALIZED'),
        };
    }

    if (!db) {
        return {
            ok: false,
            response: apiError('Database not initialized', 500, 'DB_NOT_INITIALIZED'),
        };
    }

    const { data: orderItems, error: orderItemsError } = await db
        .from('order_items')
        .select('id, quantity, price')
        .eq('order_id', orderId)
        .order('created_at', { ascending: true });

    if (orderItemsError) {
        return {
            ok: false,
            response: apiError(
                'Failed to load order items for split',
                500,
                'ORDER_ITEMS_FETCH_FAILED',
                orderItemsError.message
            ),
        };
    }

    const rows = (orderItems ?? []) as Array<Record<string, unknown>>;
    if (rows.length === 0) {
        return {
            ok: false,
            response: apiError(
                'Item-based split requires relational order items',
                409,
                'ORDER_SPLIT_ITEMS_NOT_AVAILABLE'
            ),
        };
    }

    const knownOrderItemIds = new Set<string>();
    for (const row of rows) {
        const id = String(row.id ?? '');
        const quantity = Number(row.quantity ?? 1);
        const unitPrice = Number(row.price ?? 0);
        const lineAmount = Number((quantity * unitPrice).toFixed(2));
        if (id.length > 0) {
            knownOrderItemIds.add(id);
            itemAmountById.set(id, lineAmount);
        }
    }

    const seen = new Set<string>();
    for (let index = 0; index < splitCount; index += 1) {
        const input = payload.splits[index];
        const itemIds = input.item_ids ?? [];

        if (itemIds.length === 0) {
            return {
                ok: false,
                response: apiError(
                    'Each split must include at least one order item',
                    400,
                    'ORDER_SPLIT_MISSING_ITEMS'
                ),
            };
        }

        const deduped = [...new Set(itemIds)];
        for (const itemId of deduped) {
            if (!knownOrderItemIds.has(itemId)) {
                return {
                    ok: false,
                    response: apiError(
                        'Split references unknown order item',
                        400,
                        'ORDER_SPLIT_UNKNOWN_ITEM',
                        { order_item_id: itemId }
                    ),
                };
            }
            if (seen.has(itemId)) {
                return {
                    ok: false,
                    response: apiError(
                        'Each order item can only belong to one split',
                        400,
                        'ORDER_SPLIT_DUPLICATE_ITEM',
                        { order_item_id: itemId }
                    ),
                };
            }
            seen.add(itemId);
        }

        const computedAmount = deduped.reduce(
            (acc, itemId) => acc + (itemAmountById.get(itemId) ?? 0),
            0
        );
        plan.push({
            split_index: index,
            split_label: input.guest_name?.trim() || `Guest ${index + 1}`,
            requested_amount: null,
            computed_amount: Number(computedAmount.toFixed(2)),
            item_ids: deduped,
            metadata: (input.metadata ?? {}) as Json,
        });
    }

    if (seen.size !== knownOrderItemIds.size) {
        return {
            ok: false,
            response: apiError(
                'Item split must allocate all order items',
                400,
                'ORDER_SPLIT_INCOMPLETE_ITEMS',
                { allocated_items: seen.size, total_items: knownOrderItemIds.size }
            ),
        };
    }

    const allocatedTotal = Number(
        plan.reduce((acc, split) => acc + split.computed_amount, 0).toFixed(2)
    );
    if (Math.abs(allocatedTotal - totalPrice) > 0.01) {
        return {
            ok: false,
            response: apiError(
                'Allocated split total does not match order total',
                400,
                'ORDER_SPLIT_TOTAL_MISMATCH',
                { expected_total: Number(totalPrice.toFixed(2)), allocated_total: allocatedTotal }
            ),
        };
    }

    return { ok: true, plan, itemAmountById };
}

import { NextRequest } from 'next/server';
import { z } from 'zod';
import { createClient } from '@/lib/supabase/server';
import { apiError, apiSuccess } from '@/lib/api/response';
import { trackApiMetric } from '@/lib/api/metrics';
import { enforcePilotAccess } from '@/lib/api/pilotGate';
import { sendOrderStatusSms } from '@/lib/notifications/sms';
import { createloleEvent } from '@/lib/events/contracts';
import { publishEvent } from '@/lib/events/runtime';
import { redisRateLimiters } from '@/lib/security';
import { monitoredQuery } from '@/lib/services/queryMonitor';
import { logger } from '@/lib/logger';

const log = logger.child('order-status');

const UpdateOrderStatusSchema = z.object({
    status: z.enum([
        'pending',
        'acknowledged',
        'preparing',
        'ready',
        'served',
        'completed',
        'cancelled',
    ]),
    type: z.enum(['kitchen', 'bar', 'general']).optional(),
});

const ALLOWED_TRANSITIONS: Record<string, string[]> = {
    pending: ['acknowledged', 'preparing', 'ready', 'cancelled'], // KDS can fast-track any order
    acknowledged: ['preparing', 'ready', 'cancelled'],
    preparing: ['ready', 'cancelled'],
    ready: ['served', 'completed', 'cancelled'],
    served: ['completed'],
    completed: [],
    cancelled: [],
};

function canTransition(current: string | null, next: string) {
    if (!current) return false;
    return (ALLOWED_TRANSITIONS[current] || []).includes(next);
}

export async function PATCH(
    request: NextRequest,
    context: { params: Promise<{ orderId: string }> }
) {
    // Apply rate limiting for order status updates (mutation endpoint)
    const rateLimitResponse = await redisRateLimiters.mutation(request);
    if (rateLimitResponse) {
        return rateLimitResponse;
    }

    const startedAt = Date.now();
    let responseStatus = 500;
    let restaurantIdForMetrics: string | null = null;

    try {
        const { orderId } = await context.params;
        const body = await request.json();
        const parsed = UpdateOrderStatusSchema.safeParse(body);

        if (!parsed.success) {
            responseStatus = 400;
            return apiError(
                'Invalid request payload',
                400,
                'INVALID_PAYLOAD',
                parsed.error.flatten()
            );
        }

        const supabase = await createClient();

        // Parallelize: auth check + order fetch at the same time
        const [
            {
                data: { user },
                error: userError,
            },
            { data: order, error: orderError },
        ] = await monitoredQuery(
            'orders:update-status:fetch-order',
            () =>
                Promise.all([
                    supabase.auth.getUser(),
                    supabase
                        .from('orders')
                        .select('id, restaurant_id, status')
                        .eq('id', orderId)
                        .maybeSingle(),
                ]),
            { orderId }
        );

        if (userError || !user) {
            responseStatus = 401;
            return apiError('Unauthorized', 401, 'UNAUTHORIZED');
        }

        if (orderError) {
            responseStatus = 500;
            return apiError('Failed to load order', 500, 'ORDER_FETCH_FAILED', orderError.message);
        }
        if (!order) {
            responseStatus = 404;
            return apiError('Order not found', 404, 'ORDER_NOT_FOUND');
        }

        restaurantIdForMetrics = order.restaurant_id;

        const pilotGateResponse = enforcePilotAccess(order.restaurant_id, request.method);
        if (pilotGateResponse) {
            responseStatus = pilotGateResponse.status;
            return pilotGateResponse;
        }

        // Staff auth check ΓÇö must be sequential (needs restaurant_id from order)
        const { data: staff, error: staffError } = await supabase
            .from('restaurant_staff')
            .select('id')
            .eq('restaurant_id', order.restaurant_id)
            .eq('user_id', user.id)
            .eq('is_active', true)
            .maybeSingle();

        if (staffError) {
            responseStatus = 500;
            return apiError(
                'Failed to verify staff access',
                500,
                'STAFF_ACCESS_CHECK_FAILED',
                staffError.message
            );
        }
        if (!staff) {
            responseStatus = 403;
            return apiError('Forbidden', 403, 'FORBIDDEN');
        }

        if (!canTransition(order.status, parsed.data.status)) {
            responseStatus = 409;
            return apiError(
                `Invalid status transition from "${order.status}" to "${parsed.data.status}"`,
                409,
                'INVALID_TRANSITION'
            );
        }

        const now = new Date().toISOString();
        const updatePayload: Record<string, string> = {
            status: parsed.data.status,
            updated_at: now,
        };
        if (parsed.data.status === 'acknowledged') updatePayload.acknowledged_at = now;
        if (parsed.data.status === 'ready' || parsed.data.status === 'completed')
            updatePayload.completed_at = now;
        if (['acknowledged', 'preparing', 'ready'].includes(parsed.data.status)) {
            updatePayload.kitchen_status = parsed.data.status;
        }

        const { data: updatedOrder, error: updateError } = await monitoredQuery(
            'orders:update-status',
            async () => {
                const result = await supabase
                    .from('orders')
                    .update(updatePayload)
                    .eq('id', order.id)
                    .select(
                        'id, restaurant_id, status, kitchen_status, order_number, customer_phone, acknowledged_at, completed_at, created_at, updated_at'
                    )
                    .single();
                return result;
            },
            { orderId: order.id, newStatus: parsed.data.status }
        );

        if (updateError || !updatedOrder) {
            responseStatus = 500;
            return apiError(
                'Failed to update order status',
                500,
                'ORDER_UPDATE_FAILED',
                updateError?.message
            );
        }

        // Γ£à Respond immediately ΓÇö fire-and-forget audit + event + metrics writes
        responseStatus = 200;
        const response = apiSuccess(updatedOrder);

        const smsPromise = (async () => {
            if (!updatedOrder?.customer_phone) return;
            const { data: restaurantSettings } = await supabase
                .from('restaurants')
                .select('settings')
                .eq('id', order.restaurant_id)
                .maybeSingle();
            const notificationsSettings = (
                restaurantSettings?.settings as Record<string, unknown> | null
            )?.notifications as Record<string, unknown> | undefined;
            const smsEnabled = Boolean(notificationsSettings?.sms_enabled);
            if (!smsEnabled) return;

            await sendOrderStatusSms({
                toPhone: updatedOrder.customer_phone,
                orderNumber: updatedOrder.order_number ?? updatedOrder.id,
                status: parsed.data.status,
            });
        })();

        // These do NOT block the response
        const durationMs = Date.now() - startedAt;
        Promise.all([
            supabase.from('audit_logs').insert({
                restaurant_id: order.restaurant_id,
                user_id: user.id,
                action: 'order_status_updated',
                entity_type: 'order',
                entity_id: order.id,
                old_value: { status: order.status },
                new_value: { status: parsed.data.status },
                metadata: { source: 'merchant_dashboard' },
            }),
            supabase.from('order_events').insert({
                restaurant_id: order.restaurant_id,
                order_id: order.id,
                event_type: 'status_changed',
                from_status: order.status,
                to_status: parsed.data.status,
                actor_user_id: user.id,
                metadata: { source: 'merchant_dashboard' },
            }),
            ...(parsed.data.status === 'completed' || parsed.data.status === 'served'
                ? [
                      publishEvent(
                          createloleEvent('order.completed', {
                              restaurant_id: order.restaurant_id,
                              order_id: order.id,
                              previous_status: order.status,
                              status: parsed.data.status,
                              source: 'merchant_dashboard',
                          })
                      ),
                  ]
                : []),
            trackApiMetric(supabase, {
                restaurantId: restaurantIdForMetrics,
                endpoint: '/api/orders/:id/status',
                method: 'PATCH',
                statusCode: responseStatus,
                durationMs,
            }),
            smsPromise,
        ]).catch(err => {
            log.warn('background write failed', { error: err });
        });

        return response;
    } catch (error) {
        responseStatus = 500;
        return apiError(
            'Internal server error',
            500,
            'INTERNAL_ERROR',
            error instanceof Error ? error.message : 'Unknown error'
        );
    }
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser } from '@/lib/api/authz';
import { parseJsonBody } from '@/lib/api/validation';
import { writeAuditLog } from '@/lib/api/audit';
import { enforcePilotAccess } from '@/lib/api/pilotGate';
import { logger } from '@/lib/logger';

const log = logger.child('orders-bulk-status');

const BulkStatusSchema = z.object({
    order_ids: z.array(z.string().uuid()).min(1).max(50),
    status: z.enum(['acknowledged', 'preparing', 'ready', 'served', 'completed', 'cancelled']),
});

const ALLOWED_TRANSITIONS: Record<string, string[]> = {
    pending: ['acknowledged', 'cancelled'],
    acknowledged: ['preparing', 'cancelled'],
    preparing: ['ready', 'cancelled'],
    ready: ['served', 'cancelled'],
    served: ['completed'],
    completed: [],
    cancelled: [],
};

function canTransition(current: string | null, next: string) {
    if (!current) {
        return false;
    }
    return (ALLOWED_TRANSITIONS[current] || []).includes(next);
}

export async function POST(request: Request) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const parsed = await parseJsonBody(request, BulkStatusSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    const supabase = auth.supabase;
    const { data: orders, error: ordersError } = await supabase
        .from('orders')
        .select('id, status, restaurant_id')
        .in('id', parsed.data.order_ids);

    if (ordersError) {
        return apiError('Failed to load orders', 500, 'ORDERS_FETCH_FAILED', ordersError.message);
    }

    if (!orders || orders.length === 0) {
        return apiError('No matching orders found', 404, 'ORDERS_NOT_FOUND');
    }

    const restaurantIds = new Set(orders.map(o => o.restaurant_id));
    if (restaurantIds.size > 1) {
        return apiError(
            'Bulk update requires orders from a single restaurant',
            409,
            'CROSS_RESTAURANT_BULK_NOT_ALLOWED'
        );
    }

    const restaurantId = orders[0].restaurant_id;
    const pilotGateResponse = enforcePilotAccess(restaurantId, request.method);
    if (pilotGateResponse) {
        return pilotGateResponse;
    }

    const invalid = orders.filter(order => !canTransition(order.status, parsed.data.status));
    if (invalid.length > 0) {
        return apiError(
            'One or more orders have invalid status transitions',
            409,
            'INVALID_BULK_TRANSITION',
            invalid.map(item => ({ id: item.id, current_status: item.status }))
        );
    }

    const now = new Date().toISOString();
    const updatePayload: Record<string, string> = {
        status: parsed.data.status,
        updated_at: now,
    };
    if (parsed.data.status === 'acknowledged') {
        updatePayload.acknowledged_at = now;
    }
    if (parsed.data.status === 'ready' || parsed.data.status === 'completed') {
        updatePayload.completed_at = now;
    }

    const { data: updated, error: updateError } = await supabase
        .from('orders')
        .update(updatePayload)
        .in('id', parsed.data.order_ids)
        .select('id, status, restaurant_id');

    if (updateError) {
        return apiError('Failed to update orders', 500, 'BULK_UPDATE_FAILED', updateError.message);
    }

    const eventRows = orders.map(order => ({
        restaurant_id: order.restaurant_id,
        order_id: order.id,
        event_type: 'bulk_status_changed',
        from_status: order.status,
        to_status: parsed.data.status,
        actor_user_id: auth.user.id,
        metadata: { source: 'merchant_dashboard' },
    }));

    const { error: eventError } = await supabase.from('order_events').insert(eventRows);
    if (eventError) {
        log.warn('order_events insert failed', { message: eventError.message });
    }

    for (const order of orders) {
        await writeAuditLog(supabase, {
            restaurant_id: order.restaurant_id,
            user_id: auth.user.id,
            action: 'orders_bulk_status_updated',
            entity_type: 'order',
            entity_id: order.id,
            old_value: { status: order.status },
            new_value: { status: parsed.data.status },
            metadata: { source: 'merchant_dashboard' },
        });
    }

    return apiSuccess({
        updated_count: updated?.length ?? 0,
        status: parsed.data.status,
        order_ids: parsed.data.order_ids,
    });
}

/**
 * @openapi
 * /api/orders:
 *   get:
 *     summary: List orders
 *     description: Retrieve a paginated list of orders for the authenticated user's restaurant
 *     tags:
 *       - Orders
 *     security:
 *       - bearerAuth: []
 *     parameters:
 *       - in: query
 *         name: status
 *         schema:
 *           type: string
 *         description: Filter by order status
 *       - in: query
 *         name: search
 *         schema:
 *           type: string
 *         description: Search by table number, order number, or customer name
 *       - in: query
 *         name: limit
 *         schema:
 *           type: integer
 *           default: 50
 *           maximum: 200
 *         description: Maximum number of orders to return
 *     responses:
 *       200:
 *         description: List of orders
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 data:
 *                   type: object
 *                   properties:
 *                     orders:
 *                       type: array
 *                       items:
 *                         $ref: '#/components/schemas/Order'
 *                     total:
 *                       type: integer
 *       401:
 *         description: Unauthorized
 *       404:
 *         description: No restaurant found for user
 *   post:
 *     summary: Create a new order
 *     description: Create a new order from guest context with HMAC-validated QR code
 *     tags:
 *       - Orders
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required:
 *               - guest_context
 *               - items
 *               - total_price
 *             properties:
 *               guest_context:
 *                 type: object
 *                 required:
 *                   - slug
 *                   - table
 *                   - sig
 *                   - exp
 *                 properties:
 *                   slug:
 *                     type: string
 *                   table:
 *                     type: string
 *                   sig:
 *                     type: string
 *                   exp:
 *                     type: string
 *               items:
 *                 type: array
 *                 items:
 *                   $ref: '#/components/schemas/OrderItem'
 *               total_price:
 *                 type: number
 *               notes:
 *                 type: string
 *               idempotency_key:
 *                 type: string
 *                 format: uuid
 *     responses:
 *       201:
 *         description: Order created successfully
 *       400:
 *         description: Invalid request
 *       429:
 *         description: Rate limit exceeded
 */
import { NextRequest } from 'next/server';
import { z } from 'zod';
import { createClient } from '@/lib/supabase/server';
import { CreateOrderSchema } from '@/lib/validators/order';
import { apiError, apiSuccess } from '@/lib/api/response';
import { logger } from '@/lib/logger';
import { monitoredQuery } from '@/lib/services/queryMonitor';
import {
    checkRateLimit,
    createOrder,
    generateGuestFingerprint,
    generateIdempotencyKey,
} from '@/lib/services/orderService';
import { resolveGuestContext } from '@/lib/security/guestContext';
import { trackApiMetric } from '@/lib/api/metrics';
import { enforcePilotAccess } from '@/lib/api/pilotGate';
import { isIdempotencyKeyValid } from '@/lib/api/idempotency';
import { createloleEvent } from '@/lib/events/contracts';
import { publishEvent } from '@/lib/events/runtime';
import { createServiceRoleClient } from '@/lib/supabase/service-role';
import { prepareOrderDiscount } from '@/lib/discounts/service';
import { redisRateLimiters } from '@/lib/security';
import type { SupabaseClient } from '@supabase/supabase-js';
import type { Database } from '@/types/database';

const OrdersQuerySchema = z.object({
    status: z.string().optional(),
    search: z.string().optional(),
    limit: z.coerce.number().int().positive().max(200).optional().default(50),
    offset: z.coerce.number().int().nonnegative().optional().default(0),
});

const OnlineOrderGuestContextSchema = z.object({
    slug: z.string().min(1),
    is_online_order: z.literal(true),
    // For online orders, table/sig/exp are not real QR values
    table: z.string().optional(),
    sig: z.string().optional(),
    exp: z.union([z.string(), z.number()]).optional(),
});

const DineInGuestContextSchema = z.object({
    slug: z.string().min(1),
    table: z.string().min(1),
    sig: z.string().min(1),
    exp: z.union([z.string(), z.number()]),
    is_online_order: z.literal(false).optional(),
});

const GuestContextInputSchema = z.union([OnlineOrderGuestContextSchema, DineInGuestContextSchema]);

const CreateOrderRequestSchema = CreateOrderSchema.omit({
    idempotency_key: true,
    restaurant_id: true,
    table_number: true,
}).extend({
    guest_context: GuestContextInputSchema,
    order_type: z.enum(['dine_in', 'online', 'delivery', 'pickup']).optional().default('dine_in'),
    delivery_address: z.string().max(500).optional(),
    customer_name: z.string().max(100).optional(),
    customer_phone: z.string().max(30).optional(),
    discount_id: z.string().uuid().optional(),
    idempotency_key: z.string().uuid().optional(),
    campaign_attribution: z
        .object({
            campaign_delivery_id: z.string().uuid(),
            campaign_id: z.string().uuid().optional(),
        })
        .optional(),
});

async function resolveRestaurantIdForUser(userId: string) {
    const supabase = await createClient();
    const { data: staffEntry, error: staffError } = await supabase
        .from('restaurant_staff')
        .select('restaurant_id')
        .eq('user_id', userId)
        .eq('is_active', true)
        .order('created_at', { ascending: false })
        .limit(1)
        .maybeSingle();

    if (staffError) {
        return { error: staffError.message };
    }

    if (staffEntry?.restaurant_id) {
        return { restaurantId: staffEntry.restaurant_id };
    }

    const { data: agencyUser, error: agencyError } = await supabase
        .from('agency_users')
        .select('restaurant_ids')
        .eq('user_id', userId)
        .maybeSingle();

    if (agencyError) {
        return { error: agencyError.message };
    }

    return { restaurantId: agencyUser?.restaurant_ids?.[0] ?? null };
}

export async function GET(request: NextRequest) {
    const startedAt = Date.now();
    let responseStatus = 500;
    let restaurantIdForMetrics: string | null = null;
    let supabaseForMetrics: Awaited<ReturnType<typeof createClient>> | null = null;

    try {
        const supabase = await createClient();
        supabaseForMetrics = supabase;
        const {
            data: { user },
            error: userError,
        } = await supabase.auth.getUser();

        if (userError || !user) {
            responseStatus = 401;
            return apiError('Unauthorized', 401, 'UNAUTHORIZED');
        }

        const { restaurantId, error: restaurantError } = await resolveRestaurantIdForUser(user.id);
        if (restaurantError) {
            responseStatus = 500;
            return apiError(
                'Failed to resolve restaurant context',
                500,
                'RESTAURANT_RESOLVE_FAILED',
                restaurantError
            );
        }
        if (!restaurantId) {
            responseStatus = 404;
            return apiError('No restaurant found for user', 404, 'RESTAURANT_NOT_FOUND');
        }
        restaurantIdForMetrics = restaurantId;

        const pilotGateResponse = enforcePilotAccess(restaurantId, request.method);
        if (pilotGateResponse) {
            responseStatus = pilotGateResponse.status;
            return pilotGateResponse;
        }

        const parsed = OrdersQuerySchema.safeParse({
            status: request.nextUrl.searchParams.get('status') ?? undefined,
            search: request.nextUrl.searchParams.get('search') ?? undefined,
            limit: request.nextUrl.searchParams.get('limit') ?? undefined,
            offset: request.nextUrl.searchParams.get('offset') ?? undefined,
        });
        if (!parsed.success) {
            responseStatus = 400;
            return apiError('Invalid query params', 400, 'INVALID_QUERY', parsed.error.flatten());
        }

        const { data, error, count } = await monitoredQuery(
            'orders:list-active',
            async () => {
                let q = supabase
                    .from('orders')
                    .select('*', { count: 'exact' })
                    .eq('restaurant_id', restaurantId)
                    .order('created_at', { ascending: false })
                    .range(parsed.data.offset, parsed.data.offset + parsed.data.limit - 1);

                if (parsed.data.status && parsed.data.status !== 'all') {
                    q = q.eq('status', parsed.data.status);
                }

                if (parsed.data.search) {
                    const s = parsed.data.search.trim();
                    if (s.length > 0) {
                        q = q.or(
                            `table_number.ilike.%${s}%,order_number.ilike.%${s}%,customer_name.ilike.%${s}%`
                        );
                    }
                }

                return q;
            },
            { restaurantId }
        );

        if (error) {
            responseStatus = 500;
            return apiError('Failed to load orders', 500, 'ORDERS_FETCH_FAILED', error.message);
        }

        responseStatus = 200;
        return apiSuccess({
            orders: data?.map(o => ({ ...o, total_price: Number(o.total_price ?? 0) / 100 })) ?? [],
            total: count ?? 0,
        });
    } catch (error) {
        responseStatus = 500;
        return apiError(
            'Internal server error',
            500,
            'INTERNAL_ERROR',
            error instanceof Error ? error.message : 'Unknown error'
        );
    } finally {
        if (supabaseForMetrics) {
            const durationMs = Date.now() - startedAt;
            await trackApiMetric(supabaseForMetrics, {
                restaurantId: restaurantIdForMetrics,
                endpoint: '/api/orders',
                method: 'GET',
                statusCode: responseStatus,
                durationMs,
            });
        }
    }
}

export async function POST(request: NextRequest) {
    // Apply rate limiting for order creation
    const rateLimitResponse = await redisRateLimiters.orderCreate(request);
    if (rateLimitResponse) {
        return rateLimitResponse;
    }

    try {
        const body = await request.json();
        const parsed = CreateOrderRequestSchema.safeParse(body);

        if (!parsed.success) {
            return apiError(
                'Invalid request payload',
                400,
                'VALIDATION_ERROR',
                parsed.error.flatten()
            );
        }

        const supabase = await createClient();
        const isOnlineOrder =
            parsed.data.order_type === 'online' ||
            parsed.data.order_type === 'delivery' ||
            parsed.data.order_type === 'pickup' ||
            (parsed.data.guest_context as { is_online_order?: boolean }).is_online_order === true;

        let restaurantId: string;
        let tableNumber: string;

        if (isOnlineOrder) {
            // ΓöÇΓöÇ Online / Delivery / Pickup: resolve restaurant by slug only ΓöÇΓöÇ
            const slug = parsed.data.guest_context.slug;
            const { data: restaurant, error: restaurantError } = await supabase
                .from('restaurants')
                .select('id, is_active')
                .eq('slug', slug)
                .maybeSingle();

            if (restaurantError) {
                return apiError('Failed to resolve restaurant', 500, 'RESTAURANT_RESOLVE_FAILED');
            }
            if (!restaurant || restaurant.is_active === false) {
                return apiError('Restaurant not found or inactive', 404, 'RESTAURANT_NOT_FOUND');
            }
            restaurantId = restaurant.id;
            // Represent the order type as the table label for legacy display
            tableNumber =
                parsed.data.order_type === 'delivery'
                    ? 'Delivery'
                    : parsed.data.order_type === 'pickup'
                      ? 'Pickup'
                      : 'Online Order';
        } else {
            // ΓöÇΓöÇ Dine-in: full QR validation via resolveGuestContext ΓöÇΓöÇ
            const guestContext = await resolveGuestContext(supabase, parsed.data.guest_context);
            if (!guestContext.valid) {
                return apiError(
                    guestContext.reason ?? 'Invalid guest context',
                    guestContext.status ?? 401,
                    'INVALID_GUEST_CONTEXT'
                );
            }
            restaurantId = guestContext.data.restaurantId;
            tableNumber = guestContext.data.tableNumber;
        }

        const ip = request.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown';
        const fingerprint = generateGuestFingerprint(ip, request.headers.get('user-agent'));

        const rateLimit = await checkRateLimit(supabase, fingerprint);
        if (!rateLimit.allowed) {
            return apiError(
                'Rate limit exceeded. Please wait before placing another order.',
                429,
                'RATE_LIMITED',
                { remainingOrders: rateLimit.remainingOrders ?? 0 }
            );
        }

        const explicitIdempotencyKey = request.headers.get('x-idempotency-key');
        if (explicitIdempotencyKey && !isIdempotencyKeyValid(explicitIdempotencyKey)) {
            return apiError('Invalid idempotency key', 400, 'INVALID_IDEMPOTENCY_KEY');
        }

        const idempotencyKey =
            explicitIdempotencyKey?.trim() ||
            parsed.data.idempotency_key ||
            generateIdempotencyKey();
        let discountRuntime: {
            discount: { id: string } | null;
            calculation: {
                subtotal: number;
                discountAmount: number;
                total: number;
                applied: boolean;
            };
        };
        try {
            discountRuntime = parsed.data.discount_id
                ? await prepareOrderDiscount({
                      supabase: createServiceRoleClient(),
                      restaurantId,
                      discountId: parsed.data.discount_id,
                      items: parsed.data.items.map(item => ({
                          id: item.id,
                          price: item.price,
                          quantity: item.quantity,
                      })),
                      excludeManagerApproval: true,
                  })
                : {
                      discount: null,
                      calculation: {
                          subtotal: parsed.data.total_price,
                          discountAmount: 0,
                          total: parsed.data.total_price,
                          applied: false,
                      },
                  };
        } catch (error) {
            return apiError(
                error instanceof Error ? error.message : 'Failed to validate discount',
                400,
                'DISCOUNT_VALIDATION_FAILED'
            );
        }

        const result = await createOrder(supabase, {
            restaurant_id: restaurantId,
            table_number: tableNumber,
            items: parsed.data.items,
            total_price: discountRuntime.calculation.total,
            notes: parsed.data.notes,
            idempotency_key: idempotencyKey,
            guest_fingerprint: fingerprint,
            order_type: parsed.data.order_type,
            delivery_address: parsed.data.delivery_address,
            customer_name: parsed.data.customer_name,
            customer_phone: parsed.data.customer_phone,
            discount_id: discountRuntime.discount?.id,
            discount_amount: discountRuntime.calculation.discountAmount,
        });

        if (!result.success) {
            return apiError(result.error ?? 'Failed to create order', 400, 'ORDER_CREATE_FAILED');
        }

        let campaignAttributionApplied = false;
        if (parsed.data.campaign_attribution) {
            const attribution = parsed.data.campaign_attribution;
            const { data: delivery, error: deliveryError } = await (
                supabase as SupabaseClient<Database>
            )
                .from('campaign_deliveries')
                .select('id, campaign_id, conversion_order_id')
                .eq('id', attribution.campaign_delivery_id)
                .maybeSingle();

            if (deliveryError) {
                logger.warn('[POST /api/orders] campaign delivery lookup failed', {
                    error: deliveryError.message,
                });
            } else if (delivery) {
                const campaignMatches =
                    !attribution.campaign_id || attribution.campaign_id === delivery.campaign_id;
                if (campaignMatches) {
                    const { data: campaign, error: campaignError } = await (
                        supabase as SupabaseClient<Database>
                    )
                        .from('campaigns')
                        .select('id')
                        .eq('id', delivery.campaign_id)
                        .eq('restaurant_id', restaurantId)
                        .maybeSingle();

                    if (campaignError) {
                        logger.warn('[POST /api/orders] campaign validation failed', {
                            error: campaignError.message,
                        });
                    } else if (campaign && !delivery.conversion_order_id) {
                        const { error: updateDeliveryError } = await (
                            supabase as SupabaseClient<Database>
                        )
                            .from('campaign_deliveries')
                            .update({
                                status: 'converted',
                                conversion_order_id: result.order.id,
                                clicked_at: new Date().toISOString(),
                            })
                            .eq('id', delivery.id);

                        if (updateDeliveryError) {
                            logger.warn('[POST /api/orders] campaign conversion update failed', {
                                error: updateDeliveryError.message,
                            });
                        } else {
                            campaignAttributionApplied = true;
                        }
                    }
                }
            }
        }

        const { error: auditError } = await supabase.from('audit_logs').insert({
            restaurant_id: restaurantId,
            action: 'order_created_guest',
            entity_type: 'order',
            entity_id: result.order.id,
            metadata: {
                table_number: tableNumber,
                item_count: parsed.data.items.length,
                source: isOnlineOrder ? 'online_ordering' : 'guest_web',
                order_type: parsed.data.order_type,
                slug: parsed.data.guest_context.slug,
                campaign_attribution: parsed.data.campaign_attribution ?? null,
                campaign_attribution_applied: campaignAttributionApplied,
            },
            new_value: {
                status: result.order.status,
                total_price: discountRuntime.calculation.total,
                discount_amount: discountRuntime.calculation.discountAmount,
            },
        });
        if (auditError) {
            logger.warn('[POST /api/orders] audit insert failed', { error: auditError.message });
        }

        await publishEvent(
            createloleEvent('order.created', {
                restaurant_id: restaurantId,
                order_id: result.order.id,
                idempotency_key: idempotencyKey,
                source: isOnlineOrder ? 'online_ordering' : 'guest_web',
                order_type: parsed.data.order_type,
            })
        );

        return apiSuccess(
            {
                id: result.order.id,
                order_number: result.order.order_number,
                status: result.order.status,
                idempotency_key: idempotencyKey,
                campaign_attribution_applied: campaignAttributionApplied,
            },
            201
        );
    } catch (error) {
        logger.error('[POST /api/orders] failed', error);
        return apiError('Internal server error', 500, 'INTERNAL_ERROR');
    }
}

import { NextRequest } from 'next/server';
import { createServiceRoleClient } from '@/lib/supabase/service-role';
import { apiSuccess, apiError } from '@/lib/api/response';
import {
    createPaymentSession,
    initiateHostedPaymentSession,
} from '@/lib/payments/payment-sessions';
import { resolveGuestContext } from '@/lib/security/guestContext';
import {
    validateOrderItems,
    checkDuplicateOrder,
    checkRateLimit,
    generateGuestFingerprint,
    generateIdempotencyKey,
} from '@/lib/services/orderService';
import { prepareOrderDiscount } from '@/lib/discounts/service';
import type { SupabaseClient } from '@supabase/supabase-js';
import type { Database } from '@/types/database';

const POST_CHOICES = ['pay_now', 'pay_later'] as const;

interface PaymentSessionRequestBody {
    guest_context?: { slug?: string; table?: string; sig?: string; exp?: string };
    items?: unknown[];
    total_price?: number;
    order_type?: string;
    payment_choice?: string;
}

async function parseJsonBody(request: NextRequest) {
    try {
        const body = (await request.json()) as PaymentSessionRequestBody;
        return { success: true as const, data: body };
    } catch {
        return { success: false as const, error: 'Invalid JSON' };
    }
}

export async function POST(request: NextRequest) {
    const parsed = await parseJsonBody(request);
    if (!parsed.success) {
        return apiError(parsed.error, 400, 'INVALID_JSON');
    }

    const data = parsed.data;
    const guestContext = data.guest_context;
    const items = data.items;
    const totalPrice = data.total_price;
    const orderType = data.order_type;
    const paymentChoice = data.payment_choice;

    if (!guestContext?.slug || !guestContext?.table || !guestContext?.sig || !guestContext?.exp) {
        return apiError('Invalid guest context', 400, 'INVALID_GUEST_CONTEXT');
    }

    if (!items || !Array.isArray(items) || items.length === 0) {
        return apiError('No items provided', 400, 'NO_ITEMS');
    }

    if (!POST_CHOICES.includes(paymentChoice as 'pay_now' | 'pay_later')) {
        return apiError('Invalid payment choice', 400, 'INVALID_PAYMENT_CHOICE');
    }

    const db = createServiceRoleClient() as SupabaseClient<Database>;
    const guestCtxResult = await resolveGuestContext(db, guestContext);

    if (!guestCtxResult.valid) {
        const reason = guestCtxResult.reason ?? 'Invalid guest context signature';
        const status = guestCtxResult.status ?? 401;
        return apiError(reason, status, 'GUEST_CONTEXT_INVALID');
    }

    const { restaurantId, tableId, tableNumber } = guestCtxResult.data;

    const orderValidation = await validateOrderItems(
        db,
        items as Array<{ id: string; name: string; quantity: number; price: number }>,
        totalPrice ?? 0,
        0
    );
    if (!orderValidation.isValid) {
        return apiError(orderValidation.error ?? 'Invalid order items', 400, 'INVALID_ORDER');
    }

    const enrichedItems = orderValidation.enrichedItems ?? [];
    const idempotencyKey = generateIdempotencyKey();
    const ip = request.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown';
    const fingerprint = generateGuestFingerprint(ip, request.headers.get('user-agent'));

    const duplicateCheck = await checkDuplicateOrder(db, idempotencyKey);
    if (duplicateCheck) {
        return apiError('Duplicate order', 409, 'DUPLICATE_ORDER');
    }

    const rateLimit = await checkRateLimit(db, fingerprint);
    if (!rateLimit.allowed) {
        return apiError('Rate limit exceeded', 429, 'RATE_LIMIT_EXCEEDED');
    }

    const discountResult = await prepareOrderDiscount({
        supabase: db,
        restaurantId,
        items: enrichedItems.map((item: { id: string; price: number; quantity: number }) => ({
            id: item.id,
            price: item.price,
            quantity: item.quantity,
        })),
    });
    const finalTotal =
        (totalPrice ?? 0) - ((discountResult.discount as { amount?: number })?.amount ?? 0);

    const surface = 'guest_qr';
    const channel =
        orderType === 'dine_in' ? 'dine_in' : orderType === 'pickup' ? 'pickup' : 'online';
    const intentType = paymentChoice === 'pay_now' ? 'pay_now' : 'pay_later';

    const session = await createPaymentSession(
        db as unknown as Parameters<typeof createPaymentSession>[0],
        {
            restaurant_id: restaurantId,
            surface,
            channel,
            intent_type: intentType,
            amount: finalTotal,
            currency: 'ETB',
            metadata: {
                order_type: orderType,
                table_id: tableId,
                table_number: tableNumber,
                guest_fingerprint: fingerprint,
                discount_applied: (discountResult.discount as { id?: string })?.id ?? null,
            },
        }
    );

    const baseUrl = request.nextUrl.origin;
    const callbackUrl = `${baseUrl}/api/v1/system/webhooks/chapa`;
    const returnUrl = `${baseUrl}/${guestContext.slug}?table=${tableNumber}&payment=complete`;

    let mode: 'deferred' | 'hosted_checkout' = 'deferred';
    let provider: string | undefined;
    let checkoutUrl: string | undefined;
    let paymentId: string | undefined;
    let transactionReference: string | undefined;
    let attempts: Array<{ provider: string; ok: boolean }> = [];
    let fallbackApplied = false;

    if (paymentChoice === 'pay_now') {
        mode = 'hosted_checkout';
        try {
            const checkout = await initiateHostedPaymentSession({
                db: db as unknown as Parameters<typeof initiateHostedPaymentSession>[0]['db'],
                paymentSessionId: session.id,
                restaurantId,
                orderId: session.order_id ?? session.id,
                amount: finalTotal,
                currency: 'ETB',
                callbackUrl,
                returnUrl,
            });
            provider = checkout.provider;
            checkoutUrl = checkout.checkoutUrl;
            paymentId = checkout.paymentId;
            transactionReference = checkout.transactionReference;
            attempts = checkout.attempts;
            fallbackApplied = checkout.fallbackApplied;
        } catch {
            provider = 'chapa';
            attempts = [{ provider: 'chapa', ok: false }];
        }
    }

    return apiSuccess(
        {
            session_id: session.id,
            mode,
            payment_choice: paymentChoice,
            provider,
            checkout_url: checkoutUrl,
            payment_id: paymentId,
            transaction_reference: transactionReference,
            attempts,
            fallback_applied: fallbackApplied,
        },
        201
    );
}

import { NextRequest } from 'next/server';
import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser } from '@/lib/api/authz';
import { parseJsonBody } from '@/lib/api/validation';
import { writeAuditLog } from '@/lib/api/audit';
import { enforcePilotAccess } from '@/lib/api/pilotGate';
import { logger } from '@/lib/logger';

const log = logger.child('service-requests');

const UpdateServiceRequestSchema = z.object({
    status: z.enum(['pending', 'in_progress', 'completed']),
});

const ALLOWED_TRANSITIONS: Record<string, string[]> = {
    pending: ['in_progress', 'completed'],
    in_progress: ['completed'],
    completed: [],
};

function canTransition(currentStatus: string | null, nextStatus: string) {
    if (!currentStatus) {
        return false;
    }
    return (ALLOWED_TRANSITIONS[currentStatus] ?? []).includes(nextStatus);
}

export async function PATCH(
    request: NextRequest,
    context: { params: Promise<{ requestId: string }> }
) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const parsedBody = await parseJsonBody(request, UpdateServiceRequestSchema);
    if (!parsedBody.success) {
        return parsedBody.response;
    }

    const { requestId } = await context.params;
    const { data: requestRow, error: requestFetchError } = await auth.supabase
        .from('service_requests')
        .select('id, restaurant_id, status')
        .eq('id', requestId)
        .maybeSingle();

    if (requestFetchError) {
        return apiError(
            'Failed to load service request',
            500,
            'SERVICE_REQUEST_FETCH_FAILED',
            requestFetchError.message
        );
    }

    if (!requestRow) {
        return apiError('Service request not found', 404, 'SERVICE_REQUEST_NOT_FOUND');
    }
    if (!requestRow.restaurant_id) {
        return apiError(
            'Service request is missing restaurant context',
            400,
            'INVALID_SERVICE_REQUEST_CONTEXT'
        );
    }

    const pilotGateResponse = enforcePilotAccess(requestRow.restaurant_id, request.method);
    if (pilotGateResponse) {
        return pilotGateResponse;
    }

    const { data: staff, error: staffError } = await auth.supabase
        .from('restaurant_staff')
        .select('id')
        .eq('restaurant_id', requestRow.restaurant_id)
        .eq('user_id', auth.user.id)
        .eq('is_active', true)
        .maybeSingle();

    if (staffError) {
        return apiError(
            'Failed to verify staff access',
            500,
            'STAFF_ACCESS_CHECK_FAILED',
            staffError.message
        );
    }
    if (!staff) {
        return apiError('Forbidden', 403, 'FORBIDDEN');
    }

    if (!canTransition(requestRow.status, parsedBody.data.status)) {
        return apiError(
            `Invalid status transition from "${requestRow.status}" to "${parsedBody.data.status}"`,
            409,
            'INVALID_TRANSITION'
        );
    }

    const now = new Date().toISOString();
    const updatePayload: { status: string; completed_at?: string } = {
        status: parsedBody.data.status,
    };
    if (parsedBody.data.status === 'completed') {
        updatePayload.completed_at = now;
    }

    const { data: updatedRequest, error: updateError } = await auth.supabase
        .from('service_requests')
        .update(updatePayload)
        .eq('id', requestRow.id)
        // HIGH-013: Explicit column selection
        .select(
            'id, restaurant_id, table_number, request_type, status, notes, completed_at, idempotency_key, created_at'
        )
        .single();

    if (updateError || !updatedRequest) {
        return apiError(
            'Failed to update service request',
            500,
            'SERVICE_REQUEST_UPDATE_FAILED',
            updateError?.message
        );
    }

    const { error: auditError } = await writeAuditLog(auth.supabase, {
        restaurant_id: requestRow.restaurant_id,
        user_id: auth.user.id,
        action: 'service_request_status_updated',
        entity_type: 'service_request',
        entity_id: requestRow.id,
        old_value: { status: requestRow.status },
        new_value: { status: parsedBody.data.status },
        metadata: { source: 'merchant_dashboard_orders_queue' },
    });
    if (auditError) {
        log.warn('audit insert failed', { message: auditError.message });
    }

    return apiSuccess(updatedRequest);
}

import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';
import { createClient } from '@/lib/supabase/server';
import { createServiceRoleClient } from '@/lib/supabase/service-role';
import { insertServiceRequest } from '@/lib/supabase/queries';
import { resolveGuestContext } from '@/lib/security/guestContext';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthorizedRestaurantContext, getAuthenticatedUser } from '@/lib/api/authz';
import { parseQuery } from '@/lib/api/validation';
import { logger } from '@/lib/logger';

const log = logger.child('service-requests');

const CreateServiceRequestSchema = z.object({
    guest_context: z.object({
        slug: z.string().min(1),
        table: z.string().min(1),
        sig: z.string().min(1),
        exp: z.union([z.string(), z.number()]),
    }),
    request_type: z.enum(['waiter', 'bill', 'cutlery', 'other']),
    notes: z.string().max(500, 'Notes too long').optional(),
});

const ListServiceRequestsQuerySchema = z.object({
    status: z.string().optional(),
    search: z.string().optional(),
    limit: z.coerce.number().int().positive().max(200).optional().default(100),
    offset: z.coerce.number().int().nonnegative().optional().default(0),
});

export async function GET(request: NextRequest) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id);
    if (!context.ok) {
        return context.response;
    }

    const parsed = parseQuery(
        {
            status: request.nextUrl.searchParams.get('status') ?? undefined,
            search: request.nextUrl.searchParams.get('search') ?? undefined,
            limit: request.nextUrl.searchParams.get('limit') ?? undefined,
            offset: request.nextUrl.searchParams.get('offset') ?? undefined,
        },
        ListServiceRequestsQuerySchema
    );
    if (!parsed.success) {
        return parsed.response;
    }

    let query = context.supabase
        .from('service_requests')
        .select('*', { count: 'exact' })
        .eq('restaurant_id', context.restaurantId)
        .order('created_at', { ascending: false })
        .range(parsed.data.offset, parsed.data.offset + parsed.data.limit - 1);

    if (parsed.data.status && parsed.data.status !== 'all') {
        query = query.eq('status', parsed.data.status);
    }

    if (parsed.data.search) {
        const search = parsed.data.search.trim();
        if (search.length > 0) {
            query = query.or(
                `table_number.ilike.%${search}%,request_type.ilike.%${search}%,notes.ilike.%${search}%`
            );
        }
    }

    const { data, error, count } = await query;
    if (error) {
        return apiError(
            'Failed to load service requests',
            500,
            'SERVICE_REQUESTS_FETCH_FAILED',
            error.message
        );
    }

    return apiSuccess({
        requests: data ?? [],
        total: count ?? 0,
    });
}

export async function POST(request: NextRequest) {
    try {
        const body = await request.json();
        const parsed = CreateServiceRequestSchema.safeParse(body);

        if (!parsed.success) {
            return NextResponse.json(
                { error: 'Invalid request payload', details: parsed.error.flatten() },
                { status: 400 }
            );
        }

        const supabase = await createClient();
        const guestContext = await resolveGuestContext(supabase, parsed.data.guest_context);
        if (!guestContext.valid) {
            return NextResponse.json(
                { error: guestContext.reason },
                { status: guestContext.status }
            );
        }

        const adminSupabase = createServiceRoleClient();
        const { data, error } = await insertServiceRequest(adminSupabase, {
            restaurant_id: guestContext.data.restaurantId,
            table_number: guestContext.data.tableNumber,
            request_type: parsed.data.request_type,
            notes: parsed.data.notes,
        });

        if (error || !data) {
            return NextResponse.json(
                { error: error?.message ?? 'Failed to create service request' },
                { status: 400 }
            );
        }

        if (parsed.data.request_type === 'bill') {
            const { error: tableStateError } = await adminSupabase
                .from('tables')
                .update({
                    status: 'bill_requested',
                    updated_at: new Date().toISOString(),
                })
                .eq('restaurant_id', guestContext.data.restaurantId)
                .eq('table_number', guestContext.data.tableNumber)
                .neq('status', 'available');

            if (tableStateError) {
                log.warn('failed to promote table to bill_requested', { message: tableStateError.message });
            }
        }

        const { error: auditError } = await adminSupabase.from('audit_logs').insert({
            restaurant_id: guestContext.data.restaurantId,
            action: 'service_request_created_guest',
            entity_type: 'service_request',
            entity_id: data.id,
            metadata: {
                table_number: guestContext.data.tableNumber,
                request_type: parsed.data.request_type,
                source: 'guest_web',
                slug: guestContext.data.slug,
            },
            new_value: {
                status: data.status,
            },
        });
        if (auditError) {
            log.warn('audit insert failed', { message: auditError.message });
        }

        return NextResponse.json({ data }, { status: 201 });
    } catch (error) {
        log.error('failed', error);
        return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
    }
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { parseJsonBody } from '@/lib/api/validation';

const CloseSessionSchema = z.object({
    notes: z.string().max(500).optional().nullable(),
});

export async function POST(request: Request, context: { params: Promise<{ sessionId: string }> }) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const restaurantContext = await getAuthorizedRestaurantContext(auth.user.id);
    if (!restaurantContext.ok) {
        return restaurantContext.response;
    }

    const parsed = await parseJsonBody(request, CloseSessionSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    const { sessionId } = await context.params;
    const { data: session, error: sessionError } = await restaurantContext.supabase
        .from('table_sessions')
        // HIGH-013: Explicit column selection
        .select(
            'id, restaurant_id, table_id, status, guest_count, assigned_staff_id, notes, metadata, opened_at, closed_at, created_at, updated_at'
        )
        .eq('id', sessionId)
        .eq('restaurant_id', restaurantContext.restaurantId)
        .eq('status', 'open')
        .maybeSingle();

    if (sessionError) {
        return apiError(
            'Failed to fetch table session',
            500,
            'TABLE_SESSION_FETCH_FAILED',
            sessionError.message
        );
    }
    if (!session) {
        return apiError('Open table session not found', 404, 'TABLE_SESSION_NOT_FOUND');
    }

    const now = new Date().toISOString();
    const { data: closedSession, error: closeError } = await restaurantContext.supabase
        .from('table_sessions')
        .update({
            status: 'closed',
            closed_at: now,
            notes: parsed.data.notes ?? session.notes,
        })
        .eq('id', session.id)
        // HIGH-013: Explicit column selection
        .select(
            'id, restaurant_id, table_id, status, guest_count, assigned_staff_id, notes, metadata, opened_at, closed_at, created_at, updated_at'
        )
        .single();

    if (closeError) {
        return apiError(
            'Failed to close table session',
            500,
            'TABLE_SESSION_CLOSE_FAILED',
            closeError.message
        );
    }

    await restaurantContext.supabase
        .from('tables')
        .update({ status: 'available' })
        .eq('id', session.table_id)
        .eq('restaurant_id', restaurantContext.restaurantId);

    return apiSuccess(closedSession);
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { parseJsonBody } from '@/lib/api/validation';

const TransferSessionSchema = z.object({
    to_table_id: z.string().uuid(),
    notes: z.string().max(500).optional().nullable(),
});

export async function POST(request: Request, context: { params: Promise<{ sessionId: string }> }) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const restaurantContext = await getAuthorizedRestaurantContext(auth.user.id);
    if (!restaurantContext.ok) {
        return restaurantContext.response;
    }

    const parsed = await parseJsonBody(request, TransferSessionSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    const { sessionId } = await context.params;
    const { data: session, error: sessionError } = await restaurantContext.supabase
        .from('table_sessions')
        // HIGH-013: Explicit column selection
        .select(
            'id, restaurant_id, table_id, status, guest_count, assigned_staff_id, notes, metadata, opened_at, closed_at, created_at, updated_at'
        )
        .eq('id', sessionId)
        .eq('restaurant_id', restaurantContext.restaurantId)
        .eq('status', 'open')
        .maybeSingle();

    if (sessionError) {
        return apiError(
            'Failed to fetch table session',
            500,
            'TABLE_SESSION_FETCH_FAILED',
            sessionError.message
        );
    }
    if (!session) {
        return apiError('Open table session not found', 404, 'TABLE_SESSION_NOT_FOUND');
    }

    if (session.table_id === parsed.data.to_table_id) {
        return apiError('Cannot transfer to the same table', 409, 'INVALID_TRANSFER_TARGET');
    }

    const { data: destinationOpen } = await restaurantContext.supabase
        .from('table_sessions')
        .select('id')
        .eq('table_id', parsed.data.to_table_id)
        .eq('status', 'open')
        .maybeSingle();

    if (destinationOpen) {
        return apiError(
            'Destination table already has an open session',
            409,
            'DESTINATION_TABLE_OCCUPIED'
        );
    }

    const now = new Date().toISOString();
    const { error: closeCurrentError } = await restaurantContext.supabase
        .from('table_sessions')
        .update({
            status: 'transferred',
            closed_at: now,
            notes: parsed.data.notes ?? session.notes,
        })
        .eq('id', session.id);

    if (closeCurrentError) {
        return apiError(
            'Failed to close current table session',
            500,
            'TABLE_SESSION_TRANSFER_CLOSE_FAILED',
            closeCurrentError.message
        );
    }

    const { data: newSession, error: newSessionError } = await restaurantContext.supabase
        .from('table_sessions')
        .insert({
            restaurant_id: restaurantContext.restaurantId,
            table_id: parsed.data.to_table_id,
            assigned_staff_id: session.assigned_staff_id,
            guest_count: session.guest_count,
            status: 'open',
            notes: parsed.data.notes ?? session.notes,
            metadata: {
                ...(session.metadata as object),
                transferred_from_session_id: session.id,
                transferred_at: now,
            },
        })
        // HIGH-013: Explicit column selection
        .select(
            'id, restaurant_id, table_id, status, guest_count, assigned_staff_id, notes, metadata, opened_at, closed_at, created_at, updated_at'
        )
        .single();

    if (newSessionError) {
        return apiError(
            'Failed to create transferred table session',
            500,
            'TABLE_SESSION_TRANSFER_CREATE_FAILED',
            newSessionError.message
        );
    }

    await Promise.all([
        restaurantContext.supabase
            .from('tables')
            .update({ status: 'available' })
            .eq('id', session.table_id)
            .eq('restaurant_id', restaurantContext.restaurantId),
        restaurantContext.supabase
            .from('tables')
            .update({ status: 'occupied' })
            .eq('id', parsed.data.to_table_id)
            .eq('restaurant_id', restaurantContext.restaurantId),
    ]);

    return apiSuccess({
        previous_session_id: session.id,
        new_session: newSession,
    });
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { parseJsonBody } from '@/lib/api/validation';

const OpenTableSessionSchema = z.object({
    table_id: z.string().uuid(),
    guest_count: z.number().int().positive().max(50).optional().default(1),
    assigned_staff_id: z.string().uuid().optional().nullable(),
    notes: z.string().max(500).optional().nullable(),
});

export async function POST(request: Request) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id);
    if (!context.ok) {
        return context.response;
    }

    const parsed = await parseJsonBody(request, OpenTableSessionSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    const { data: table, error: tableError } = await context.supabase
        .from('tables')
        .select('id, restaurant_id, status')
        .eq('id', parsed.data.table_id)
        .eq('restaurant_id', context.restaurantId)
        .maybeSingle();

    if (tableError) {
        return apiError('Failed to fetch table', 500, 'TABLE_FETCH_FAILED', tableError.message);
    }
    if (!table) {
        return apiError('Table not found', 404, 'TABLE_NOT_FOUND');
    }

    const { data: existingOpen, error: existingError } = await context.supabase
        .from('table_sessions')
        .select('id')
        .eq('table_id', parsed.data.table_id)
        .eq('status', 'open')
        .maybeSingle();

    if (existingError) {
        return apiError(
            'Failed to verify table session state',
            500,
            'TABLE_SESSION_STATE_FAILED',
            existingError.message
        );
    }
    if (existingOpen) {
        return apiError('Table already has an open session', 409, 'TABLE_SESSION_ALREADY_OPEN');
    }

    const { data: session, error: sessionError } = await context.supabase
        .from('table_sessions')
        .insert({
            restaurant_id: context.restaurantId,
            table_id: parsed.data.table_id,
            guest_count: parsed.data.guest_count,
            assigned_staff_id: parsed.data.assigned_staff_id ?? null,
            notes: parsed.data.notes ?? null,
            status: 'open',
        })
        // HIGH-013: Explicit column selection
        .select(
            'id, restaurant_id, table_id, status, guest_count, assigned_staff_id, notes, metadata, opened_at, closed_at, created_at, updated_at'
        )
        .single();

    if (sessionError) {
        return apiError(
            'Failed to open table session',
            500,
            'TABLE_SESSION_OPEN_FAILED',
            sessionError.message
        );
    }

    await context.supabase
        .from('tables')
        .update({ status: 'occupied' })
        .eq('id', parsed.data.table_id)
        .eq('restaurant_id', context.restaurantId);

    return apiSuccess(session, 201);
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { parseJsonBody } from '@/lib/api/validation';
import { writeAuditLog } from '@/lib/api/audit';
import { calculateTipDistribution } from '@/lib/pricing/tip-pool';

const AllocateTipSchema = z.object({
    tip_pool_id: z.string().uuid(),
    period_date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'Date must be in YYYY-MM-DD format'),
    shift_id: z.string().uuid().optional(),
    total_tips_collected: z.number().int().min(0),
    total_bill_amount: z.number().int().min(0).optional(),
});

export async function POST(request: Request) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p1' });
    if (!context.ok) {
        return context.response;
    }

    const parsed = await parseJsonBody(request, AllocateTipSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    const { tip_pool_id, period_date, shift_id, total_tips_collected, total_bill_amount } =
        parsed.data;
    const db = context.supabase;

    // Get the tip pool with shares
    const { data: tipPool, error: poolError } = await db
        .from('tip_pools')
        // HIGH-013: Explicit column selection
        .select(
            'id, restaurant_id, name, name_am, description, description_am, is_active, pool_type, pool_value, calculated_from, valid_from, valid_until, allocation_mode, created_by, created_at, updated_at'
        )
        .eq('id', tip_pool_id)
        .eq('restaurant_id', context.restaurantId)
        .single();

    if (poolError || !tipPool) {
        return apiError('Tip pool not found', 404, 'TIP_POOL_NOT_FOUND');
    }

    if (!tipPool.is_active) {
        return apiError('Tip pool is not active', 400, 'TIP_POOL_INACTIVE');
    }

    // Get shares
    const { data: shares, error: sharesError } = await db
        .from('tip_pool_shares')
        // HIGH-013: Explicit column selection
        .select('id, tip_pool_id, restaurant_id, role, percentage, created_at, updated_at')
        .eq('tip_pool_id', tip_pool_id);

    if (sharesError || !shares || shares.length === 0) {
        return apiError('No shares configured for tip pool', 400, 'TIP_POOL_NO_SHARES');
    }

    // Calculate pool amount
    let poolableTips = total_tips_collected;
    if (tipPool.calculated_from === 'total' && total_bill_amount) {
        if (tipPool.pool_type === 'percentage') {
            poolableTips = Math.round(total_bill_amount * (tipPool.pool_value / 10000));
        } else {
            poolableTips = Math.min(tipPool.pool_value, total_bill_amount);
        }
    }

    // Calculate distribution
    const distribution = calculateTipDistribution(
        poolableTips,
        shares.map((s: { role: string; percentage: number }) => ({
            role: s.role,
            percentage: s.percentage,
        }))
    );
    const periodStart = new Date(period_date);
    periodStart.setHours(0, 0, 0, 0);
    const periodEnd = new Date(period_date);
    periodEnd.setHours(23, 59, 59, 999);

    // Create allocation record
    const { data: allocation, error: allocationError } = await db
        .from('tip_allocations')
        .insert({
            restaurant_id: context.restaurantId,
            tip_pool_id,
            shift_id: shift_id ?? null,
            period_date,
            period_start: periodStart.toISOString(),
            period_end: periodEnd.toISOString(),
            total_tips_collected,
            total_tips_pooled: poolableTips,
            total_tips_distributed: distribution.reduce((sum, d) => sum + d.amount, 0),
            distribution: distribution as Array<{ role: string; amount: number }>,
            status: 'calculated',
            created_by: auth.user.id,
        })
        // HIGH-013: Explicit column selection
        .select(
            'id, restaurant_id, tip_pool_id, shift_id, period_date, period_start, period_end, total_tips_collected, total_tips_pooled, total_tips_distributed, distribution, status, created_by, created_at, updated_at'
        )
        .single();

    if (allocationError) {
        return apiError(
            'Failed to create tip allocation',
            500,
            'TIP_ALLOCATION_FAILED',
            allocationError.message
        );
    }

    await writeAuditLog(context.supabase, {
        restaurant_id: context.restaurantId,
        user_id: auth.user.id,
        action: 'tip_allocation_created',
        entity_type: 'tip_allocation',
        entity_id: allocation.id,
        metadata: {
            tip_pool_id,
            period_date,
            total_tips_collected,
            poolable_tips: poolableTips,
            distribution_count: distribution.length,
        },
    });

    return apiSuccess({ allocation }, 201);
}

import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { parseJsonBody } from '@/lib/api/validation';
import { writeAuditLog } from '@/lib/api/audit';

const CreateTipPoolSchema = z.object({
    name: z.string().trim().min(1).max(120),
    name_am: z.string().trim().max(120).optional().nullable(),
    description: z.string().trim().max(500).optional().nullable(),
    is_active: z.boolean().optional().default(true),
    pool_type: z.enum(['percentage', 'fixed_amount']).default('percentage'),
    pool_value: z.number().int().min(0).default(0),
    calculated_from: z.enum(['tips', 'total']).default('tips'),
    valid_from: z.string().datetime().optional().nullable(),
    valid_until: z.string().datetime().optional().nullable(),
    allocation_mode: z.enum(['shift', 'daily', 'weekly']).default('shift'),
});

const _UpdateTipPoolSchema = CreateTipPoolSchema.partial();

const TipPoolShareSchema = z.object({
    role: z.enum([
        'server',
        'bartender',
        'host',
        'busser',
        'kitchen',
        'manager',
        'cook',
        'barista',
    ]),
    percentage: z.number().int().min(0).max(10000),
});

const CreateTipPoolWithSharesSchema = z.object({
    tip_pool: CreateTipPoolSchema,
    shares: z.array(TipPoolShareSchema).min(1),
});

export async function GET() {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p1' });
    if (!context.ok) {
        return context.response;
    }

    try {
        const db = context.supabase;

        // Get tip pools with their shares
        const { data: pools, error: poolsError } = await db
            .from('tip_pools')
            // HIGH-013: Explicit column selection
            .select(
                'id, restaurant_id, name, name_am, description, description_am, is_active, pool_type, pool_value, calculated_from, valid_from, valid_until, allocation_mode, created_by, created_at, updated_at'
            )
            .eq('restaurant_id', context.restaurantId)
            .order('created_at', { ascending: false });

        if (poolsError) {
            return apiError(
                'Failed to load tip pools',
                500,
                'TIP_POOL_FETCH_FAILED',
                poolsError.message
            );
        }

        if (!pools || pools.length === 0) {
            return apiSuccess({ tip_pools: [], shares: {} });
        }

        const poolIds = pools.map((p: { id: string }) => p.id);

        // Get shares for all pools
        const { data: shares, error: sharesError } = await db
            .from('tip_pool_shares')
            // HIGH-013: Explicit column selection
            .select('id, tip_pool_id, restaurant_id, role, percentage, created_at, updated_at')
            .in('tip_pool_id', poolIds)
            .order('role', { ascending: true });

        if (sharesError) {
            return apiError(
                'Failed to load tip pool shares',
                500,
                'TIP_POOL_SHARES_FETCH_FAILED',
                sharesError.message
            );
        }

        // Group shares by pool
        const sharesByPool: Record<string, Array<Record<string, unknown>>> = {};
        (shares ?? []).forEach((share: Record<string, unknown>) => {
            const tipPoolId = share.tip_pool_id as string;
            if (!sharesByPool[tipPoolId]) {
                sharesByPool[tipPoolId] = [];
            }
            sharesByPool[tipPoolId].push(share);
        });

        return apiSuccess({
            tip_pools: pools ?? [],
            shares: sharesByPool,
        });
    } catch (error) {
        return apiError(
            'Failed to load tip pools',
            500,
            'TIP_POOL_FETCH_FAILED',
            error instanceof Error ? error.message : 'Unknown error'
        );
    }
}

export async function POST(request: Request) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id, { phase: 'p1' });
    if (!context.ok) {
        return context.response;
    }

    const parsed = await parseJsonBody(request, CreateTipPoolWithSharesSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    const { tip_pool, shares } = parsed.data;

    // Validate shares total doesn't exceed 100%
    const totalPercentage = shares.reduce((sum, s) => sum + s.percentage, 0);
    if (totalPercentage > 10000) {
        return apiError('Total shares cannot exceed 100%', 400, 'TIP_POOL_SHARES_EXCEED_100');
    }

    const db = context.supabase;

    // Create the tip pool
    const { data: pool, error: poolError } = await db
        .from('tip_pools')
        .insert({
            restaurant_id: context.restaurantId,
            created_by: auth.user.id,
            ...tip_pool,
        })
        // HIGH-013: Explicit column selection
        .select(
            'id, restaurant_id, name, name_am, description, description_am, is_active, pool_type, pool_value, calculated_from, valid_from, valid_until, allocation_mode, created_by, created_at, updated_at'
        )
        .single();

    if (poolError || !pool) {
        return apiError(
            'Failed to create tip pool',
            500,
            'TIP_POOL_CREATE_FAILED',
            poolError?.message
        );
    }

    // Create shares
    const sharesData = shares.map(share => ({
        restaurant_id: context.restaurantId,
        tip_pool_id: pool.id,
        role: share.role,
        percentage: share.percentage,
    }));

    const { error: sharesError } = await db.from('tip_pool_shares').insert(sharesData);

    if (sharesError) {
        // Rollback pool creation
        await db.from('tip_pools').delete().eq('id', pool.id);
        return apiError(
            'Failed to create tip pool shares',
            500,
            'TIP_POOL_SHARES_CREATE_FAILED',
            sharesError.message
        );
    }

    await writeAuditLog(context.supabase, {
        restaurant_id: context.restaurantId,
        user_id: auth.user.id,
        action: 'tip_pool_created',
        entity_type: 'tip_pool',
        entity_id: pool.id,
        metadata: { name: pool.name, shares_count: shares.length },
    });

    return apiSuccess({ tip_pool: pool, shares }, 201);
}

/**
 * Waitlist Notify API Route
 *
 * Endpoint for notifying a guest that their table is ready.
 * - POST /api/waitlist/:id/notify
 */

import { apiError, apiSuccess } from '@/lib/api/response';
import { getAuthenticatedUser, getAuthorizedRestaurantContext } from '@/lib/api/authz';
import { writeAuditLog } from '@/lib/api/audit';
import { getWaitlistEntry, notifyGuest } from '@/lib/waitlist/service';
import { logger } from '@/lib/logger';

/**
 * Extract waitlist ID from request
 */
function getWaitlistId(params: { id: string }): string {
    return params.id;
}

/**
 * POST /api/waitlist/:id/notify
 * Notify a guest that their table is ready
 */
export async function POST(request: Request, { params }: { params: Promise<{ id: string }> }) {
    const auth = await getAuthenticatedUser();
    if (!auth.ok) {
        return auth.response;
    }

    const context = await getAuthorizedRestaurantContext(auth.user.id);
    if (!context.ok) {
        return context.response;
    }

    try {
        const resolvedParams = await params;
        const waitlistId = getWaitlistId(resolvedParams);

        // Get the waitlist entry
        const entry = await getWaitlistEntry(waitlistId);

        if (!entry) {
            return apiError('Waitlist entry not found', 404, 'WAITLIST_NOT_FOUND');
        }

        // Verify the entry belongs to the user's restaurant
        if (entry.restaurant_id !== context.restaurantId) {
            return apiError('Access denied', 403, 'ACCESS_DENIED');
        }

        // Check if already seated or cancelled
        if (entry.status === 'seated') {
            return apiError('Guest has already been seated', 400, 'ALREADY_SEATED');
        }

        if (entry.status === 'cancelled') {
            return apiError('Waitlist entry was cancelled', 400, 'ALREADY_CANCELLED');
        }

        // Send notification
        const result = await notifyGuest(waitlistId);

        if (!result.success) {
            return apiError(
                result.error ?? 'Failed to send notification',
                500,
                'NOTIFICATION_FAILED',
                result.error
            );
        }

        await writeAuditLog(context.supabase, {
            restaurant_id: context.restaurantId,
            user_id: auth.user.id,
            action: 'waitlist_notified',
            entity_type: 'waitlist_entry',
            entity_id: waitlistId,
            metadata: {
                guestName: entry.guest_name,
                guestPhone: entry.guest_phone,
                position: entry.position,
            },
        });

        return apiSuccess({
            message: 'Guest notified successfully',
            notification: {
                success: result.success,
                phone: result.phone,
                message: result.message,
            },
        });
    } catch (error) {
        logger.error('[waitlist] notify Error', error);
        return apiError(
            'Failed to notify guest',
            500,
            'NOTIFICATION_FAILED',
            error instanceof Error ? error.message : 'Unknown error'
        );
    }
}

