/**
 * POST /api/device/tables/bill-request
 * Mark a table as bill requested and create/update a bill service request.
 * Requires X-Device-Token header.
 */
import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getDeviceContext } from '@/lib/api/authz';
import { createServiceRoleClient } from '@/lib/supabase/service-role';
import { parseJsonBody } from '@/lib/api/validation';

const BillRequestSchema = z.object({
    table_id: z.string().uuid().optional(),
    table_number: z.string().trim().min(1).optional(),
    notes: z.string().trim().max(300).optional(),
});

export async function POST(request: Request) {
    const ctx = await getDeviceContext(request);
    if (!ctx.ok) return ctx.response;

    const parsed = await parseJsonBody(request, BillRequestSchema);
    if (!parsed.success) return parsed.response;

    const { table_id, table_number, notes } = parsed.data;
    if (!table_id && !table_number) {
        return apiError('table_id or table_number is required', 400, 'TABLE_SELECTOR_REQUIRED');
    }

    const admin = createServiceRoleClient();
    let tableQuery = admin
        .from('tables')
        .select('id, table_number, status')
        .eq('restaurant_id', ctx.restaurantId);

    if (table_id) {
        tableQuery = tableQuery.eq('id', table_id);
    } else if (table_number) {
        tableQuery = tableQuery.eq('table_number', table_number);
    }

    const { data: table, error: tableError } = await tableQuery.maybeSingle();
    if (tableError) {
        return apiError('Failed to fetch table', 500, 'TABLE_FETCH_FAILED', tableError.message);
    }
    if (!table) {
        return apiError('Table not found', 404, 'TABLE_NOT_FOUND');
    }

    const tableStatus = String(table.status ?? 'available');
    if (tableStatus === 'available') {
        return apiError(
            'Cannot request bill for an available table',
            409,
            'BILL_REQUEST_INVALID_TABLE_STATE'
        );
    }

    const now = new Date().toISOString();
    const { data: existingBillRequest } = await admin
        .from('service_requests')
        .select('id, status')
        .eq('restaurant_id', ctx.restaurantId)
        .eq('table_number', table.table_number)
        .eq('request_type', 'bill')
        .in('status', ['pending', 'acknowledged'])
        .order('created_at', { ascending: false })
        .limit(1)
        .maybeSingle();

    if (!existingBillRequest) {
        await admin.from('service_requests').insert({
            restaurant_id: ctx.restaurantId,
            table_number: table.table_number,
            request_type: 'bill',
            status: 'pending',
            notes: notes ?? 'Bill requested via waiter POS',
        });
    }

    const { error: tableUpdateError } = await admin
        .from('tables')
        .update({
            status: 'bill_requested',
            updated_at: now,
        })
        .eq('id', table.id)
        .eq('restaurant_id', ctx.restaurantId);

    if (tableUpdateError) {
        return apiError(
            'Failed to mark table as bill requested',
            500,
            'TABLE_BILL_REQUEST_UPDATE_FAILED',
            tableUpdateError.message
        );
    }

    return apiSuccess({
        table_id: table.id,
        table_number: table.table_number,
        status: 'bill_requested',
    });
}

/**
 * POST /api/device/tables/close
 * Settle a dine-in table and close its open table session.
 * Requires X-Device-Token header.
 *
 * IMPORTANT: This endpoint now publishes order.completed events to the
 * event bus instead of processing loyalty/ERCA synchronously. Background
 * jobs handle those side effects asynchronously.
 */
import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getDeviceContext } from '@/lib/api/authz';
import { createServiceRoleClient } from '@/lib/supabase/service-role';
import { parseJsonBody } from '@/lib/api/validation';
import { isChapaConfigured, verifyChapaTransaction } from '@/lib/services/chapaService';
import { ensurePaymentSessionForRecordedPayment } from '@/lib/payments/payment-sessions';
import { createloleEvent } from '@/lib/events/contracts';
import { enqueueInternalJob } from '@/lib/events/runtime';
import { logger } from '@/lib/logger';

const log = logger.child('close-table');

const CloseTableSchema = z.object({
    table_id: z.string().uuid().optional(),
    table_number: z.string().trim().min(1).optional(),
    payment: z.object({
        provider: z.enum(['cash', 'chapa', 'other']),
        tx_ref: z.string().trim().min(3).optional(),
        amount: z.number().nonnegative().optional(),
        tip_amount: z.number().nonnegative().optional().default(0),
    }),
    notes: z.string().trim().max(500).optional(),
});

const BLOCKING_ORDER_STATUSES = [
    'payment_pending',
    'pending',
    'acknowledged',
    'preparing',
] as const;
const FINALIZABLE_ORDER_STATUSES = ['ready', 'served'] as const;

export async function POST(request: Request) {
    const ctx = await getDeviceContext(request);
    if (!ctx.ok) return ctx.response;

    const parsed = await parseJsonBody(request, CloseTableSchema);
    if (!parsed.success) return parsed.response;

    const admin = createServiceRoleClient();
    const { table_id, table_number, payment, notes } = parsed.data;

    if (!table_id && !table_number) {
        return apiError('table_id or table_number is required', 400, 'TABLE_SELECTOR_REQUIRED');
    }

    let tableQuery = admin
        .from('tables')
        .select('id, table_number, status')
        .eq('restaurant_id', ctx.restaurantId);

    if (table_id) {
        tableQuery = tableQuery.eq('id', table_id);
    } else if (table_number) {
        tableQuery = tableQuery.eq('table_number', table_number);
    }

    const { data: table, error: tableError } = await tableQuery.maybeSingle();
    if (tableError) {
        return apiError('Failed to fetch table', 500, 'TABLE_FETCH_FAILED', tableError.message);
    }
    if (!table) {
        return apiError('Table not found', 404, 'TABLE_NOT_FOUND');
    }

    const { data: openSession, error: sessionError } = await admin
        .from('table_sessions')
        .select('id, notes')
        .eq('restaurant_id', ctx.restaurantId)
        .eq('table_id', table.id)
        .eq('status', 'open')
        .maybeSingle();

    const { data: tableOrders, error: ordersError } = await admin
        .from('orders')
        .select('id, status, total_price, chapa_tx_ref, paid_at, chapa_verified')
        .eq('restaurant_id', ctx.restaurantId)
        .eq('table_number', table.table_number)
        .in('status', [
            'payment_pending',
            'pending',
            'acknowledged',
            'preparing',
            'ready',
            'served',
        ]);

    if (sessionError) {
        return apiError(
            'Failed to resolve table session',
            500,
            'TABLE_SESSION_FETCH_FAILED',
            sessionError.message
        );
    }
    if (ordersError) {
        return apiError(
            'Failed to fetch table orders',
            500,
            'TABLE_ORDERS_FETCH_FAILED',
            ordersError.message
        );
    }

    let ensuredOpenSession = openSession;
    if (!ensuredOpenSession) {
        const { data: createdSession, error: createSessionError } = await admin
            .from('table_sessions')
            .insert({
                restaurant_id: ctx.restaurantId,
                table_id: table.id,
                guest_count: 1,
                status: 'open',
                notes: 'Auto-recovered during waiter settlement (missing legacy open session)',
            })
            .select('id, notes')
            .single();

        if (createSessionError) {
            if (createSessionError.code === '23505') {
                const { data: recoveredSession, error: recoverSessionError } = await admin
                    .from('table_sessions')
                    .select('id, notes')
                    .eq('restaurant_id', ctx.restaurantId)
                    .eq('table_id', table.id)
                    .eq('status', 'open')
                    .maybeSingle();
                if (recoverSessionError) {
                    return apiError(
                        'Failed to recover open table session',
                        500,
                        'TABLE_SESSION_RECOVERY_FAILED',
                        recoverSessionError.message
                    );
                }
                ensuredOpenSession = recoveredSession;
            } else {
                return apiError(
                    'Failed to auto-create open table session',
                    500,
                    'TABLE_SESSION_CREATE_FAILED',
                    createSessionError.message
                );
            }
        } else {
            ensuredOpenSession = createdSession;
        }
    }

    if (!ensuredOpenSession) {
        return apiError('Open table session not found', 409, 'TABLE_SESSION_NOT_OPEN');
    }

    const tableStatus = String(table.status ?? 'available');
    if (tableStatus !== 'bill_requested') {
        return apiError(
            'Table must be in bill requested state before settlement',
            409,
            'TABLE_NOT_BILL_REQUESTED'
        );
    }

    const activeOrders = tableOrders ?? [];
    const blockingOrders = activeOrders.filter(order =>
        BLOCKING_ORDER_STATUSES.includes(
            String(order.status) as (typeof BLOCKING_ORDER_STATUSES)[number]
        )
    );
    if (blockingOrders.length > 0) {
        return apiError(
            'Table has unpaid or in-progress orders. Complete prep/payment first.',
            409,
            'TABLE_CLOSE_BLOCKED',
            {
                blocking_order_ids: blockingOrders.map(order => order.id),
                blocking_statuses: [...new Set(blockingOrders.map(order => order.status))],
            }
        );
    }

    const settlementAmount = Number(
        activeOrders.reduce((sum, order) => sum + Number(order.total_price ?? 0), 0).toFixed(2)
    );

    if (activeOrders.length === 0) {
        const now = new Date().toISOString();
        const mergedCloseNotes =
            [ensuredOpenSession.notes, notes, 'Closed via waiter POS (no active orders)']
                .filter(Boolean)
                .join(' | ') || null;

        await Promise.all([
            admin
                .from('table_sessions')
                .update({
                    status: 'closed',
                    closed_at: now,
                    notes: mergedCloseNotes,
                    updated_at: now,
                })
                .eq('id', ensuredOpenSession.id)
                .eq('restaurant_id', ctx.restaurantId),
            admin
                .from('tables')
                .update({
                    status: 'available',
                    active_order_id: null,
                    updated_at: now,
                })
                .eq('id', table.id)
                .eq('restaurant_id', ctx.restaurantId),
            admin.from('audit_logs').insert({
                restaurant_id: ctx.restaurantId,
                user_id: null,
                action: 'waiter_table_closed',
                entity_type: 'table',
                entity_id: table.id,
                metadata: {
                    source: 'waiter_pos_device',
                    table_number: table.table_number,
                    session_id: ensuredOpenSession.id,
                    settled_amount: 0,
                },
            }),
        ]);

        return apiSuccess({
            table_id: table.id,
            table_number: table.table_number,
            closed_session_id: ensuredOpenSession.id,
            payment: null,
            completed_order_ids: [],
        });
    }

    if (settlementAmount <= 0) {
        return apiError(
            'No billable orders found for this table',
            409,
            'TABLE_CLOSE_NO_BILLABLE_ORDERS'
        );
    }

    if (typeof payment.amount === 'number') {
        const provided = Number(payment.amount.toFixed(2));
        if (Math.abs(provided - settlementAmount) > 0.01) {
            return apiError(
                `Settlement amount mismatch. Expected ${settlementAmount.toFixed(2)} ETB`,
                409,
                'TABLE_CLOSE_AMOUNT_MISMATCH'
            );
        }
    }

    const paymentProvider = payment.provider;
    const hasTxRef = Boolean(payment.tx_ref?.trim());
    if (paymentProvider === 'chapa' && hasTxRef) {
        if (isChapaConfigured()) {
            const verified = await verifyChapaTransaction(String(payment.tx_ref));
            const verifiedStatus = String(verified.data?.status ?? '').toLowerCase();
            if (verifiedStatus !== 'success') {
                return apiError(
                    'Chapa payment is not verified as successful',
                    409,
                    'CHAPA_PAYMENT_NOT_VERIFIED',
                    verified.data ?? null
                );
            }
        }
    } else if (paymentProvider === 'chapa') {
        const unpaidOrders = activeOrders.filter(
            order =>
                !order.paid_at ||
                order.chapa_verified !== true ||
                !String(order.chapa_tx_ref ?? '').trim()
        );
        if (unpaidOrders.length > 0) {
            return apiError(
                'Missing Chapa tx_ref. Some orders are not marked as paid via Chapa.',
                409,
                'TABLE_CLOSE_MISSING_TX_REF'
            );
        }
    }

    const now = new Date().toISOString();
    const finalizableOrders = activeOrders.filter(order =>
        FINALIZABLE_ORDER_STATUSES.includes(
            String(order.status) as (typeof FINALIZABLE_ORDER_STATUSES)[number]
        )
    );
    const finalizableOrderIds = finalizableOrders.map(order => order.id);

    const paymentSession = await ensurePaymentSessionForRecordedPayment(
        admin as unknown as Parameters<typeof ensurePaymentSessionForRecordedPayment>[0],
        {
            restaurantId: ctx.restaurantId,
            orderId: null,
            surface: ctx.device.device_type === 'terminal' ? 'terminal' : 'waiter_pos',
            channel: 'dine_in',
            method:
                paymentProvider === 'cash'
                    ? 'cash'
                    : paymentProvider === 'other'
                      ? 'other'
                      : paymentProvider,
            provider:
                paymentProvider === 'cash' || paymentProvider === 'other'
                    ? 'internal'
                    : paymentProvider,
            amount: settlementAmount,
            status: 'captured',
            metadata: {
                source: `${ctx.device.device_type}_close_table`,
                table_id: table.id,
                table_number: table.table_number,
                order_ids: activeOrders.map(order => order.id),
            },
        }
    );

    const { data: paymentRecord, error: paymentError } = await admin
        .from('payments')
        .insert({
            restaurant_id: ctx.restaurantId,
            order_id: null,
            payment_session_id: paymentSession.id,
            method: paymentProvider,
            provider:
                paymentProvider === 'cash' || paymentProvider === 'other'
                    ? 'internal'
                    : paymentProvider,
            provider_reference: payment.tx_ref?.trim() || null,
            amount: settlementAmount,
            tip_amount: Number((payment.tip_amount ?? 0).toFixed(2)),
            currency: 'ETB',
            status: 'captured',
            captured_at: now,
            metadata: {
                source: `${ctx.device.device_type}_close_table`,
                payment_session_id: paymentSession.id,
                table_id: table.id,
                table_number: table.table_number,
                order_ids: activeOrders.map(order => order.id),
                paid_order_tx_refs: activeOrders
                    .map(order => String(order.chapa_tx_ref ?? '').trim())
                    .filter(Boolean),
            },
            created_by: null,
        })
        .select('id, amount, provider_reference')
        .single();

    if (paymentError || !paymentRecord) {
        return apiError(
            'Failed to record settlement payment',
            500,
            'PAYMENT_RECORD_FAILED',
            paymentError?.message
        );
    }

    if (finalizableOrderIds.length > 0) {
        await admin
            .from('orders')
            .update({
                status: 'completed',
                completed_at: now,
                updated_at: now,
            })
            .in('id', finalizableOrderIds)
            .eq('restaurant_id', ctx.restaurantId);

        await admin.from('order_events').insert(
            finalizableOrders.map(order => ({
                restaurant_id: ctx.restaurantId,
                order_id: order.id,
                event_type: 'status_changed',
                from_status: String(order.status ?? 'ready'),
                to_status: 'completed',
                actor_user_id: null,
                metadata: {
                    source: 'waiter_pos_close_table',
                    payment_id: paymentRecord.id,
                    tx_ref: payment.tx_ref?.trim() || null,
                },
            }))
        );

        // Queue background jobs for each completed order
        // This removes synchronous cross-domain side effects (loyalty, ERCA, etc.)
        const jobQueuePromises = finalizableOrderIds.map(orderId =>
            enqueueInternalJob({
                path: '/api/jobs/orders/completed',
                body: createloleEvent('order.completed', {
                    order_id: orderId,
                    restaurant_id: ctx.restaurantId,
                    completed_at: now,
                    trigger: 'table_close',
                }) as unknown as Record<string, unknown>,
                deduplicationKey: `order-completed-${orderId}`,
            }).catch(err => {
                log.error(`Failed to queue job for order ${orderId}`, err);
                return undefined;
            })
        );

        // Fire and forget - don't block the response on job queuing
        Promise.all(jobQueuePromises).catch(() => {});
    }

    const mergedCloseNotes =
        [
            ensuredOpenSession.notes,
            notes,
            payment.tx_ref?.trim()
                ? `Settled via ${paymentProvider}: ${payment.tx_ref}`
                : `Settled via ${paymentProvider}`,
        ]
            .filter(Boolean)
            .join(' | ') || null;

    await Promise.all([
        admin
            .from('table_sessions')
            .update({
                status: 'closed',
                closed_at: now,
                notes: mergedCloseNotes,
                updated_at: now,
            })
            .eq('id', ensuredOpenSession.id)
            .eq('restaurant_id', ctx.restaurantId),
        admin
            .from('tables')
            .update({
                status: 'available',
                active_order_id: null,
                updated_at: now,
            })
            .eq('id', table.id)
            .eq('restaurant_id', ctx.restaurantId),
        admin.from('audit_logs').insert({
            restaurant_id: ctx.restaurantId,
            user_id: null,
            action: 'waiter_table_closed',
            entity_type: 'table',
            entity_id: table.id,
            metadata: {
                source: `${ctx.device.device_type}_device`,
                table_number: table.table_number,
                session_id: ensuredOpenSession.id,
                payment_id: paymentRecord.id,
                payment_session_id: paymentSession.id,
                tx_ref: payment.tx_ref,
                settled_amount: settlementAmount,
            },
        }),
    ]);

    return apiSuccess({
        table_id: table.id,
        table_number: table.table_number,
        closed_session_id: ensuredOpenSession.id,
        payment: paymentRecord,
        completed_order_ids: finalizableOrderIds,
    });
}

/**
 * POST /api/device/tables/ensure-open-session
 * Ensure an open table_session exists for a table in device mode.
 * Requires X-Device-Token header.
 */
import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { getDeviceContext } from '@/lib/api/authz';
import { createServiceRoleClient } from '@/lib/supabase/service-role';
import { parseJsonBody } from '@/lib/api/validation';

const EnsureOpenSessionSchema = z.object({
    table_id: z.string().uuid().optional(),
    table_number: z.string().trim().min(1).optional(),
    notes: z.string().trim().max(300).optional(),
});

export async function POST(request: Request) {
    const ctx = await getDeviceContext(request);
    if (!ctx.ok) return ctx.response;

    const parsed = await parseJsonBody(request, EnsureOpenSessionSchema);
    if (!parsed.success) return parsed.response;

    const { table_id, table_number, notes } = parsed.data;
    if (!table_id && !table_number) {
        return apiError('table_id or table_number is required', 400, 'TABLE_SELECTOR_REQUIRED');
    }

    const admin = createServiceRoleClient();
    let tableQuery = admin
        .from('tables')
        .select('id, table_number')
        .eq('restaurant_id', ctx.restaurantId);

    if (table_id) {
        tableQuery = tableQuery.eq('id', table_id);
    } else if (table_number) {
        tableQuery = tableQuery.eq('table_number', table_number);
    }

    const { data: table, error: tableError } = await tableQuery.maybeSingle();
    if (tableError) {
        return apiError('Failed to fetch table', 500, 'TABLE_FETCH_FAILED', tableError.message);
    }
    if (!table) {
        return apiError('Table not found', 404, 'TABLE_NOT_FOUND');
    }

    const { data: existingOpen, error: existingError } = await admin
        .from('table_sessions')
        .select('id, status, opened_at')
        .eq('restaurant_id', ctx.restaurantId)
        .eq('table_id', table.id)
        .eq('status', 'open')
        .maybeSingle();

    if (existingError) {
        return apiError(
            'Failed to check open table session',
            500,
            'TABLE_SESSION_FETCH_FAILED',
            existingError.message
        );
    }

    if (existingOpen) {
        return apiSuccess({
            table_id: table.id,
            table_number: table.table_number,
            session: existingOpen,
            created: false,
        });
    }

    const { data: created, error: createError } = await admin
        .from('table_sessions')
        .insert({
            restaurant_id: ctx.restaurantId,
            table_id: table.id,
            guest_count: 1,
            status: 'open',
            notes: notes ?? 'Auto-opened from waiter settlement recovery',
        })
        .select('id, status, opened_at')
        .single();

    if (createError) {
        if (createError.code === '23505') {
            const { data: racedOpen, error: racedOpenError } = await admin
                .from('table_sessions')
                .select('id, status, opened_at')
                .eq('restaurant_id', ctx.restaurantId)
                .eq('table_id', table.id)
                .eq('status', 'open')
                .maybeSingle();

            if (racedOpenError || !racedOpen) {
                return apiError(
                    'Failed to recover open table session',
                    500,
                    'TABLE_SESSION_RECOVERY_FAILED',
                    racedOpenError?.message ?? createError.message
                );
            }

            return apiSuccess({
                table_id: table.id,
                table_number: table.table_number,
                session: racedOpen,
                created: false,
            });
        }

        return apiError(
            'Failed to create open table session',
            500,
            'TABLE_SESSION_CREATE_FAILED',
            createError.message
        );
    }

    return apiSuccess({
        table_id: table.id,
        table_number: table.table_number,
        session: created,
        created: true,
    });
}

/**
 * GET /api/device/tables
 * Device-authenticated endpoint for POS/KDS to fetch tables.
 * Requires X-Device-Token header (set after pairing).
 * No Supabase auth session needed.
 */
import { apiError, apiSuccess } from '@/lib/api/response';
import { getDeviceContext } from '@/lib/api/authz';
import { createServiceRoleClient } from '@/lib/supabase/service-role';

export async function GET(request: Request) {
    const ctx = await getDeviceContext(request);
    if (!ctx.ok) return ctx.response;

    const admin = createServiceRoleClient();

    const { data, error } = await admin
        .from('tables')
        .select(
            'id, restaurant_id, table_number, capacity, status, active_order_id, section, created_at, updated_at'
        )
        .eq('restaurant_id', ctx.restaurantId)
        .order('table_number');

    if (error) {
        return apiError('Failed to fetch tables', 500, 'TABLES_FETCH_FAILED', error.message);
    }

    return apiSuccess({ tables: data ?? [] });
}

import { apiError, apiSuccess } from '@/lib/api/response';
import { getScopedDeviceContext } from '@/lib/api/authz';
import { getPaymentOptionsForSurface, normalizeDeviceMetadata } from '@/lib/devices/config';
import { createServiceRoleClient } from '@/lib/supabase/service-role';

const ACTIVE_ORDER_STATUSES = ['pending', 'acknowledged', 'preparing', 'ready', 'served'];

export async function GET(request: Request) {
    const ctx = await getScopedDeviceContext(request, ['terminal']);
    if (!ctx.ok) return ctx.response;

    const admin = createServiceRoleClient();
    const [tablesResult, ordersResult] = await Promise.all([
        admin
            .from('tables')
            .select('id, table_number, status, updated_at')
            .eq('restaurant_id', ctx.restaurantId)
            .order('table_number'),
        admin
            .from('orders')
            .select('id, table_number, order_number, status, total_price, created_at')
            .eq('restaurant_id', ctx.restaurantId)
            .in('status', ACTIVE_ORDER_STATUSES)
            .order('created_at', { ascending: false }),
    ]);

    if (tablesResult.error) {
        return apiError(
            'Failed to fetch terminal tables',
            500,
            'TERMINAL_TABLES_FETCH_FAILED',
            tablesResult.error.message
        );
    }

    if (ordersResult.error) {
        return apiError(
            'Failed to fetch terminal orders',
            500,
            'TERMINAL_ORDERS_FETCH_FAILED',
            ordersResult.error.message
        );
    }

    const tables = tablesResult.data ?? [];
    const orders = ordersResult.data ?? [];
    const deviceMetadata = normalizeDeviceMetadata(
        'terminal',
        (ctx.device.metadata ?? undefined) as Record<string, unknown> | undefined
    );

    const orderTotalsByTable = new Map<string, number>();
    const orderCountsByTable = new Map<string, number>();

    for (const order of orders) {
        const tableNumber = String(order.table_number ?? '').trim();
        if (!tableNumber) continue;
        orderTotalsByTable.set(
            tableNumber,
            Number(
                (
                    (orderTotalsByTable.get(tableNumber) ?? 0) + Number(order.total_price ?? 0)
                ).toFixed(2)
            )
        );
        orderCountsByTable.set(tableNumber, (orderCountsByTable.get(tableNumber) ?? 0) + 1);
    }

    const terminalTables = tables
        .filter(table => {
            const status = String(table.status ?? 'available');
            return (
                status !== 'available' || orderTotalsByTable.has(String(table.table_number ?? ''))
            );
        })
        .map(table => ({
            ...table,
            outstanding_total: orderTotalsByTable.get(String(table.table_number ?? '')) ?? 0,
            active_order_count: orderCountsByTable.get(String(table.table_number ?? '')) ?? 0,
        }));

    return apiSuccess({
        device: {
            id: ctx.device.id,
            name: ctx.device.name,
            device_type: ctx.device.device_type,
            device_profile: ctx.device.device_profile ?? 'cashier',
            assigned_zones: ctx.device.assigned_zones,
            last_active_at: ctx.device.last_active_at,
            metadata: deviceMetadata,
        },
        payment_options: getPaymentOptionsForSurface('terminal').filter(option =>
            (deviceMetadata.allowed_payment_methods ?? []).includes(option.method)
        ),
        tables: terminalTables,
        orders,
    });
}

/**
 * Notification Processor Cron Job
 *
 * CRIT-11: Queue-based notification processor via event bus
 *
 * This endpoint should be called by a cron scheduler every minute.
 * It processes pending notifications from the queue and cleans up old processed notifications.
 *
 * @see docs/implementation/CRITICAL_IMPLEMENTATION_STRATEGY.md - CRIT-11
 */

import { NextRequest, NextResponse } from 'next/server';
import { processQueue, getQueueStats, type ProcessResult } from '@/lib/notifications/queue';
import { clearOldEntries } from '@/lib/notifications/deduplication';
import { createServiceRoleClient } from '@/lib/supabase/service-role';
import { logger } from '@/lib/logger';

const log = logger.child('notification-processor');

/**
 * Cron secret validation
 */
function validateCronSecret(request: NextRequest): boolean {
    const authHeader = request.headers.get('authorization');
    const cronSecret = process.env.CRON_SECRET;

    if (!cronSecret) {
        log.warn('CRON_SECRET not configured');
        return false;
    }

    return authHeader === `Bearer ${cronSecret}`;
}

/**
 * Clean up old processed notifications
 */
async function cleanupOldNotifications(olderThanDays: number = 7): Promise<number> {
    const supabase = createServiceRoleClient();
    const cutoffDate = new Date(Date.now() - olderThanDays * 24 * 60 * 60 * 1000).toISOString();

    // Delete old sent/cancelled notifications
    const { data, error } = await supabase
        .from('notification_queue')
        .delete()
        .in('status', ['sent', 'cancelled'])
        .lt('created_at', cutoffDate);

    if (error) {
        log.error('Failed to cleanup old notifications', error);
        return 0;
    }

    return Array.isArray(data) ? (data as unknown[]).length : 0;
}

/**
 * POST /api/jobs/cron/notification-processor
 *
 * Processes pending notifications and cleans up old records.
 * Should be called by Vercel Cron or external scheduler every minute.
 *
 * Headers:
 * - Authorization: Bearer <CRON_SECRET>
 *
 * Query params:
 * - limit: Max notifications to process (default: 50)
 * - cleanup_days: Days to keep sent/cancelled notifications (default: 7)
 */
export async function POST(request: NextRequest) {
    const startTime = Date.now();

    // Validate cron secret
    if (!validateCronSecret(request)) {
        return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    try {
        // Parse optional config from query params
        const { searchParams } = new URL(request.url);
        const limit = parseInt(searchParams.get('limit') || '50', 10);
        const cleanupDays = parseInt(searchParams.get('cleanup_days') || '7', 10);

        log.info('Starting notification processing', {
            limit,
            cleanupDays,
        });

        // Get queue stats before processing
        const statsBefore = await getQueueStats();

        // Process pending notifications
        const processResult: ProcessResult = await processQueue(limit);

        // Get queue stats after processing
        const statsAfter = await getQueueStats();

        // Clean up old notifications
        const cleanedUp = await cleanupOldNotifications(cleanupDays);

        // Clear old deduplication entries
        const dedupCleared = await clearOldEntries(cleanupDays * 24);

        const duration = Date.now() - startTime;

        log.info('Processing complete', {
            duration: `${duration}ms`,
            processed: processResult.processed,
            sent: processResult.sent,
            failed: processResult.failed,
            retried: processResult.retried,
            cleanedUp,
            dedupCleared,
            statsBefore,
            statsAfter,
        });

        return NextResponse.json({
            success: true,
            timestamp: new Date().toISOString(),
            duration_ms: duration,
            processing: {
                processed: processResult.processed,
                sent: processResult.sent,
                failed: processResult.failed,
                retried: processResult.retried,
                errors: processResult.errors.length > 0 ? processResult.errors : undefined,
            },
            cleanup: {
                notifications_deleted: cleanedUp,
                dedup_entries_cleared: dedupCleared,
            },
            queue_stats: {
                before: statsBefore,
                after: statsAfter,
            },
        });
    } catch (error) {
        log.error('Error', error);

        return NextResponse.json(
            {
                success: false,
                error: error instanceof Error ? error.message : 'Unknown error',
                timestamp: new Date().toISOString(),
            },
            { status: 500 }
        );
    }
}

/**
 * GET /api/jobs/cron/notification-processor
 *
 * Health check endpoint for the cron job.
 * Returns queue statistics.
 */
export async function GET(_request: NextRequest) {
    try {
        // Get queue stats
        const stats = await getQueueStats();

        return NextResponse.json({
            status: 'healthy',
            endpoint: 'notification-processor',
            timestamp: new Date().toISOString(),
            queue_stats: stats,
        });
    } catch (error) {
        return NextResponse.json(
            {
                status: 'unhealthy',
                error: error instanceof Error ? error.message : 'Unknown error',
                timestamp: new Date().toISOString(),
            },
            { status: 500 }
        );
    }
}

/**
 * Stale Device Check Cron Job
 *
 * CRIT-05: Scheduled job to detect and alert on stale devices
 *
 * This endpoint should be called by a cron scheduler every 5-10 minutes.
 * It checks for devices that haven't synced within the configured threshold
 * and sends alerts to the operations team.
 *
 * @see docs/implementation/CRITICAL_IMPLEMENTATION_STRATEGY.md - CRIT-05
 */

import { NextRequest, NextResponse } from 'next/server';
import { runStaleDeviceDetection, StaleDeviceConfig } from '@/lib/sync/stale-device-monitor';
import { sendInfoAlert } from '@/lib/monitoring/alerts';
import { logger } from '@/lib/logger';

const log = logger.child('stale-device-check');

/**
 * Cron secret validation
 */
function validateCronSecret(request: NextRequest): boolean {
    const authHeader = request.headers.get('authorization');
    const cronSecret = process.env.CRON_SECRET;

    if (!cronSecret) {
        log.warn('CRON_SECRET not configured');
        return false;
    }

    return authHeader === `Bearer ${cronSecret}`;
}

/**
 * POST /api/jobs/cron/stale-device-check
 *
 * Runs stale device detection and sends alerts.
 * Should be called by Vercel Cron or external scheduler.
 *
 * Headers:
 * - Authorization: Bearer <CRON_SECRET>
 *
 * Query params:
 * - warning_threshold: Minutes before warning alert (default: 30)
 * - critical_threshold: Minutes before critical alert (default: 60)
 * - business_hours_only: Only alert during business hours (default: true)
 */
export async function POST(request: NextRequest) {
    const startTime = Date.now();

    // Validate cron secret
    if (!validateCronSecret(request)) {
        return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    try {
        // Parse optional config from query params
        const { searchParams } = new URL(request.url);
        const config: StaleDeviceConfig = {
            warningThresholdMinutes: parseInt(searchParams.get('warning_threshold') || '30', 10),
            criticalThresholdMinutes: parseInt(searchParams.get('critical_threshold') || '60', 10),
            businessHoursOnly: searchParams.get('business_hours_only') !== 'false',
            maxDevicesPerRun: 100,
        };

        log.info('Starting detection with config', {
            warningThreshold: config.warningThresholdMinutes,
            criticalThreshold: config.criticalThresholdMinutes,
            businessHoursOnly: config.businessHoursOnly,
        });

        // Run detection
        const result = await runStaleDeviceDetection(config);

        const duration = Date.now() - startTime;

        // Log summary
        log.info('Detection complete', {
            duration: `${duration}ms`,
            checked: result.checked,
            warning: result.warningDevices.length,
            critical: result.criticalDevices.length,
            alertsSent: result.alertsSent,
            errors: result.errors.length,
        });

        // Send summary alert if there were critical devices
        if (result.criticalDevices.length > 0) {
            await sendInfoAlert('Stale device check completed', {
                critical_devices: result.criticalDevices.length,
                warning_devices: result.warningDevices.length,
                alerts_sent: result.alertsSent,
                duration_ms: duration,
            });
        }

        return NextResponse.json({
            success: true,
            timestamp: new Date().toISOString(),
            duration_ms: duration,
            summary: {
                checked: result.checked,
                warning_devices: result.warningDevices.length,
                critical_devices: result.criticalDevices.length,
                alerts_sent: result.alertsSent,
            },
            errors: result.errors.length > 0 ? result.errors : undefined,
        });
    } catch (error) {
        log.error('Error', error);

        return NextResponse.json(
            {
                success: false,
                error: error instanceof Error ? error.message : 'Unknown error',
                timestamp: new Date().toISOString(),
            },
            { status: 500 }
        );
    }
}

/**
 * GET /api/jobs/cron/stale-device-check
 *
 * Health check endpoint for the cron job.
 */
export async function GET(_request: NextRequest) {
    // Allow GET for health checks without auth
    return NextResponse.json({
        status: 'healthy',
        endpoint: 'stale-device-check',
        timestamp: new Date().toISOString(),
    });
}

