/**
 * POST /api/v1/system/sync
 * Process a batch of sync operations from client
 */
export async function POST(request: NextRequest) {
    const startTime = Date.now();

    // Authenticate request
    const authContext = await getSyncAuthContext(request);
    if (!authContext.ok) {
        return authContext.response as ReturnType<typeof apiError>;
    }

    const { restaurantId, userId, deviceId } = authContext;

    // Parse and validate request body
    const parsed = await parseJsonBody(request, SyncRequestSchema);
    if (!parsed.success) {
        return parsed.response;
    }

    const { operations, clientId, lastSyncAt } = parsed.data;

    logger.info('[SyncAPI] Processing sync request', {
        restaurantId,
        userId,
        deviceId,
        clientId,
        operationCount: operations.length,
        lastSyncAt,
    });

    // Process each operation
    const results: SyncOperationResult[] = [];

    for (const op of operations) {
        // Verify all operations are for the same restaurant
        if (op.restaurantId !== restaurantId) {
            results.push({
                id: op.id,
                success: false,
                error: 'Tenant isolation violation - operation restaurant_id does not match authenticated restaurant',
            });
            continue;
        }

        const result = await processSyncOperation(op, restaurantId);
        results.push(result);
    }

    const successCount = results.filter(r => r.success).length;
    const failureCount = results.filter(r => !r.success).length;
    const conflictCount = results.filter(r => r.conflict?.detected).length;

    logger.info('[SyncAPI] Sync request completed', {
        restaurantId,
        clientId,
        totalOperations: operations.length,
        successCount,
        failureCount,
        conflictCount,
        durationMs: Date.now() - startTime,
    });

    return apiSuccess({
        results,
        summary: {
            total: operations.length,
            succeeded: successCount,
            failed: failureCount,
            conflicts: conflictCount,
        },
        processedAt: new Date().toISOString(),
    });
}

/**
 * GET /api/v1/system/sync
 * Get sync status and pending changes since last sync
 */
export async function GET(request: NextRequest) {
    const startTime = Date.now();

    // Authenticate request
    const authContext = await getSyncAuthContext(request);
    if (!authContext.ok) {
        return authContext.response as ReturnType<typeof apiError>;
    }

    const { restaurantId } = authContext;

    // Parse query parameters
    const { searchParams } = new URL(request.url);
    const queryParams = {
        restaurantId: searchParams.get('restaurantId') || undefined,
        since: searchParams.get('since') || undefined,
        limit: searchParams.get('limit') || '50',
    };

    const parsedQuery = SyncStatusQuerySchema.safeParse(queryParams);
    if (!parsedQuery.success) {
        return apiError(
            'Invalid query parameters',
            400,
            'INVALID_QUERY',
            parsedQuery.error.flatten()
        );
    }

    const { since, limit } = parsedQuery.data;

    const admin = createServiceRoleClient();

    // Get counts of changed records since last sync
    const sinceFilter = since || new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(); // Default 24h

    // Get order changes
    const { count: ordersChanged } = await admin
        .from('orders')
        .select('*', { count: 'exact', head: true })
        .eq('restaurant_id', restaurantId)
        .gte('updated_at', sinceFilter);

    // Get order items changes
    const { count: orderItemsChanged } = await admin
        .from('order_items')
        .select('*', { count: 'exact', head: true })
        .eq('restaurant_id', restaurantId)
        .gte('updated_at', sinceFilter);

    // Get KDS items changes
    const { count: kdsItemsChanged } = await admin
        .from('kds_order_items')
        .select('*', { count: 'exact', head: true })
        .eq('restaurant_id', restaurantId)
        .gte('updated_at', sinceFilter);

    const { count: timeEntriesChanged } = await admin
        .from('time_entries')
        .select('*', { count: 'exact', head: true })
        .eq('restaurant_id', restaurantId)
        .gte('updated_at', sinceFilter);

    const { count: tipAllocationsChanged } = await admin
        .from('tip_allocations')
        .select('*', { count: 'exact', head: true })
        .eq('restaurant_id', restaurantId)
        .gte('updated_at', sinceFilter);

    // Get recent sync operations for this restaurant
    const { data: recentSyncOps, error: syncOpsError } = await admin
        .from('sync_idempotency_keys')
        .select('id, idempotency_key, processed_at')
        .eq('restaurant_id', restaurantId)
        .gte('processed_at', sinceFilter)
        .order('processed_at', { ascending: false })
        .limit(limit);

    if (syncOpsError) {
        logger.error('[SyncAPI] Error fetching sync status', { error: syncOpsError, restaurantId });
        return apiError('Failed to fetch sync status', 500, 'SYNC_STATUS_ERROR');
    }

    logger.info('[SyncAPI] Sync status retrieved', {
        restaurantId,
        since: sinceFilter,
        durationMs: Date.now() - startTime,
    });

    return apiSuccess({
        restaurantId,
        since: sinceFilter,
        changes: {
            orders: ordersChanged || 0,
            orderItems: orderItemsChanged || 0,
            kdsItems: kdsItemsChanged || 0,
            timeEntries: timeEntriesChanged || 0,
            tipAllocations: tipAllocationsChanged || 0,
        },
        recentSyncOperations: recentSyncOps || [],
        serverTime: new Date().toISOString(),
    });
}

import { NextRequest } from 'next/server';
import {
    parseChapaWebhook,
    publishPaymentWebhookEvent,
    verifyChapaWebhookSignature,
} from '@/lib/payments/webhooks';
import { apiSuccess, apiError } from '@/lib/api/response';

export async function GET() {
    // Chapa browser redirects may still hit old callback expectations.
    // We acknowledge the request but only POST deliveries trigger state changes.
    return apiSuccess({ received: true, ignored: true });
}

export async function POST(request: NextRequest) {
    try {
        const rawBody = await request.text();
        const signature = request.headers.get('x-chapa-signature');

        if (!verifyChapaWebhookSignature(rawBody, signature)) {
            return apiError('Invalid Chapa webhook signature', 401, 'INVALID_SIGNATURE');
        }

        const parsed = parseChapaWebhook(rawBody, request.nextUrl.searchParams);
        const published = await publishPaymentWebhookEvent(parsed);

        return apiSuccess({
            received: true,
            event_id: published.eventId,
            job_message_id: published.jobMessageId ?? null,
        });
    } catch (error) {
        return apiError(
            'Failed to process Chapa webhook',
            500,
            'WEBHOOK_PROCESSING_FAILED',
            error instanceof Error ? error.message : 'Unknown webhook error'
        );
    }
}

import { NextRequest } from 'next/server';
import { createClient } from '@/lib/supabase/server';
import { apiError, apiSuccess } from '@/lib/api/response';
import { writeAuditLog } from '@/lib/api/audit';
import { AggregatorService } from '@/lib/delivery/aggregator';
import { getStoreGatewayService } from '@/lib/gateway/service';
import { z } from 'zod';
import type { Json } from '@/types/database';
import { logger } from '@/lib/logger';

const log = logger.child('webhooks/delivery');

/**
 * Inbound Webhook Endpoint for Delivery Partners
 *
 * POST /api/webhooks/delivery
 *
 * Receives order webhooks from external delivery partners (Beu, Zmall, Deliver Addis, etc.)
 * and normalizes them into the external_orders table.
 *
 * Headers:
 * - X-Provider: The delivery provider (beu, zmall, deliver_addis, telebirr_food, esoora, custom_local)
 * - X-API-Key: The integration API key for the restaurant
 * - X-Signature: HMAC signature of the payload (optional, for verification)
 */

// Webhook payload schema (flexible to accommodate different providers)
const WebhookPayloadSchema = z.object({
    // Standard fields
    order_id: z.string().optional(),
    external_order_id: z.string().optional(),
    customer_name: z.string().optional(),
    customer_phone: z.string().optional(),
    total: z.number().optional(),
    total_amount: z.number().optional(),
    currency: z.string().default('ETB'),
    items: z.array(z.unknown()).optional(),
    delivery_address: z.any().optional(),
    notes: z.string().optional(),
    status: z.string().optional(),
    created_at: z.string().optional(),
    // Allow additional provider-specific fields
    metadata: z.record(z.string(), z.unknown()).optional(),
});

type WebhookPayload = z.infer<typeof WebhookPayloadSchema>;

// Provider configurations
const PROVIDER_CONFIGS = {
    beu: {
        name: 'Beu',
        color: '#FF6B00', // Orange
        orderPrefix: 'BEU',
    },
    zmall: {
        name: 'Zmall',
        color: '#00A651', // Green
        orderPrefix: 'ZML',
    },
    deliver_addis: {
        name: 'Deliver Addis',
        color: '#2196F3', // Blue
        orderPrefix: 'DA',
    },
    telebirr_food: {
        name: 'Telebirr Food',
        color: '#EAB308', // Amber
        orderPrefix: 'TBF',
    },
    esoora: {
        name: 'Esoora',
        color: '#9C27B0', // Purple
        orderPrefix: 'ESR',
    },
    custom_local: {
        name: 'Custom Local',
        color: '#607D8B', // Grey
        orderPrefix: 'LOC',
    },
} as const;

type Provider = keyof typeof PROVIDER_CONFIGS;

function createDeliveryAggregatorService() {
    return new AggregatorService({
        publishLocalEvent: async event => {
            const gateway = getStoreGatewayService();
            if (!gateway) {
                return;
            }

            await gateway.publishCommand({
                type: event.type,
                aggregate: event.aggregate,
                aggregateId: event.aggregateId,
                payload: event.payload,
                restaurantId: event.restaurantId,
                locationId: event.locationId,
            });
        },
    });
}

/**
 * Normalize order status from different providers to our standard status
 */
function normalizeStatus(status: string | undefined): string {
    const statusMap: Record<string, string> = {
        // Common statuses
        pending: 'pending',
        new: 'pending',
        confirmed: 'confirmed',
        accepted: 'confirmed',
        preparing: 'preparing',
        cooking: 'preparing',
        ready: 'ready',
        picked_up: 'picked_up',
        on_the_way: 'on_the_way',
        delivered: 'delivered',
        completed: 'delivered',
        cancelled: 'cancelled',
        canceled: 'cancelled',
        rejected: 'rejected',
    };

    return statusMap[status?.toLowerCase() ?? 'pending'] ?? 'pending';
}

/**
 * Generate a unique provider order ID if not provided
 */
function generateProviderOrderId(provider: Provider): string {
    const prefix = PROVIDER_CONFIGS[provider].orderPrefix;
    const timestamp = Date.now().toString(36).toUpperCase();
    const random = Math.random().toString(36).substring(2, 6).toUpperCase();
    return `${prefix}-${timestamp}-${random}`;
}

export async function POST(request: NextRequest) {
    const startTime = Date.now();

    // Extract headers
    const provider = request.headers.get('X-Provider')?.toLowerCase() as Provider | null;
    const apiKey = request.headers.get('X-API-Key');
    // Signature validation can be added later for enhanced security
    // const signature = request.headers.get('X-Signature');

    // Validate provider
    if (!provider || !PROVIDER_CONFIGS[provider]) {
        return apiError(
            'Invalid or missing X-Provider header. Supported: beu, zmall, deliver_addis, telebirr_food, esoora, custom_local',
            400,
            'INVALID_PROVIDER'
        );
    }

    // Validate API key
    if (!apiKey) {
        return apiError('Missing X-API-Key header', 401, 'MISSING_API_KEY');
    }

    // Parse and validate payload
    let payload: WebhookPayload;
    try {
        const body = await request.json();
        const parsed = WebhookPayloadSchema.safeParse(body);
        if (!parsed.success) {
            return apiError(
                'Invalid webhook payload',
                400,
                'INVALID_PAYLOAD',
                parsed.error.flatten()
            );
        }
        payload = parsed.data;
    } catch {
        return apiError('Failed to parse request body', 400, 'INVALID_JSON');
    }

    const supabase = await createClient();

    // Find restaurant by API key
    // The API key should be stored in delivery_partners.credentials_ref or settings_json
    const { data: partner, error: partnerError } = await supabase
        .from('delivery_partners')
        .select('id, restaurant_id, settings_json, credentials_ref')
        .eq('provider', provider)
        .eq('status', 'connected')
        .maybeSingle();

    if (partnerError) {
        log.error('Failed to query delivery partner', partnerError);
        return apiError('Internal server error', 500, 'DATABASE_ERROR');
    }

    if (!partner) {
        return apiError(
            'No active delivery partner found for this provider',
            404,
            'PARTNER_NOT_FOUND'
        );
    }

    // Validate API key against stored credentials
    const settings = partner.settings_json as Record<string, unknown> | null;
    const storedApiKey = (settings?.api_key as string) ?? partner.credentials_ref;

    if (!storedApiKey || storedApiKey !== apiKey) {
        await writeAuditLog(supabase, {
            restaurant_id: partner.restaurant_id,
            action: 'webhook_auth_failed',
            entity_type: 'delivery_partner',
            entity_id: partner.id,
            metadata: {
                provider,
                reason: 'invalid_api_key',
            },
        });

        return apiError('Invalid API key', 401, 'INVALID_API_KEY');
    }

    // Generate or extract order ID
    const providerOrderId =
        payload.order_id ?? payload.external_order_id ?? generateProviderOrderId(provider);
    const totalAmount = payload.total ?? payload.total_amount ?? 0;
    const normalizedStatus = normalizeStatus(payload.status);

    // Check for duplicate order
    const { data: existingOrder } = await supabase
        .from('external_orders')
        .select('id, provider_order_id')
        .eq('restaurant_id', partner.restaurant_id)
        .eq('provider', provider)
        .eq('provider_order_id', providerOrderId)
        .maybeSingle();

    if (existingOrder) {
        // Update existing order instead of creating duplicate
        const { data: updatedOrder, error: updateError } = await supabase
            .from('external_orders')
            .update({
                normalized_status: normalizedStatus,
                payload_json: payload as unknown as Json,
                updated_at: new Date().toISOString(),
            })
            .eq('id', existingOrder.id)
            .select()
            .single();

        if (updateError) {
            log.error('Failed to update external order', updateError);
            return apiError('Failed to update order', 500, 'UPDATE_FAILED');
        }

        return apiSuccess({
            message: 'Order updated',
            order_id: updatedOrder.id,
            provider_order_id: providerOrderId,
            status: normalizedStatus,
            duplicate: true,
        });
    }

    // Create new external order
    const { data: newOrder, error: createError } = await supabase
        .from('external_orders')
        .insert({
            restaurant_id: partner.restaurant_id,
            delivery_partner_id: partner.id,
            provider: provider,
            provider_order_id: providerOrderId,
            source_channel: provider,
            normalized_status: normalizedStatus,
            total_amount: totalAmount,
            currency: payload.currency ?? 'ETB',
            payload_json: payload as unknown as Json,
        })
        .select()
        .single();

    if (createError) {
        log.error('Failed to create external order', createError);
        return apiError('Failed to create order', 500, 'CREATE_FAILED', createError.message);
    }

    const aggregatorService = createDeliveryAggregatorService();
    const aggregatorResult = await aggregatorService.receiveAndBroadcastOrder(
        supabase as never,
        partner.restaurant_id,
        partner.id,
        {
            external_order_id: providerOrderId,
            external_order_number: payload.external_order_id ?? undefined,
            raw_order_data: payload as unknown as Record<string, unknown>,
            customer_name: payload.customer_name ?? undefined,
            customer_phone: payload.customer_phone ?? undefined,
            delivery_address:
                typeof payload.delivery_address === 'string' ? payload.delivery_address : undefined,
            delivery_notes: payload.notes ?? undefined,
            items: Array.isArray(payload.items)
                ? payload.items.flatMap(item => {
                      if (!item || typeof item !== 'object') {
                          return [];
                      }

                      const candidate = item as Record<string, unknown>;
                      const name =
                          typeof candidate.name === 'string'
                              ? candidate.name
                              : typeof candidate.item_name === 'string'
                                ? candidate.item_name
                                : 'Unknown Item';
                      const quantity = Number(candidate.quantity ?? 1);
                      const price = Number(
                          candidate.price ?? candidate.unit_price ?? candidate.total_price ?? 0
                      );
                      const notes =
                          typeof candidate.notes === 'string'
                              ? candidate.notes
                              : typeof candidate.special_instructions === 'string'
                                ? candidate.special_instructions
                                : undefined;

                      return [
                          {
                              name,
                              quantity: Number.isFinite(quantity) && quantity > 0 ? quantity : 1,
                              price: Number.isFinite(price) ? price : 0,
                              ...(notes ? { notes } : {}),
                          },
                      ];
                  })
                : [],
            subtotal: totalAmount,
            delivery_fee: 0,
            platform_fee: 0,
            total: totalAmount,
            placed_at: payload.created_at ?? undefined,
        }
    );

    if (!aggregatorResult.success && aggregatorResult.error !== 'Order already exists') {
        log.error('Failed to inject webhook order into aggregator runtime', undefined, aggregatorResult);
    }

    // Check if auto-accept is enabled
    const { data: restaurant } = await supabase
        .from('restaurants')
        .select('settings')
        .eq('id', partner.restaurant_id)
        .maybeSingle();

    const settings2 = (restaurant?.settings ?? {}) as Record<string, unknown>;
    const channels = (settings2.channels ?? {}) as Record<string, unknown>;
    const onlineOrdering = (channels.online_ordering ?? {}) as Record<string, unknown>;
    const autoAccept = onlineOrdering.auto_accept_orders === true;

    // Log the webhook
    await writeAuditLog(supabase, {
        restaurant_id: partner.restaurant_id,
        action: 'external_order_received',
        entity_type: 'external_order',
        entity_id: newOrder.id,
        metadata: {
            provider,
            provider_order_id: providerOrderId,
            total_amount: totalAmount,
            currency: payload.currency ?? 'ETB',
            status: normalizedStatus,
            auto_accept: autoAccept,
            runtime_injected:
                aggregatorResult.success || aggregatorResult.error === 'Order already exists',
            aggregator_order_id: aggregatorResult.order?.id ?? null,
            processing_time_ms: Date.now() - startTime,
        },
    });

    // Return success response
    return apiSuccess(
        {
            message: 'Order received successfully',
            order_id: newOrder.id,
            provider_order_id: providerOrderId,
            status: normalizedStatus,
            auto_accepted: autoAccept,
            runtime_injected:
                aggregatorResult.success || aggregatorResult.error === 'Order already exists',
            aggregator_order_id: aggregatorResult.order?.id ?? null,
            processing_time_ms: Date.now() - startTime,
        },
        201
    );
}

import { timingSafeEqual } from 'crypto';
import { z } from 'zod';
import { apiError, apiSuccess } from '@/lib/api/response';
import { createServiceRoleClient } from '@/lib/supabase/service-role';
import { sendOrderStatusSms } from '@/lib/notifications/sms';

const GuestOrderStatusSchema = z.object({
    eventType: z.string(),
    details: z.object({
        orderGuid: z.string().uuid(),
        guestOrderStatus: z.enum(['IN_PREPARATION', 'READY_FOR_PICKUP', 'CLOSED', 'VOIDED']),
        lastUpdated: z.string().datetime().optional(),
    }),
});

function verifySharedSecret(headerValue: string | null, expectedSecret: string): boolean {
    if (!headerValue) return false;

    const expected = Buffer.from(expectedSecret, 'utf8');
    const received = Buffer.from(headerValue, 'utf8');
    if (expected.length !== received.length) return false;

    try {
        return timingSafeEqual(expected, received);
    } catch {
        return expectedSecret === headerValue;
    }
}

function mapGuestOrderStatusToInternalStatus(guestOrderStatus: string) {
    if (guestOrderStatus === 'IN_PREPARATION') return 'preparing';
    if (guestOrderStatus === 'READY_FOR_PICKUP') return 'ready';
    if (guestOrderStatus === 'CLOSED') return 'served';
    return 'cancelled';
}

export async function POST(request: Request) {
    const configuredSecret = process.env.GUEST_ORDER_STATUS_WEBHOOK_SECRET;
    if (configuredSecret) {
        const headerSecret =
            request.headers.get('x-webhook-secret') ??
            request.headers.get('x-guest-webhook-secret');
        if (!verifySharedSecret(headerSecret, configuredSecret)) {
            return apiError('Invalid webhook secret', 401, 'INVALID_WEBHOOK_SECRET');
        }
    }

    const body = await request.json().catch(() => null);
    const parsed = GuestOrderStatusSchema.safeParse(body);
    if (!parsed.success) {
        return apiError('Invalid webhook payload', 400, 'INVALID_PAYLOAD', parsed.error.flatten());
    }

    if (parsed.data.eventType !== 'guestOrderStatusUpdated') {
        return apiError('Unsupported eventType', 400, 'UNSUPPORTED_EVENT_TYPE');
    }

    const admin = createServiceRoleClient();
    const orderId = parsed.data.details.orderGuid;
    const guestOrderStatus = parsed.data.details.guestOrderStatus;
    const mappedStatus = mapGuestOrderStatusToInternalStatus(guestOrderStatus);

    const { data: existingOrder, error: orderFetchError } = await admin
        .from('orders')
        .select('id, restaurant_id, status, customer_phone, order_number')
        .eq('id', orderId)
        .maybeSingle();

    if (orderFetchError) {
        return apiError(
            'Failed to resolve order',
            500,
            'ORDER_LOOKUP_FAILED',
            orderFetchError.message
        );
    }
    if (!existingOrder) {
        return apiError('Order not found', 404, 'ORDER_NOT_FOUND');
    }

    if (existingOrder.status === mappedStatus) {
        return apiSuccess({
            accepted: true,
            updated: false,
            order_id: existingOrder.id,
            status: existingOrder.status,
        });
    }

    const { error: updateError } = await admin
        .from('orders')
        .update({
            status: mappedStatus,
            updated_at: new Date().toISOString(),
        })
        .eq('id', existingOrder.id);

    if (updateError) {
        return apiError('Failed to update order', 500, 'ORDER_UPDATE_FAILED', updateError.message);
    }

    const { data: restaurantSettings } = await admin
        .from('restaurants')
        .select('settings')
        .eq('id', existingOrder.restaurant_id)
        .maybeSingle();
    const notificationsSettings = (restaurantSettings?.settings as Record<string, unknown> | null)
        ?.notifications as Record<string, unknown> | undefined;
    const smsEnabled = Boolean(notificationsSettings?.sms_enabled);

    const smsPromise =
        smsEnabled && existingOrder.customer_phone
            ? sendOrderStatusSms({
                  toPhone: existingOrder.customer_phone,
                  orderNumber: existingOrder.order_number ?? existingOrder.id,
                  status: mappedStatus,
              })
            : Promise.resolve({ success: false, provider: 'log' as const, skipped: true });

    await Promise.all([
        admin.from('order_events').insert({
            restaurant_id: existingOrder.restaurant_id,
            order_id: existingOrder.id,
            event_type: 'status_changed',
            from_status: existingOrder.status,
            to_status: mappedStatus,
            actor_user_id: null,
            metadata: {
                source: 'guest_order_status_webhook',
                guest_order_status: guestOrderStatus,
                webhook_last_updated: parsed.data.details.lastUpdated ?? null,
            },
        }),
        admin.from('audit_logs').insert({
            restaurant_id: existingOrder.restaurant_id,
            action: 'guest_order_status_webhook_received',
            entity_type: 'order',
            entity_id: existingOrder.id,
            metadata: {
                guest_order_status: guestOrderStatus,
                mapped_status: mappedStatus,
            },
            old_value: { status: existingOrder.status },
            new_value: { status: mappedStatus },
        }),
        smsPromise,
    ]);

    return apiSuccess({
        accepted: true,
        updated: true,
        order_id: existingOrder.id,
        previous_status: existingOrder.status,
        status: mappedStatus,
    });
}

/**
 * Telebirr Webhook Handler
 *
 * Handles payment callbacks from Telebirr mobile money service.
 * Verifies signature and updates payment status.
 */

import { NextRequest } from 'next/server';
import { verifyTelebirrWebhookSignature } from '@/lib/payments/telebirr';
import { createAuditedServiceRoleClient } from '@/lib/supabase/service-role';
import { logger } from '@/lib/logger';
import { apiSuccess, apiError } from '@/lib/api/response';

export async function POST(request: NextRequest) {
    const startTime = Date.now();

    try {
        // Get raw body for signature verification
        const rawBody = await request.text();
        const signature = request.headers.get('x-telebirr-sign') ?? '';

        // Verify webhook signature
        const appKey = process.env.TELEBIRR_APP_KEY;
        if (!appKey) {
            logger.error('[TelebirrWebhook] TELEBIRR_APP_KEY not configured');
            return apiError('Webhook not configured', 500, 'TELEBIRR_NOT_CONFIGURED');
        }

        const isValid = verifyTelebirrWebhookSignature(rawBody, signature, appKey);
        if (!isValid) {
            logger.warn('[TelebirrWebhook] Invalid signature', {
                signature: signature.substring(0, 10) + '...',
            });
            return apiError('Invalid signature', 401, 'INVALID_SIGNATURE');
        }

        // Parse the payload
        const payload = JSON.parse(rawBody) as {
            outTradeNo: string;
            tradeNo: string;
            tradeStatus: string;
            totalAmount: string;
            currency: string;
            buyerId?: string;
            timestamp?: string;
        };

        logger.info('[TelebirrWebhook] Received payment callback', {
            outTradeNo: payload.outTradeNo,
            tradeStatus: payload.tradeStatus,
        });

        // Map Telebirr status to our status
        let paymentStatus: 'pending' | 'success' | 'failed' | 'cancelled';
        switch (payload.tradeStatus) {
            case 'TRADE_SUCCESS':
            case 'TRADE_FINISHED':
                paymentStatus = 'success';
                break;
            case 'TRADE_CLOSED':
                paymentStatus = 'cancelled';
                break;
            case 'WAIT_BUYER_PAY':
            default:
                paymentStatus = 'pending';
        }

        // Update payment record using audited service role client
        const supabase = createAuditedServiceRoleClient('telebirr_webhook', {
            metadata: {
                tradeNo: payload.tradeNo,
                outTradeNo: payload.outTradeNo,
            },
        });

        // Find payment by transaction reference
        const { data: payment, error: findError } = await supabase
            .from('payments')
            .select('id, order_id, restaurant_id')
            .eq('provider_reference', payload.outTradeNo)
            .maybeSingle();

        if (findError) {
            logger.error('[TelebirrWebhook] Error finding payment', findError);
            return apiError('Database error', 500, 'DB_ERROR', findError.message);
        }

        if (!payment) {
            logger.warn('[TelebirrWebhook] Payment not found', {
                outTradeNo: payload.outTradeNo,
            });
            // Return success to prevent retries for unknown payments
            return apiSuccess({ received: true });
        }

        // Update payment status
        const { error: updateError } = await supabase
            .from('payments')
            .update({
                status: paymentStatus,
                provider_transaction_id: payload.tradeNo,
                metadata: {
                    buyerId: payload.buyerId,
                    telebirrTimestamp: payload.timestamp,
                    rawCallback: payload,
                },
                updated_at: new Date().toISOString(),
            })
            .eq('id', payment.id);

        if (updateError) {
            logger.error('[TelebirrWebhook] Error updating payment', updateError);
            return apiError(
                'Failed to update payment',
                500,
                'PAYMENT_UPDATE_FAILED',
                updateError.message
            );
        }

        // If payment successful, update order status
        if (paymentStatus === 'success' && payment.order_id) {
            const { error: orderUpdateError } = await supabase
                .from('orders')
                .update({
                    payment_status: 'paid',
                    status: 'confirmed',
                    updated_at: new Date().toISOString(),
                })
                .eq('id', payment.order_id);

            if (orderUpdateError) {
                logger.error('[TelebirrWebhook] Error updating order', orderUpdateError);
                // Don't fail the webhook - payment was updated successfully
            }
        }

        const duration = Date.now() - startTime;
        logger.info('[TelebirrWebhook] Payment processed', {
            outTradeNo: payload.outTradeNo,
            status: paymentStatus,
            durationMs: duration,
        });

        return apiSuccess({ received: true });
    } catch (error) {
        const duration = Date.now() - startTime;
        logger.error('[TelebirrWebhook] Error processing webhook', {
            error: error instanceof Error ? error.message : 'Unknown error',
            durationMs: duration,
        });

        return apiError(
            'Internal server error',
            500,
            'INTERNAL_ERROR',
            error instanceof Error ? error.message : 'Unknown error'
        );
    }
}

// Only allow POST requests
export async function GET() {
    return apiError('Method not allowed', 405, 'METHOD_NOT_ALLOWED');
}

